quests[66001] = { id = 66001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine letzte Hoffnung", sourceObjective = "Rettet das letzte energieerfüllte Drachenei.", completion = "Ist das...?", sourceObjectiveStatus = "unverified-source-field" }
quests[66003] = { id = 66003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ringe, sie zu binden", description = "Die Djaradin hier sind wagemutig geworden. Sie haben Flammenelementare gebunden und lassen sie durch die Gegend wüten. Die Wildtiere sind geflohen, und die Elementare sind unseren Lagern gefährlich nahe.\n\nZum Glück konnte ich eine kleine steinerne Bastion errichten, um diese feurige Flut, die die Djaradin entfesselt haben, standzuhalten... Und wir werden nicht scheitern!\n\nSammelt die magischen Ringe ein, die diese Flammenelementare binden. Wir werden die Ringe verwenden, um unsere Verteidigung gegen sie zu verstärken.", sourceObjective = "Sammelt 12 geschmolzene Fesselringe.", progress = "Habt Ihr alle Ringe gesammelt, um die ich gebeten habe?", completion = "Perfekt! Die Restenergien dieser Ringe können gegen ihre Erschaffer verwendet werden, um ein Konstrukt unter unserer Kontrolle zu beschwören!", sourceObjectiveStatus = "unverified-source-field" }
quests[66004] = { id = 66004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galgresh" }
quests[66005] = { id = 66005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medaillon einer gefallenen Freundin", description = "<Dieser zerkaute Metallbrocken war einst ein wunderschönes und bedeutendes Ornament der Zentauren der Shikaar.\n\nKhasar könnte mehr über seinen Besitzer wissen.>", sourceObjective = "Bringt das Medaillon einer gefallenen Freundin zu Khasar zurück.\n\nBereitgestellter Gegenstand:", completion = "Dieses Medaillon ist alles, was von einer lieben Freundin zurückblieb, die sich in der letzten Saison zu weit in den Sumpf gewagt hat. Ich glaubte es an die Elemente verloren.\n\nIch schnitt dieses Leder aus ihrem ersten erlegten Mammut. Wir waren damals noch Kinder.", sourceObjectiveStatus = "unverified-source-field" }
quests[66006] = { id = 66006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Roscha", description = "Baba konnte sich ausruhen und Roschas Vorräte sind wieder da. Wir können zurückkehren, ohne sie zusätzlich aufzuregen.\n\nNehmt einige Kisten mit, wenn Ihr geht. Den Rest werde ich von unseren Kriegern abholen lassen.", sourceObjective = "Bringt die Vorräte zu Hufschmiedin Roscha zurück.", completion = "Ihr habt die Vorräte? Gut.\n\nLasst sie bei der Schmiede.\n\n<Roscha sieht sich um und runzelt die Stirn.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66007] = { id = 66007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Luft ist rein", description = "Die Primalisten halten Kalecgos mithilfe dieser massiven Kugeln fern.\n\nWenn das so weitergeht, wird Kalecgos noch verletzt. Sollte er scheitern, kann er Raszageth nicht mehr bekämpfen.\n\nMithilfe Eures ermächtigten Edelsteins müsstet Ihr Euch als Elementar tarnen können, um vorzuschleichen.\n\nVernichtet die Kugeln mit ihm. Dann müsste Kalecgos seine Macht entfesseln können.\n\nIch werde mich darauf konzentrieren, den Turm vor Raszageth zu beschützen.", sourceObjective = "Zerstört 4 Lavaleuchtfeuer.", completion = "Habt Dank, {name}. Es ist an der Zeit, den Primalisten zu zeigen, welche Macht wirklich im Aspekt des blauen Drachenschwarms steckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[66009] = { id = 66009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Verteidigung Vakthros'", description = "Es ist Zeit, {name}. Die Streitkräfte der Primalisten in der Luft schwinden, jetzt, wo Ihr die Situation am Boden unter Kontrolle gebracht habt.\n\nRaszageth hat nach einem ihrer Leutnants gerufen, um die Truppen der Primalisten zu verstärken, dank Eurer Anstrengungen.\n\nIhr müsst Euch um dieses Monster kümmern, während ich weiter gegen Raszageth vordringe und Khadgar helfe.\n\nHaltet die Augen nach meiner Magie offen, während Ihr kämpft. Ich werde tun, was ich kann, um Euch zu helfen.\n\nEs ist Zeit, dass Raszageth den Zorn des Aspekts der Magie zu spüren bekommt!", sourceObjective = "Besiegt Korthrox den Zerstörer.", completion = "Gut, Euch zu sehen. Die Zeit drängt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66011] = { id = 66011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Gedenken an Ysera", description = "Oh nein! Ich glaube, ich verstehe ihn jetzt. Theramus... er vermisst Ysera und sie kann nicht zurückkehren.\n\nKommt! Ich kann mir vorstellen, wohin er gegangen ist. Wir werden ihn nicht weiter belästigen, aber es wäre gut, ihm zu sagen, dass es uns leidtut und dass wir ihm den Abstand geben, den er braucht.\n\nWir sind füreinander da, inmitten der Natur, die uns umgibt.", sourceObjective = "Findet Theramus erneut.", progress = "Wir wissen es zu schätzen, dass Ihr bei uns bleibt, {race}. Ihr seid uns eine große Hilfe.", completion = "<Theramus blickt in aller Stille auf den jüngst wiederhergestellten Schrein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66012] = { id = 66012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die versiegelte Tür", description = "Unsere Späher haben die Dracheninseln nach irgendetwas Interessantem durchkämmt. Sie sind mit vielen Erkenntnissen zurückgekehrt, aber eine Entdeckung übertrifft alle anderen... eine Tür.\n\nEine Tür, geschmiedet von den Titanen und gegen die Welt versiegelt. Niemandem ist es bis jetzt gelungen, einen Weg zu den Artefakten zu finden, die sicherlich auf der anderen Seite warten.\n\nAber andererseits hat noch kein Mysterium dem scharfsinnigen Blick der Archäologischen Akademie lange standgehalten.\n\nMit der Hilfe der Forscherliga wird diese Herausforderung bestimmt ein Klacks, dessen bin ich mir sicher.", sourceObjective = "Reist zur versiegelten Tür in Thaldraszus und sprecht mit Naleidea.", completion = "Für jemandem von Eurem Kaliber war die Reise vermutlich ein Kinderspiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[66013] = { id = 66013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersucht die Tür", description = "Da wären wir. Wenn wir an dieser Tür vorbeikommen wollen, müssen wir herausfinden, wer sie verschlossen hat und wie.\n\nSeht Euch in der Umgebung nach etwas um, das uns die Antworten auf unsere Fragen geben könnte.", sourceObjective = "Durchsucht die Umgebung nach Hinweisen.", progress = "Welch eine interessante Entdeckung. Was glaubt Ihr, liegt auf der anderen Seite?", completion = "Wir brauchen mehr als das hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[66015] = { id = 66015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwurstein der blauen Drachen", description = "Das Azurblaue Gebirge hat sich fürs Erste stabilisiert, und immer mehr blaue Drachen sind aufgetaucht... genau im rechten Moment.\n\nEs ist Zeit, in die Azurarchive zurückzukehren und den Schwurstein wieder zu beanspruchen.\n\nIch möchte, dass Ihr auch anwesend seid, {name}. Ihr wart während dieser Tortur eine große Bereicherung.", sourceObjective = "Begleitet Kalecgos, um den Schwurstein der blauen Drachen zu beanspruchen.", completion = "Der Schwurstein wurde ein weiteres Mal ermächtigt. Es gibt viel zu tun... aber zumindest kehrt das Azurblaue Gebirge zu seinem früheren Zustand zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[66016] = { id = 66016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klan Teerai", description = "<Während Sansok Khan in Gebärden spricht, formuliert Okir die Worte.>\n\nKlan Teerai ist der Klan unserer Khanam Matra, unsere direkte Verbindung zu den Vorfahren der Maruuk. Sie bewahren unsere Traditionen und erzählen unsere Geschichten.\n\nUm die Maruuk zu verstehen, müsst Ihr den Klan Teerai verstehen. Eine der Töchter der Khanam Matra, Qariin Dotur, bereitet ein Mahl für unsere Ahnen vor. Helft ihr. Sie wird Euch über unser Volk lehren.", sourceObjective = "Meldet Euch bei Qariin Dotur.", completion = "Willkommen, Fremdling.", sourceObjectiveStatus = "unverified-source-field" }
quests[66017] = { id = 66017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klan Ohn'ir", description = "<Während Sansok Khan in Gebärden spricht, formuliert Okir die Worte.>\n\nDie Mystiker unserer Länder, so wie Ohn Seshteng, gehören zum Klan Ohn'ir. Der Klan besteht nicht aus Familien, sondern eher aus Zentauren aus allen Teilen der Ebenen mit einer angeborenen Verbindung zu Ohn'ahra. Sie verbringen ihr Leben damit, diese Verbindung zu pflegen und ihre Fähigkeiten zu perfektionieren. Letztendlich erhalten sie Anweisungen, um unterschiedliche Klans zu beraten und unsere Länder zu beschützen.\n\nOhn Seshteng ging, um mit ihrem Khan über das Omen zu sprechen, das sie erhalten hat. Schließt Euch ihr an, um mehr über die Ohn'ir zu erfahren.", sourceObjective = "Trefft Ohn Seshteng bei den Mystikerbecken.", completion = "Es ist gut, wieder bei meinem Klan zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[66018] = { id = 66018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klan Nokhud", description = "<Während Sansok Khan in Gebärden spricht, formuliert Okir die Worte.>\n\nKlan Nokhud ist als neuester an die Macht gekommen. Ihr verstorbener Khan, Jhakan, hat eine mächtige Armee aufgestellt, um sich Gebiete von ihren Vorgängern anzueignen. Das ist der Brauch unseres Volkes.\n\nWährend Jhakan sich Respekt verdient hat, trifft das nicht auf seinen Sohn zu. Balakar hat seinen Vater getötet und die Kontrolle über den Klan ergriffen. Seitdem sind sie noch engstirniger geworden. Aber um die Maruuk zu verstehen, müsst Ihr sie verstehen.", sourceObjective = "Begleitet Tomul zu Wache Bahir.", completion = "Es ist mir absolut keine Freude, Euch Bahir vorzustellen, einen der Schläger von Balakar Khan.", sourceObjectiveStatus = "unverified-source-field" }
quests[66019] = { id = 66019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Ahnen ehren", description = "Unsere Ahnen schreiten an unserer Seite auf den Winden von Ohn'ahra, sie führen und beschützen uns. Alle Maruuk, tote und lebendige, versammeln sich unter einem Waffenstillstand am Khural.\n\nDer Geruch dieses Mahls ruft unsere Vorfahren zu unserem Feuer. Wenn sie kommen, beginnt der Khural.", sourceObjective = "Helft Qariin Dotur dabei, ein Mahl für die Ahnen vorzubereiten.", progress = "Die Maruuk kehren seit Generationen zu diesem Ort zurück. Wir schreiten Seite an Seite mit unseren Ahnen.", completion = "Unsere Ahnen haben für unsere Zukunft viel riskiert. Es ist nur richtig, sie dazu einzuladen, sich an unserer Seite zu versammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[66020] = { id = 66020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omen und Räucherwerk", description = "Ich erzählte Tigari Khan vom Omen, das wir erhalten hatten, bevor wir Maruukai betraten. Sie äußerte ihre Bedenken, da sich der Wind auch für sie kalt anfühlte.\n\nWir kultivieren hier bestimmte Blumen. Wir nehmen ihre Blüten und zerkleinern und verbrennen sie, um eine tranceähnliche Wirkung zu erzeugen. So vertiefen wir unsere Verbindung zu den Omen.\n\nIch bitte Euch, solche Blumen zu sammeln, damit wir mit ihnen ein Räucherwerk machen können. Vielleicht erfahren wir mithilfe meiner Khan mehr über Ohn'ahras Not.", sourceObjective = "Sammelt 5 Süßnuckelblüten, mahlt sie zu Süßnuckelräucherwerk und helft dann Ohn Seshteng beim Ritual.", progress = "Tigari Khan ist sehr versiert im Lesen von Omen. Mit ihrer Hilfe können wir mehr über dieses Omen erfahren.", completion = "Ohn'ahra selbst droht Verrat. Wir müssen Ruhe bewahren, {name}. Jetzt ist die Zeit für Verbündete.", sourceObjectiveStatus = "unverified-source-field" }
quests[66021] = { id = 66021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwillkommener Fremdling", description = "Hah! Seht Euch an. Schwach. So wie diese mickrigen Jäger, die Euch hergebracht haben.\n\nIhr möchtet die Nokhud kennenlernen? Unsere Sprache ist der Kampf. \n\n\"Der Tabarr\", so nennt sich unser Kampfritual. Wir trainieren. Wir üben. Dadurch werden wir hart. Nun gibt es keine Schwäche in unserem Klan.\n\nSchon zu viele Worte. Geht, übt.", sourceObjective = "Besiegt 6 Zentauren der Nokhud.", completion = "Für die Nokhud gehen bloße Stärke und Macht über alles.\n\nWir sind in vielen Dingen nicht einer Meinung.", sourceObjectiveStatus = "unverified-source-field" }
quests[66022] = { id = 66022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Khanam Matra", description = "Ich kann nicht in den Gebieten der Zentauren bleiben, ich muss so schnell wie möglich in die Gärten zurückkehren.\n\nDie Khanam Matra hat zugestimmt, unser Hilfegesuch anzuhören. Sie erwartet meine Ankunft oben auf dem Krutal, dem zentralen Gebäude von Maruukai.\n\nAuch wenn ich zunächst mit ihr alleine sprechen muss, seid Ihr herzlich eingeladen, Euch uns anzuschließen.", sourceObjective = "Berichtet Khanswache Akoto, um an Gemisaths Audienz mit der Khanam Matra teilzunehmen.", progress = "Die Khanam Matra erwartet Euch.", completion = "Dieser verräterische Dummkopf.\n\n<Akato spuckt auf den Boden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66023] = { id = 66023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffenstillstand gebrochen", description = "Balakar bringt Schande über seinen Klan. Er führt sie in einen Sturm, geblendet durch seine Gier nach Macht.\n\nIhr Betrug enthüllt ihre Schwäche. Macht sie nieder.", sourceObjective = "Tötet 10 Streitkräfte der Nokhud.", completion = "Der Pfad, für den sie sich entschieden haben, ist jetzt mit Blut getränkt.\n\nSpäherin Tomul hat versucht, uns zu warnen, dass dies passieren könnte. Sie hat vielleicht noch weitere Vermutungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66024] = { id = 66024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Rücken freihalten", description = "Die Nokhud sind vernarrt in die uralten Kriegsgeschichten unseres Volkes. Eigentlich sind sie schwache, herumalbernde Kinder. Und blitzartig haben sie ihre Verbindung zu Ohn'ahra durchtrennt.\n\nNun! Wenn sie den Weg der Verderbnis einschlagen, um Krieg zu beginnen, so werden wir ihnen entgegenkommen.\n\nNatürlich behielt Bahir das Kommando, um seine Flucht zu decken. Ihr Blut wird schon bald den Boden tränken.", sourceObjective = "Tötet Wache Bahir.", progress = "<Sarest überblickt mit verengten Augen das Schlachtfeld.>", completion = "Balakar war ein leichtes Ziel für Koroleths verderbenden Einfluss.\n\nDer Sturm ist hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[66025] = { id = 66025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung der Nokhud", description = "Klan Nokhuds Armee nimmt Maruukai ein.\n\nLasst uns unsere nächsten Schritte in den Kammern des Khans besprechen. Wir müssen für die Sicherheit der Maruuk sorgen.", sourceObjective = "Besprecht die nächsten Schritte.", completion = "Das Lebensblut der Maruuk ist in Gefahr.", sourceObjectiveStatus = "unverified-source-field" }
quests[66026] = { id = 66026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelles Handeln ist geboten", description = "Der Grund für diese Angriffe muss in den Brackenfellgnollen selbst zu finden sein.\n\nWir kämpfen seit Generationen gegen sie, aber normalerweise sind sie nicht mehr als lästige Fliegen.\n\nUns bleibt keine andere Wahl, als direkt zu handeln. Diese Fäulnis wird sonst das Gleichgewicht im Azurblauen Gebirge zerstören, inklusive dessen, was Ihr sucht.\n\nTrefft uns außerhalb von Brackenfell. Wir werden jede Hilfe brauchen können, die wir bekommen.", sourceObjective = "Trefft Brena bei Brackenfell.", completion = "Ich spüre den Schrecken dieses Waldes über mich hereinbrechen, wenn ich nur hier stehe. Irgendetwas ist hier ganz und gar falsch.\n\nIch bereue langsam, unsere beste Kämpferin zurück nach Iskaara geschickt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[66027] = { id = 66027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf an die blauen Drachen", description = "Ich kann mich nicht länger davor fürchten, die blauen Drachen zu vereinen, {name}. Es ist besser für uns, eine Familie zu sein, als... nur ein Schatten unseres einstigen Selbst.\n\nSelbst wenn ich den Schwurstein nicht wieder beanspruchen kann, werde ich seine Macht dennoch nutzen können, um eine Nachricht an alle blauen Drachen zu senden.\n\nEs ist Zeit, dass sie... von ihrem Aspekt zu hören bekommen.", sourceObjective = "Seht zu, wie Kalecgos den blauen Drachenschwarm zusammenruft.", progress = "Bleibt zurück, {name}.", completion = "Wir müssen hier weg, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66028] = { id = 66028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Zukunft!", description = "Ich habe Chronormus und Eternus' Spur in eine potenzielle Zukunft verfolgt. Ich weiß nicht, was Ihr dort finden werdet, nur, dass sie dunkel und chaotisch ist.\n\nSoridormi hat einige unserer Zeitwanderer vorweg in diese Zukunft gebracht, um unsere Verbindung zu dieser Zeit aufrechtzuerhalten. Ihre beträchtliche Macht wird benötigt, um das Portal offen zu halten, sie wird sich also auf Eure Hilfe verlassen müssen.\n\nSoridormi kann Euch weitere Anweisungen geben, wenn Ihr sie aufsucht.\n\nBeeilt Euch, {name}. Findet Chronormu.", sourceObjective = "Reist in die Zukunft der Primalisten.", completion = "Wir müssen Chromie und Eternus finden, bevor diese Zeit noch mehr Schaden erleiden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[66029] = { id = 66029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temporalabstimmung", description = "Chronormu und Eternus fallen durch die Zeit, aber ich spüre, dass sie hin und wieder anhalten. Diese kurzen Momente sind unsere Gelegenheit, sie zu finden.\n\n<Nozdormu beschwört einen kleinen Chronokristall herbei.>\n\nIch habe diesen Kristall mit meiner Macht sowie meiner eigenen Zeitresonanz erfüllt. Sie sind in eine... beunruhigende potenzielle Zukunft geraten. Findet sie und nutzt ihn. Hoffentlich könnt Ihr damit ihre temporale Position fixieren, bevor sie uns wieder entgleiten.", sourceObjective = "Wendet den Chronokristall in der Zukunft der Primalisten auf Eternus und Chromie an, um zu verhindern, dass sie weiter durch die Zeit fallen.", completion = "Der Prozess war noch nicht abgeschlossen, aber ich kann Chronormu jetzt genauer verfolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66030] = { id = 66030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerstand ist nicht zwecklos", description = "Die temporalen Wellen haben den Leuten hier Probleme bereitet. Feinde tauchen auf, wo sie zuvor nicht waren, oder sind viel mächtiger, als sie sein sollten. Diese Veränderungen sind recht klein, aber verheerend.\n\nIch bitte Euch, den Widerstandskämpfern hier zu helfen. Heilt ihre Wunden, damit sie weiterkämpfen können. Setzt ihre Zeitlinien auf die richtigen Pfade zurück, so als hätten sie nie mit unserer interagiert. Es ist nicht viel, aber es ist alles, was wir für sie tun können.", sourceObjective = "Heilt Widerstandskämpfer in der Zukunft der Primalisten.", progress = "Habt Ihr den Widerstand unterstützt?", completion = "Diese mutigen Kämpfer werden ihre Kräfte noch einmal verstärken können.", sourceObjectiveStatus = "unverified-source-field" }
quests[66031] = { id = 66031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit verschaffen", description = "Ich schätze, es sollte mich nicht überraschen, hier zu sein.\n\nDas ist nicht das Azeroth, das ich wollte, aber es ist das, was ich bekommen habe. Wir kämpfen dafür, das zu erhalten, was noch übrig ist, und dafür, unsere Welt zurückzubekommen... Aber Eure Ankunft hat für etwas Ärger gesorgt.\n\nWir nutzen die Essenz dieser Elementare da draußen für unseren Schutz. Seht Ihr diesen Schild? Das ist das Einzige, das uns davor bewahrt, entdeckt und vernichtet zu werden, und Ihr habt uns unserer Ressourcen beraubt. Bringt uns etwas von dieser Essenz zurück, dann überleben wir womöglich einen weiteren Tag.", sourceObjective = "Sammelt Elementaressenz für das Überlebendenlager.", progress = "Habt Ihr gesammelt, was wir brauchen?", completion = "Ihr habt uns etwas Raum zum Atmen verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[66032] = { id = 66032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr in die Gegenwart", description = "Diese Zeitlinie ist düster und chaotisch. Die Störung hier war schwerwiegend. Ich werde eine Weile in dieser Zeitlinie bleiben und mich um die verbleibenden Wellen kümmern, die erscheinen könnten.\n\nKehrt zu Nozdormu zurück. Er wird von Eurem Erfolg erfahren wollen, auch wenn er weniger umfassend war, als wir es uns gewünscht hatten.", sourceObjective = "Kehrt zu Nozdormu in die Gegenwart zurück.", completion = "Eure Reise hat unsere Ziele nicht erreicht, aber ein Erfolg war sie dennoch.", sourceObjectiveStatus = "unverified-source-field" }
quests[66033] = { id = 66033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die... Vergangenheit?", description = "Es ist bedauerlich, dass wir Chronormu nicht stabilisieren konnten. Aber es gibt einen weiteren Ort, an dem wir sie eventuell erwischen und ihren Sturz durch die Zeit stoppen können.\n\n<Nozdormu runzelt die Stirn.>\n\nDie Einblicke in die Vergangenheit dieser Zeitlinie sind... seltsam. Selbst verglichen mit einigen der Visionen, die ich im Laufe meines Lebens beobachtet habe.\n\nSeid vorsichtig, {name}. Ich bin nicht sicher, was Euch erwartet, aber es ist mächtig und es... kommt mir irgendwie bekannt vor.", sourceObjective = "Nehmt das Portal und trefft Euch mit Andantenormu in Azmerloth.", completion = "Was ich auch erwartet habe... Das war es nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[66035] = { id = 66035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murlocpartikel", description = "Eine alternative Zeitlinie, die aus Murlocs entsprungen ist?!\n\nVerzeiht meine egoistische Bitte, aber würdet Ihr einige Partikel Temporalenergie einsammeln, während Ihr nach Botschafterin Chronormu sucht?\n\nLauft einfach in die Partikel hinein und Euer Stab sollte den Rest erledigen. Ich werde die Daten später analysieren... wenn wir nicht gerade auf Reisen durch die Risse in Azeroths verschiedenen Realitäten sind.", sourceObjective = "Laugt 12 Temporalpartikel aus.", completion = "Erstaunliche Arbeit!\n\nWie stellt Ihr Euch die Murlocs dieser Murlocwelt vor? Ich erschaudere bei dem Gedanken...", sourceObjectiveStatus = "unverified-source-field" }
quests[66036] = { id = 66036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mugurlglrlgl!", description = "Mrglgulglrrlglgul! Grurguglullgurl!\n\nGruglrlgllrugl rrgulgrulgrgl grugll gurgull gur. Murgllgllrugl gurgllglrl Murgul gruggullgl. Murguglegurgllgur gurgll gurgulgul guruulgurllgr guuglrllgl.\n\nMgrgulllglll gurl gugll.\n\n<Ihr seid Euch nicht sicher, was genau er Euch sagen will, aber er gestikuliert wild, als würde er auf jemanden oder etwas einstechen. Dieser Murloc will wohl, dass Ihr etwas tötet.>", completion = "Frrg drg Allrghnnge!\n\n<Die Murlocs scheinen zufrieden zu sein.>" }
quests[66037] = { id = 66037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Realität", description = "Wir konnten Botschafterin Chronormus Verbindung zu unserer Zeit verstärken. Ich bin mir sicher, wenn wir sie wiederfinden, können wir das Ritual beenden.\n\nLasst uns fürs Erste wieder in unsere Gegenwart zurückkehren, in eine Welt mit... deutlich weniger Murlocs.", sourceObjective = "Kehrt zu Nozdormu in die Gegenwart zurück.", completion = "Ich danke Euch, dass Ihr dabei geholfen habt, die Zeitlinien zu bewahren... so seltsam sie manchmal auch sein mögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66038] = { id = 66038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rennt durch die Zeit!", description = "{name}, wir müssen rasch handeln, um Botschafterin Chronormu einzuholen, und das meine ich ganz wörtlich.\n\nZera und ich tun, was wir können, damit wir schneller Fortschritte machen. Wir müssen jedoch so gut es geht vermeiden, uns zu sehr in dieser Zeitperiode zu verfangen. Andernfalls werden wir noch langsamer und erwischen die Botschafterin womöglich nicht, bevor sie an Nozdormus Magie verloren ist.\n\nWir haben keine Sekunde zu verschwenden!", sourceObjective = "Rast durch die Zeit und folgt dem Pfad von Chromie und Eternus.", completion = "Bei den Aspekten... Das ist das Schwarze Imperium!", sourceObjectiveStatus = "unverified-source-field" }
quests[66039] = { id = 66039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chromiezeit", description = "Das... das ist das Schwarze Imperium. Wir sind tatsächlich sehr weit in die Vergangenheit gereist.\n\nSeht! Dort sind Botschafterin Chronormu und Eternus! Wir müssen uns beeilen und das Ritual zu Ende bringen.\n\nSelbst meine Neugier ist nicht groß genug, als dass ich herausfinden wollte, wo sie beim nächsten Mal landen.", sourceObjective = "Findet Chromie und schließt das Temporalstabilisierungsritual ab.", completion = "So ist es schon viel besser!\n\nOh, keine Sorge wegen Eternus. Wir haben zurzeit eine Art Waffenstillstand.", sourceObjectiveStatus = "unverified-source-field" }
quests[66040] = { id = 66040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Zukunft", description = "Wir werden nicht mehr durch die Zeiten fallen, aber wir sind weit in die Vergangenheit gereist. Seeehr weit. \"Die-Titanen-waren-noch-nicht-auf-Azeroth\"-weit. Wieder nach Hause zu kommen, wird... keine leichte Aufgabe.\n\nAber wir Drachen können es schaffen!\n\nHaltet Ihr uns bitte diese Schergen des Schwarzen Imperiums vom Leib. Es sollte nicht allzu lang dauern!\n\nSchätze ich.\n\nVermutlich.\n\nMacht Euch keine Gedanken! Haltet einfach nur diese grässlichen Biester fern und wir kümmern uns um den Rest! Ganz einfach!", sourceObjective = "Verteidigt Eure Verbündeten gegen das Schwarze Imperium, bis das Temporalportal errichtet wurde.", progress = "Das war eine etwas... unerwartete Wendung.", completion = "Die Zeit ist wieder stabil.", sourceObjectiveStatus = "unverified-source-field" }
quests[66042] = { id = 66042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschachtelte Muster", description = "Wir stehen am Ursprung der Schattenlande. Wir dürfen nicht zulassen, dass dieser Ort sie ins Verderben reißt.\n\nArbeitet mit unseren neuen Verbündeten zusammen, {name}. Ihre Unterstützung wird den Unterschied zwischen unserem Erfolg und dem Untergang aller Dinge ausmachen.", sourceObjective = "Unterstützt unsere Verbündeten in Zereth Mortis, indem Ihr Weltquests und tägliche Quests abschließt, Schätze plündert und seltene Kreaturen tötet.", progress = "An diesem Ort sind alle Schicksale miteinander verflochten.", completion = "Wir kommen unserem Ziel näher. Schritt um Schritt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66044] = { id = 66044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstürmung der Mauern", description = "Sabellian und die anderen Drachen halten die Djaradin fürs Erste zurück. Wir müssen schnell sein und die hohen Türme sichern, um unseren Sieg sicherzustellen.\n\nWir beide schalten die Belagerungsarmbrüste aus, die uns von oben bedrohen.\n\nLasst mich wissen, sobald Ihr bereit seid.", sourceObjective = "Schaltet die drei Belagerungsarmbrüste und den Champion Choruk aus.", completion = "Gut gemacht, {name}. Sabellian und seine Truppen werden die Djaradin aufhalten, während ich den Schwurstein aktiviere, um die Macht wiederherzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66048] = { id = 66048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beste Pläne und Absichten", description = "Die Djaradin anzugreifen, die die Obsidianzitadelle kontrollieren, wird keine leichte Aufgabe. Selbst mit Furorion und seinen Schwarzkrallenstreitkräften müssen wir uns auf einen harten Kampf gefasst machen. Furorion mag sich seiner Sache sicher sein, aber... ich bin nicht so siegesgewiss.\n\nVielleicht können wir mit den Assistenten sprechen, die bei der Strategieplanung helfen, um Verbesserungen vorzuschlagen.", sourceObjective = "Besprecht die Pläne mit verschiedenen Mitgliedern von Furorions Streitkräften.", progress = "Könnt Ihr unsere Erfolgschancen verbessern?", completion = "Ich verstehe. Ich werde mir Eure Beurteilung sehr gründlich überlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66049] = { id = 66049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obsidianschwurstein", description = "Als Neltharion zum Erdwächter wurde, leistete er einen Schwur, die Welt zu behüten, {name}. Dass er die tiefsten Orte der Erde schützen und mit seinem Schwarm als Azeroths Verteidiger dienen würde. Der Obsidianschwurstein repräsentiert dieses Versprechen.\n\nWir müssen den Stein aktivieren und die Dracheninseln wissen lassen, dass der schwarze Drachenschwarm zurückgekehrt ist!\n\nFolgt mir, {name}.", sourceObjective = "Findet den Obsidianschwurstein.", progress = "Habt Ihr den Schwurstein gesehen?", completion = "Das ist zwar ein Rückschlag, aber mit Eurer Hilfe können wir den Schwurstein bestimmt reparieren. Arbeitet mit Bazentus zusammen... Macht es so.", sourceObjectiveStatus = "unverified-source-field" }
quests[66055] = { id = 66055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zerrüttete Vergangenheit", description = "Der Schwurstein ist beschädigt! Es fehlen Teile.\n\nTut, was Ihr könnt, um die Fragmente zu beschaffen! Vielleicht kann man den Stein irgendwie reparieren!", sourceObjective = "Findet 12 Schwursteinfragmente.", progress = "Habt Ihr die fehlenden Fragmente des Schwursteins gefunden?", completion = "Das scheinen alle Teile zu sein. Ich denke, wir können das reparieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[66056] = { id = 66056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Zukunft schmieden", description = "Die Schmiede des Erdwächters ist die mächtigste aller Drachenschmieden. Unsere Vorfahren schmiedeten darin die stärksten Waffen und Rüstungen, um Azeroth zu verteidigen.\n\nDas Feuer der Schmiede weist die nötige Kraft auf, um die zerbrochenen Fragmente des Schwursteins neu zusammenzufügen.\n\nLasst uns gehen und die Schmiede für die bevorstehende Arbeit vorbereiten.", sourceObjective = "Bereitet die Schmiede des Erdwächters vor.", progress = "Habt Ihr die nötige Aufgabe verrichtet?", completion = "Sehr gut. Nachdem unser Prinz nun da ist, können wir beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66057] = { id = 66057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederherstellen der Zuversicht", description = "Die zerbrochenen Fragmente wurden wieder zusammengefügt. Wir sind bereit, den Schwurstein zu reparieren.\n\nNun geht und helft Furorion, die Reparatur fertigzustellen.", sourceObjective = "Repariert den Obsidianschwurstein.", completion = "Das macht die Angelegenheit etwas komplizierter, doch mir wird nicht versagt bleiben, was mir rechtmäßig zusteht!", sourceObjectiveStatus = "unverified-source-field" }
quests[66070] = { id = 66070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchtklinges Knochen" }
quests[66071] = { id = 66071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegende Rocs", description = "Mein Name ist Professorin Harleen Hohnzirper, berühmte Ornithologin der Extraklasse! Ich bin hergekommen, um die mythischen Blaufederrocs der Dracheninseln zu studieren, aber ich schätze, wir haben jetzt größere Hühnchen zu rupfen.\n\nIch nehme mal an, dass diese Harpyien aus Kalimdor kamen, als die Inseln sich öffneten. Sie sind hoch invasiv und veranstalten ein Festmahl, wie man es sonst nur bei Ogern am Buffet des Bilgewasserkasinos sieht.\n\nGeben wir den einheimischen Rocs hier die Chance, sich zu wehren. Nehmt dieses Medizinset und verwendet es, um die Verletzten wieder auf die Beine zu bringen.", sourceObjective = "Unterstützt 8 verletzte Blaufederrocs.", completion = "Fedrige Arbeit, {name}!\n\nIch würde Euch ja beim Heilen und Töten helfen, aber ich bin in letzter Zeit eher für das Ausklügeln guter Ideen gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[66074] = { id = 66074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urscythidenkönigin" }
quests[66076] = { id = 66076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creature Name" }
quests[66078] = { id = 66078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharfes Training", description = "Ich habe die Schwarzkrallen seit Jahren gehegt, ausgebildet und ermutigt, nach den gleichen Höhen zu streben, die Ihr erreicht habt.\n\nSie mögen nicht die gleichen hehren Ziele erreicht haben wie Ihr, doch sie zeichnen sich auf ihre Weise aus. Sie machen mich stolz.\n\nEs wäre uns allen eine Ehre, wenn Ihr ihr Können auf die Probe stelltet. Ich glaube, Ihr werdet in ihnen ein Stück von Euch selbst wiedererkennen.", sourceObjective = "Stellt das Können von 8 Schwarzkrallenassassinen und -rächern auf die Probe.", progress = "Habt Ihr sie getestet und für würdig befunden?", completion = "Ich glaube, die Schwarzkrallen sind auf alles vorbereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[66079] = { id = 66079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furorion wartet", description = "Diese Eier repräsentieren eine neue Generation der Drachenheit. Sie müssen beschützt und gehegt werden. Und doch... ist mein Herz voller Schmerz und ich sorge mich um Furorion. Ich fürchte, seine sture Entschlossenheit macht ihn geradezu tollkühn.\n\nIm Laufe der Jahre habe ich Eure treue Freundschaft zu schätzen gelernt, {name}. Vielleicht könnt Ihr an meiner statt gehen und ihm helfen.\n\nIhr findet ihn am Obsidianbollwerk. Und bitte, gebt auf ihn acht. Von seinem Schwarm sind nur noch so wenige übrig.", sourceObjective = "Trefft Euch mit Furorion am Obsidianbollwerk.", completion = "Ah, Champion... Eure Ankunft ist vom Glück begünstigt. Da Ihr nun hier seid, wird mein Plan sicherlich gelingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66080] = { id = 66080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeitprobleme", description = "Hallo, {class}. Ihr kommt genau zur rechten Zeit!\n\nAm Tempel geht etwas vor sich und sorgt dafür, dass sich die Zeitwege destabilisieren und ins Tal überlaufen. Nicht nur das, wir vermissen auch einige Zeitwanderer!\n\nDeshalb haben wir zusätzliche Hilfe angefordert, doch eines unserer neusten Mitglieder ist noch nicht angekommen.\n\nKönntet Ihr sie suchen gehen? Da sich die Zeit im Bereich um das Tal herum im Wandel befindet, wissen wir nicht, welche Gefahren dort lauern!", sourceObjective = "Findet die vermisste Rekrutin im Wallenden Wald in Thaldraszus.", completion = "Ich wusste doch, dass jemand kommen würde... irgendwann!", sourceObjectiveStatus = "unverified-source-field" }
quests[66081] = { id = 66081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit läuft ab", description = "Wegen des Angriffs auf den Bronzetempel läuft überall Temporalenergie aus.\n\nDie Zeitwanderer haben überall im Wald Sammelgefäße aufgestellt, um die Magie aufzufangen. Alles, was gesammelt wird, kann als zusätzliche Macht verwendet werden! Das ist gut, denn diese Krise frisst Ressourcen.\n\nIch sollte die Gefäße einsammeln, aber ich muss erst noch Luft schnappen.\n\nKönntet Ihr sie für mich holen?", sourceObjective = "Sammelt 8 Temporalsammler im Wallenden Wald von Thaldraszus.", progress = "Konntet Ihr sie alle finden?", completion = "Habt Dank, {name}.\n\nJetzt kann der Wald sich erholen und die Zeitwanderer haben zusätzliche Energie.", sourceObjectiveStatus = "unverified-source-field" }
quests[66082] = { id = 66082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit in der Flasche", description = "Toll! Der Zeitwandererstab ist intakt! Aber er ist leer.\n\nIch weiß! Ihr könnt ihn mit der Temporalenergie wieder aufladen, die sich hier in der Natur ansammelt. Das bedeutet leider auch, dass Ihr die betroffenen Waldlebewesen besiegen müsst. Die Energien machen sie gefährlich und instabil und wir hätten die Population ohnehin dezimieren müssen...\n\nManchmal muss man für das größere Wohl Opfer bringen. Könnt Ihr helfen? Ich brauche noch einen Augenblick.", sourceObjective = "Sammelt Zeitenergie von erlegten zeitgeladenen Wildtieren im Wallenden Wald von Thaldraszus.", completion = "Dieser Stab hat bereits einiges durchgemacht, aber dank Eurer Hilfe sollte er wieder voll funktionstüchtig sein.\n\nVielen Dank, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66083] = { id = 66083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fühlt sich an, wie beim ersten Mal", description = "Die Zeitwege zu behüten, ist eine gefährliche Aufgabe.\n\nAuch wenn Ihr <kein Zeitwanderer/keine Zeitwanderin> seid, glaubt Botschafterin Chronormu, dass Ihr eine große Hilfe sein werdet. Aber damit Eure Sicherheit gewährleistet ist, müssen wir Euch ordentlich ausbilden.\n\nLeider sind unsere Ausbilder immer noch vermisst. Ich werde mein Bestes geben. Schauen wir mal, wie wir uns anstellen. Ich weiß, dass die Botschafterin sich auf uns beide verlässt.", sourceObjective = "Sprecht mit Andantenormu und nehmt an der Zeitwandererausbildung teil.", completion = "Das war recht unerwartet! Wie Ihr seht, birgt die Zeitenergie viele Gefahren.\n\nIch wünschte, wir hätten Zeit, die Auswirkungen Eures Malheurs zu beobachten, aber es gibt Wichtigeres zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[66084] = { id = 66084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeiten wie diese", description = "Trotz des kleinen Malheurs bei der Ausbildung glaube ich, dass Ihr bereit seid, um uns hier zu helfen.\n\nDie Verzerrungen im Tal erlauben verschiedenen Zeitperioden, in unsere überzufließen. Wir wissen nicht, warum diese Zeitlinien miteinander verbunden sind, und das ist beunruhigend. Wir brauchen mehr Informationen.\n\nBitte seht, ob Ihr etwas über die Kreaturen in Erfahrung bringen könnt, die aus den verschiedenen Zeitlinien hierherkommen. Sicherlich hinterlassen sie beim Übergang irgendwelche Rückstände. Wenn wir sie untersuchen, finden wir hoffentlich einen Weg, diese Krise zu meistern.", sourceObjective = "Sammelt 100 Temporalrückstände von zeitverlorenen Gegnern in den Wandernden Sanden.", progress = "Das Ganze ist zwar unangenehm, aber ich freue mich darauf, neue Chronologien zu entdecken, die ich studieren kann.", completion = "Mit diesen Proben werden wir besser verstehen, wie und warum diese Zeitlinien sich mit unserer überschneiden.\n\nDanke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66085] = { id = 66085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Könnten wir die Zeit zurückdrehen", description = "Ein anständiger Zeitwanderer lässt keine Krise halb geklärt. Warum warten und lernen, wenn wir die Werkzeuge, die wir brauchen, bereits besitzen?\n\nDa Ihr nach wie vor meinen Stab habt, habe ich mir Ersatz besorgt. Den vermisst bestimmt niemand. Mein Plan lautet wie folgt: Wir schließen uns bei diesen Rissen zusammen und retten gemeinsam den Tag! Alle Tage, genaugenommen. Entschuldigung, dieser Zeitkram ist noch verwirrend für mich.\n\nWas sagt Ihr? Das sollte doch leicht genug sein, nicht wahr?", sourceObjective = "Schließt die Zeitrisse mit Siaszerathel in den Wandernden Sanden.", completion = "Wir haben es geschafft! Richtig?\n\nAbgesehen von ein paar Falten... davon muss Dante nichts erfahren. Und unerwarteten Besuch gab es auch...\n\nAlles in allem würde ich aber sagen, dass das ziemlich gut gelaufen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[66087] = { id = 66087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sperrstunde", description = "Diese Vorstöße strapazieren diese Zeitlinie, bis sie zerbricht. Wenn wir nur die Reihe unserer Zeitwanderer vollständig wäre!\n\nObwohl Ihr neu am Stab seid, sagt man mir, dass Ihr uns sehr geholfen habt. Mit zusätzlichem Ansporn könntet Ihr unserer Sache vielleicht noch mehr helfen.\n\nNormalerweise würde ich Euch gründlich ausbilden, aber es sind... ungewöhnliche Zeiten. Nehmt diese Rolle des fortgeschrittenen Wissens und nutzt sie, um die Eindringlinge zurückzudrängen! Aber beeilt Euch, die Effekte sind vorübergehender Natur.", sourceObjective = "Unterstützt die Zeitwanderer und vernichtet zeitverlorene Gegner, stärkt bronzene Verbündete, holt verlorene Artefakte zurück und schließt Zeitrisse in den Wandernden Sanden.", progress = "Jedes Eindringen schwächt diese Zeitlinie.", completion = "Der Stab eines Zeitwanderers ist beim Hüten der Zeit entscheidend. Manchmal genügt schon ein sanfter Anstoß. Andere Male ist ein stattlicher Hieb erforderlich. Damit sollte die Instabilität dieser Gegend vorerst gelindert worden sein.\n\nEs gibt zwar noch viel zu tun, aber Eure Begleiter sind erpicht darauf, oben beim Tempel zu helfen. Ich werde sicherstellen, dass dieses Gebiet geschützt bleibt, während Ihr weiterzieht.\n\nViel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[66090] = { id = 66090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad der Dunklen Waldläufer", sourceObjective = "Nehmt das Ornat der Dunklen Waldläufer entgegen.", completion = "<Velonara blickt Euch wissend an.>\n\nEs war eine gute Tarnung, aber ich habe sofort gesehen, dass Ihr nicht die Person wart, der Ihr zu sein vorgabt.\n\nDennoch habt Ihr Euer Leben riskiert, um uns zu helfen. Das werde ich nicht vergessen.\n\nEs gibt einige unter den Kaldorei, die von Sylvanas' Val'kyr aufgezogen wurden und zu den ihren zurückkehren wollen. Wenn Tyrande sie zurückhaben will, können sie gehen. Der Rest wird in den Reihen der Dunklen Waldläufer willkommen sein.\n\nIn Anerkennung Eurer Dienste möchte ich Euch dieses Geschenk anbieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[66091] = { id = 66091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad der Dunklen Waldläufer", sourceObjective = "Jahrelang haben wir Dunklen Waldläufer als Agenten der Bansheekönigin gearbeitet. Jetzt, unter der Führung des neuen Rates der Verlassenen, dienen wir einer größeren Sache: der Gestaltung der Zukunft unseres Volkes.\n\nWir können nicht sicher sein, was vor uns liegt. Aber ich schwöre, dass die Dunklen Waldläufer alles in ihrer Macht stehende tun werden, um dieses Königreich zu verteidigen.\n\nEure Hilfe war ausschlaggebend dafür, dass wir die Ruinen von Lordaeron befreien konnten. Nehmt dies mit unserem Dank an.", sourceObjectiveStatus = "unverified-source-field" }
quests[66094] = { id = 66094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Szar Skeleth", description = "Laut den Aufzeichnungen eines Hüters kann der Stein der Einsicht in einem drakonischen Turm auf einem Fluss in der Mitte der Ebenen von Ohn'ahra gefunden werden. Das sollte Szar Skeleth sein. Seid vorsichtig. Die Splitterflammen werden uns sicherlich nicht einfach hineinspazieren lassen.\n\nSobald Ihr dort seid, trefft Euch mit Toddy, damit wir den Stein zurückholen können.", sourceObjective = "Trefft Euch mit Toddy nahe Szar Skeleth auf den Ebenen von Ohn'ahra.", completion = "Da seid Ihr ja! Ich hab eine besondere Mission für Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66100] = { id = 66100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewichtiger Nachschub", description = "Diesmal hab ich es echt vermasselt. Ich wollte mir nur kurz die Beine vertreten und kam gerade noch rechtzeitig zum Lager zurück, um mitanzusehen, wie sich die Tarasek alles unter den Nagel rissen, was nicht festgetackert war.\n\nDiese Vorräte waren teuer und ich kann nicht einfach um Hilfe bitten, um neue zu besorgen! Meine Schwester Nori hält mich jetzt schon für eine Versagerin.\n\nWenn Ihr sowieso das Tal passiert, könntet Ihr vielleicht die Augen nach verlorenen Säcken mit Vorräten offenhalten?", sourceObjective = "Sammelt 6 Säcke an Vorräten der Wegbehüterin.", progress = "<Alvi blickt in Eure Richtung, offensichtlich voller Panik. Die fehlenden Vorräte scheinen gerade ihre geringste Sorge zu sein.>", completion = "Danke, {name}, aber wir haben gerade größere Probleme.", sourceObjectiveStatus = "unverified-source-field" }
quests[66101] = { id = 66101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Himmel hoch", description = "Toddy und Naleidea haben einen sofortigen Untersuchungsbericht über die Umgebung angefordert.\n\nZum Glück habe ich ein verzaubertes Teleskop und eine Feldmesserscheibe, die uns helfen werden, nahegelegene Gebiete aus der Sicherheit der Wolken heraus auszuspähen.\n\nLeider habe ich tödliche Höhenangst und kann mich nicht überwinden, das Gerät zu betreten.\n\nIhr habt keine Höhenangst, oder?", sourceObjective = "Nutzt die Scheibe des Feldmessers, um in den Himmel zu springen und die Umgebung auszuspähen.", progress = "Viel Glück dort oben. Ich bleibe lieber auf dem Boden.", completion = "<Aster seufzt erleichtert.>\n\nIch war sicher, Ihr würdet von da oben in Euren Tod stürzen. Habt Dank, dass Ihr das Risiko auf Euch genommen habt, damit ich es nicht tun musste.", sourceObjectiveStatus = "unverified-source-field" }
quests[66103] = { id = 66103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bemüht, jeden Wunsch zu erfüllen", description = "Wir müssen mehr Truppen aussenden, um die Obsidianzitadelle zu verteidigen. Jetzt, da wir Fuß gefasst haben, ist es wichtig, die Versorgung an frischen Rekruten nicht abreißen zu lassen.\n\nWir verfügen über zusätzliche Reservetruppen am Obsidianbollwerk. Die könnten uns den Rücken stärken.\n\nIm Prinzip sind sie gut ausgebildet, aber sie könnten davon profitieren, wenn jemand mit Eurer Erfahrung und Eurem Talent ihre Kampfkünste auf die Probe stellen würde. So stellen wir fest, ob sie wirklich bereit sind.", sourceObjective = "Stellt das Können von 10 Schwarzkrallenassassinen und -rächern am Obsidianbollwerk auf die Probe.", completion = "Danke, {name}. Diese Truppen sind dank Euch besser vorbereitet denn je. Und unsere Bemühungen erfordern eine große Menge an Vorbereitung und Kampfkraft.", sourceObjectiveStatus = "unverified-source-field" }
quests[66104] = { id = 66104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forensische Ökologie", description = "Ich weiß nicht mehr weiter, {name}. Tharu und ich haben uns durch fast alle Leichen gewühlt, nur um am Ende zu stolpern, weil wir uns nicht auf einen Ansatz einigen können. Wenn er mir bloß zuhören würde!\n\n<Ökologe Iskha seufzt.>\n\nDer Stress durch die Situation setzt uns beiden zu. Ich habe bislang nicht einmal eine belastbare Hypothese.\n\nIhr seht aus, als würde Euch so schnell nichts auf den Magen schlagen. Könntet Ihr vielleicht die letzten beiden Gorlocs übernehmen? Ihr könnt Euch mein Skalpell borgen.", sourceObjective = "Seziert die Gorlocleichen.", progress = "Keine Sorge, an den Gestank gewöhnt Ihr Euch nach einer Weile.", completion = "Haben die Kämpfe der Gorlocs das Sumpfland so in Mitleidenschaft gezogen?\n\n<Ökologe Iskha wirkt beschämt.>\n\nIch glaube, jetzt verstehe ich...", sourceObjectiveStatus = "unverified-source-field" }
quests[66105] = { id = 66105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lösung mit dem Skalpell", description = "Ich glaube, wir können von hier aus sicher genug Daten sammeln, aber...\n\nTharu ist ein herausragender Ökologe und er ist ein Mann der Tat. Dennoch ist das Ökosystem fragil, und wir könnten es beschädigen, wenn wir nicht vorsichtig sind. Ich gebe allerdings zu, dass wir nicht mehr viel Zeit haben.\n\nEs könnte sich vielleicht lohnen, etwas auf ihn einzugehen.\n\nDie wütenden Elementare zu erledigen, sollte uns etwas Zeit verschaffen, ohne dass es unsere Forschung behindert. Aber achtet darauf, sie in gleichen Zahlen zu erledigen... Wir wollen das Gleichgewicht ja nicht noch weiter stören.", sourceObjective = "Tötet 5 |4Tobendes:Tobende; Wasser und 5 |4Tobenden Wind:Tobende Winde;.", completion = "Hat das irgendetwas gebracht? Nein?\n\n<Ökologe Iskha seufzt.>\n\nNa, zumindest sind wir fast fertig mit unserer Forschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[66106] = { id = 66106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muscheln kuscheln", description = "Ich war ein Narr, Iskha nicht zu glauben, als er darauf beharrte, dass mehr dahintersteckte. Er wäre nicht mein Freund, wenn er mir nicht immer zwei Schritte voraus wäre.\n\nAber wir können es ihm gegenüber wiedergutmachen, indem wir etwas unternehmen. Wenn tatsächlich Muscheln für dieses elementare Chaos verantwortlich sind, geht doch in ihr Lager und entreißt die Muscheln ihren glitschigen Händen.\n\nBringt haufenweise Wind- und Wassermuscheln her, damit Iskha genug hat, um nach Herzenslust zu forschen.", sourceObjective = "Sammelt 15 wassererfüllte Muscheln und 15 winderfüllte Muscheln von Triefschlund- und Windflossengorlocs.", progress = "Das sollte ihnen eine Lehre sein.", completion = "Iskha und ich bringen sie zurück zu den Lebensbecken, wo sie keinen Ärger mehr machen können.\n\nIhr habt das heute gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66107] = { id = 66107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildtierrettung", description = "Man muss kein Ökologe sein, um zu erkennen, dass das Sumpfland in echten Schwierigkeiten steckt.\n\nAber Iskha lässt uns hier in aller Ruhe tote Kreaturen untersuchen, während wir lieber verhindern sollten, dass sie überhaupt sterben! Der rote Drachenschwarm ist schließlich dafür da, das Leben zu schützen, nicht zu zerteilen!\n\nIch liebe Iskha, und er hat wirklich Ahnung, aber wenn wir warten, bis er fertig ist, gibt es kein Sumpfland mehr, das wir noch retten könnten.\n\nIch kümmere mich um seine ewige Nachdenkerei. Geht Ihr inzwischen raus, macht Euch Eure Stiefel schmutzig und rettet einige Lebewesen.", sourceObjective = "Rettet die Lebewesen des Rastlosen Sumpflands.", completion = "So! Das Sumpfland ist wieder in Ordnung! Iskha geht immer noch seiner Taxidermie... ich meine seinen Nachforschungen nach.\n\nMoment mal, wie meint Ihr das, dass weiterhin Elementare kommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[66108] = { id = 66108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lösung mit dem Vorschlaghammer", description = "Nun, ich bin froh, dass Tharu meine Sichtweise jetzt nachvollziehen kann. Und ich bin dankbar, dass Ihr Lebewesen retten konntet, während ich hier herumgetrödelt habe.\n\nDie Situation ist ernster als gedacht. Er hatte recht, dass wir sofort handeln müssen. Nach allem, was ich bisher in Erfahrung bringen konnte, wird dieses elementare Bombardement nicht aufhören, bis wir uns um die Gorlocs gekümmert haben.\n\nAn Tharus Stelle und praktisch gedacht würde ich mich direkt ihren Anführern zuwenden. Wenn sie niemanden mehr haben, um den sie sich versammeln können, sollten sie sich verziehen und das Sumpfland nicht mehr bedrohen.", sourceObjective = "Tötet Sogglmoggl, den König der Triefschlünde, und Wirblgirgl, den König der Windflossen.", completion = "Das sollte sie zumindest eine Weile lang aufhalten.\n\nDanke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66110] = { id = 66110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Frieden eine Chance", sourceObjective = "Stellt Euch den Vertretern der Allianz vor.", completion = "<Kapitänin Garrick begrüßt Euch.>\n\nKriegsfürstin Breka beweist einmal mehr ihre Ehrenhaftigkeit, indem sie Euch zu mir schickt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66111] = { id = 66111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindringende Elementare", sourceObjective = "Tötet 15 Urelementare in der Botschaft von Schwingenrast.", completion = "Für die Drachenschuppenexpedition!\n\n<Kapitänin Garrick salutiert Euch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66112] = { id = 66112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer zur Hand", description = "Habt Ihr je so machtvolle Elementare gesehen?!\n\n<Grun grüßt.>\n\nHab die Wachen grummeln gehört, weil sie die ganze Zeit gegen sie kämpfen müssen, aber sie sehen nicht das große Ganze... größere Elementare heißt größere Handwerksmaterialien!\n\nWährend Ihr draußen seid, um für unsere Sicherheit Elementare zu beseitigen oder was auch immer ihr macht, nehmt ein paar Stücke der größten mit, dann kann ich mal versuchen, ob ich da was draus machen kann!", sourceObjective = "Sammelt einen urzeitlichen geschmolzenen Kern.", progress = "Als Erstes fertige ich einen großartigen Helm an... Nein, einen Hammer... Nein, einen GROSSEN Hammer!", completion = "<Gruns Augen weiten sich, als Ihr ihm die Urkerne überreicht.>\n\nUnglaublich! Das ist der beste Tag meines Lebens!", sourceObjectiveStatus = "unverified-source-field" }
quests[66113] = { id = 66113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unscheinbare Fuhre", sourceObjective = "Repariert den ausgeliehenen Wagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66114] = { id = 66114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Königin", description = "Wir beschützen unsere kostbaren Eier, um die Zukunft aller Drachenschwärme zu sichern. Mit ihrem Handeln werden uns die Primalisten nicht nur seelische Pein zufügen.\n\nSie bedrohen unsere Existenz.\n\nIch muss die Königin sofort darüber informieren.", sourceObjective = "Reitet mit Majordomus Selistra zum Rubinlebensschrein.", completion = "Das ist schrecklich... doch unser Schwarm hat über die Jahre viele Tragödien erlitten. Wir werden standhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[66115] = { id = 66115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mandat der Roten", description = "Hingabe und Mitgefühl sind unsere Berufung. Wir helfen den anderen Schwärmen nicht nur ihretwegen, sondern zum Wohle der gesamten Drachenheit.\n\nVielleicht versteht Ihr uns besser, wenn Ihr mit der Drachenbrut hier beim Rubinlebensschrein sprecht.", sourceObjective = "Sprecht mit den Pflegern beim Rubinlebensschrein.", progress = "Der rote Drachenschwarm bewahrt unser aller Zukunft.", completion = "Ich hoffe, Ihr wisst das, was wir tun, mittlerweile zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66116] = { id = 66116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die größte Bedrohung", description = "Wir haben einfach zu viele verwundbare Eier, die wir schützen müssen. Wenn der Feind durchbricht, ist alles verloren!\n\nIch bin sicher, unsere Wachen marschieren auf dem Feld auf, um den Gegner zurückzudrängen. Sprecht mit Kommandant Lethanak. Er wird Eure Stärke dort einsetzen, wo sie am dringendsten gebraucht wird.", sourceObjective = "Findet Kommandant Lethanak beim Blitzfrostangriff.", completion = "Ich werde sämtliche Waffen aus meiner Waffenkammer einsetzen, um diese Feinde aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[66117] = { id = 66117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säubert das Schlachtfeld" }
quests[66118] = { id = 66118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basaltangriff", description = "Raszageth und ihre Primalisten haben gigantische Erdelementare herbeigerufen, um unsere Mauern zu durchbrechen. Sie müssen aufgehalten werden!", sourceObjective = "Zerstört 4 zornige Klippen beim Blitzfrostangriff.", progress = "Sie werden alles in ihrer Macht Stehende tun, um unsere Mauern zu zerstören!", completion = "Der Lebensschrein ist unerschütterlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[66119] = { id = 66119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rubinlebensbecken: Invasion der Primalisten", description = "Die Primalisten haben sich einen Weg in unser Zuhause gebahnt. Wir waren auf einen so intensiven Angriff nicht vorbereitet... Mehrere von ihnen konnten durchbrechen.\n\nEiner unserer Drakoniden ist ebenfalls durch, um ihnen zu folgen, doch er hat sich noch nicht zurückgemeldet. Ich fürchte das Schlimmste.\n\nIch stehe Wache. Solange ich lebe, wird kein weiterer von ihnen unsere Mauern durchbrechen, doch Ihr müsst Euch um die kümmern, die es hineingeschafft haben.\n\nLos!", sourceObjective = "Betretet die Rubinlebensbecken und haltet den Angriff der Primalisten auf.\n\nIhr könnt die Rubinlebensbecken über die Anhängerdungeons auch allein betreten.", progress = "Sie werden unsere Zukunft zerstören, wenn wir es nicht schaffen, sie aufzuhalten.", completion = "Unsere Heimat wird zwar noch jahrelang von diesem Angriff gezeichnet sein, aber wir sind stark. Wir werden... durchhalten, und die geretteten Eier werden uns eine strahlende Zukunft bescheren.\n\nHabt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[66121] = { id = 66121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eivakuierung", sourceObjective = "Rettet 4 Eier aus der Blitzfrostenklave.", completion = "Fast fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[66122] = { id = 66122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protokampf", sourceObjective = "Besiegt 3 Protodrachen in der Blitzfrostenklave.", completion = "Sie mögen zwar unserer Art angehört haben, und hätten vielleicht als Geschwister an uns herantreten können... aber ihre Grausamkeit beraubt mich jeder Gnade.", sourceObjectiveStatus = "unverified-source-field" }
quests[66123] = { id = 66123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ab mit dem Kopf", description = "Jadzigeth, einer von Raszageths niederträchtigen Leutnants, führt die Primalisten hier an.\n\nZeigen wir ihnen, was passiert, wenn sie sich gegen uns stellen.", sourceObjective = "Besiegt Jadzigeth in der Blitzfrostenklave.", progress = "Es gibt keinen anderen Weg.", completion = "Unsere Königin!", sourceObjectiveStatus = "unverified-source-field" }
quests[66124] = { id = 66124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Triumphaler Abgang", description = "Soweit ich sehen konnte, hat die Königin sich in die Wilde Brutstätte zurückgezogen. Sie dient als Außenposten, um die Protodrachen in der Gegend zu überwachen... Ich hoffe nur, dass ihre Verteidigung ausreicht.\n\nWir müssen sofort dorthin!", sourceObjective = "Entkommt mit Majordomus Selistra aus der Blitzfrostenklave.", progress = "Meine Königin...", completion = "Ich habe keine Ruhe gefunden, bevor die Eier in Sicherheit waren... Das ist eine Erleichterung.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66126] = { id = 66126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offenbarung unserer Vergangenheit", description = "Bringt mir einen zusammengesetzten Schlüssel.", sourceObjective = "Findet 1 zusammengesetzten Schlüssel.", progress = "Ein restaurierter Obsidianschlüssel könnte uns helfen, Funktionen dieser Schmiede zu erschließen, von denen wir bisher nur geträumt haben!", completion = "Eine weise Entscheidung. Diese Streitereien um den Thron werden unserer Verteidigung nicht gerade nützen. Wir müssen Waffen und Ausrüstung herstellen, um die Djaradin abzuwehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[66128] = { id = 66128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nächste Schritte", description = "Diese Steine sind eine unfassbare Entdeckung, selbst wenn sie ihren gedachten Zweck nie erfüllen.\n\nBevor wir sie ausprobieren, müssen wir uns aber an den Ablauf halten. Sie müssen untersucht und katalogisiert werden, und die Berichte müssen an das Hauptquartier der Archäologischen Akademie und das der Forscherliga geschickt werden.\n\nTreffen wir uns im Basislager wieder. Dann können wir besprechen, was als Nächstes ansteht.", sourceObjective = "Trefft Euch mit Toddy und Naleidea im Forscherzelt beim Drachenschuppenbasislager an der Küste des Erwachens.", progress = "Oh, Ihr könnt Euch nicht vorstellen, wie ich plane, in diese Einrichtung zu kommen!", completion = "Keine Sorge. Seid etwas geduldig, dann gehen wir der Sache schon noch auf den Grund.", sourceObjectiveStatus = "unverified-source-field" }
quests[66129] = { id = 66129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offenbarung unserer Vergangenheit", description = "Bringt mir einen zusammengesetzten Schlüssel.", sourceObjective = "Findet 1 zusammengesetzten Schlüssel.", progress = "Wir müssen die verlorenen Obsidianschlüssel finden! Wir brauchen die Macht, die sie erschließen, um die Ungläubigen zurückzuschlagen.", completion = "Dieser Beitrag sichert Euch einen Platz unter den wenigen Auserwählten von Todesschwinge. Gemeinsam werden wir über die Welt hinwegfegen und die Stunde des Zwielichts verkünden!", sourceObjectiveStatus = "unverified-source-field" }
quests[66130] = { id = 66130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offenbarung unserer Vergangenheit", description = "Bringt mir einen zusammengesetzten Schlüssel.", sourceObjective = "Findet 1 zusammengesetzten Schlüssel.", progress = "Besorgt mir noch mehr restaurierte Obsidianschlüssel, dann können wir das volle Potential der Obsidianzitadelle aktivieren.", completion = "Gute Arbeit. Dieser Schlüssel wird uns erlauben, mehr verlorene Geheimnisse der Zitadelle aufzudecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[66131] = { id = 66131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offenbarung unserer Vergangenheit", description = "Bringt mir einen zusammengesetzten Schlüssel.", sourceObjective = "Findet 1 zusammengesetzten Schlüssel.", progress = "Bringt mir weitere restaurierte Schlüssel, damit wir unsere Arbeit hier fortsetzen können.", completion = "Habt Dank, {name}. Eure Unterstützung in dieser Sache wird meinen Thronanspruch untermauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[66133] = { id = 66133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüssel der Loyalität", sourceObjective = "Sammelt 1 große Obsidianschlüssel.", sourceObjectiveStatus = "unverified-source-field" }
quests[66134] = { id = 66134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schädlingsbekämpfung in Azeroth", description = "Ihr da! Schlüpfling!\n\nGeht mir zur Hand, ja? Diese Schotlinge zerfetzen meine ganzen Pflanzen!\n\nAlle möglichen Elementare sind in die Gärten eingedrungen und sie scheinen... die Tiere zu beeinflussen. Als ob ihre Energie die Schotlinge verrückt machen würde! Verrückter als sonst!\n\nIch habe mit diesen drei schon alle Hände voll zu tun. Bitte! Helft mir, bevor sie all meine Blumenbeete verwüsten.", sourceObjective = "Tötet 8 aufgebrachte Setzlinge in den Gärten.", completion = "Den Titanen sei Dank, Ihr seid da! Ansonsten weiß ich nicht, wie ich dieses Ungeziefer jemals loswerde.\n\nHelft Ihr einem alten Drakoniden mit den restlichen Gärten?", sourceObjectiveStatus = "unverified-source-field" }
quests[66135] = { id = 66135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrling des Gärtners", description = "Blattington! Fürst Blattington, wo bist du?\n\nMein Vorstandsassistent und Lehrling Fürst Blattington ist verschwunden! Er liebt das Erkunden, aber er ist noch schlechter als ich, wenn es darum geht, sich zu verteidigen. Ich bin ein Gärtner, kein Krieger!\n\nKönntet Ihr diesen Faulenzer bitte für mich finden? Ich brauche ihn hier, damit ich nachdenken kann. Er hält sich normalerweise im Schuppen auf und wühlt sich durch Müllhaufen.\n\nAber seid vorsichtig, er kann manchmal leicht reizbar sein.", sourceObjective = "Sucht nach Fürst Blattington in der Gartenhütte, indem Ihr Müllhaufen beseitigt.", completion = "Ah, da ist er ja! Mein lieber Gehilfe. Wer ist ein guter Junge? Ein guter, stacheliger Junge? Blattington! Wer ist der stacheligste? Ganz genau! Du!\n\nÄhem. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66136] = { id = 66136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarextrakt", description = "Vor ein paar Tagen hat ein riesiger Feuerelementar den See verwüstet. Ich glaube, dass er hinter all diesem Chaos steckt, aber er ist zu groß, als dass wir ihn bekämpfen könnten. Irgendwie müssen wir ihn zuerst schwächen.\n\nSchreibt den alten Gryrmpech aber noch nicht zu früh ab, denn ich habe einen Plan!\n\nWasserelementare haben beschlossen, es sich im Pavillon des blauen Drachenschwarms gemütlich zu machen. Wenn Ihr genügend Essenz von ihnen sammelt, könnten wir sie gegen den Feuerelementar einsetzen.\n\nMan soll Feuer mit Feuer bekämpfen! Oder in diesem Fall eben mit Wasser, schätze ich.\n\nJedenfalls solltet Ihr Euch jetzt auf den Weg machen.", sourceObjective = "Sammelt 5 wässrige Essenzen in den Gärten.", progress = "In all meinen Jahren habe ich noch nie so viele Elementare auf einem Haufen gesehen. Warum mussten sie unbedingt in meinem Garten auftauchen?", completion = "Ausgezeichnet! Genau das brauchen wir, um diese Feuerelementare ein für alle Mal zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66137] = { id = 66137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Peitsche schwingen", description = "Ich bin sicher, dass die Schotlinge nicht die einzigen Wildtiere sind, die sich wie die Axt im Wald benehmen.\n\nAlexstraszas Baum war mir schon immer ein Dorn im Auge. Ihre Lebensmagie zieht allerhand Flora und Fauna an, Gut und Böse gleichermaßen. Und ratet mal, wer sich um die Bösen kümmern muss? Der alte Gryrmpech natürlich!\n\nBei den Aspekten, ich werde zu alt für so etwas.\n\nDiese Verwalter sind nicht im Kämpfen ausgebildet, es liegt also an Euch, das Unkrautproblem der Lebensbindern zu lösen.", sourceObjective = "Tötet 10 invasive Todesblüten und Peitscherunkrautlinge in den Gärten.", completion = "Das Elementarproblem ist größer, als ich dachte, wenn Ihr so viele getötet habt. Aber zumindest wird Alexstrasza sich freuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66138] = { id = 66138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie Sand im Stundenglas", description = "Wie auch der Rest der Gärten musste Nozdormus Stundenglas den Unruhen der Elementare standhalten. Turbulente Windelementare sind vorbeigezogen und haben den magischen Sand aus dem Inneren des Stundenglases verstreut.\n\nOhne diesen Sand ist Nozdormus Einfluss hier stark geschwächt.\n\nAls Verwalter in Ausbildung wurde ich damit beauftragt, das Stundenglas jederzeit zu überwachen. Wenn Ihr den Sand an meiner Stelle einsammeln könntet, wäre ich Euch auf ewig dankbar.", sourceObjective = "Sammelt 8 Haufen aus windgepeitschtem Zeitsand in den Gärten.", completion = "Gute Arbeit. Nozdormu hat mir gestern gesagt, dass er sich gerne bedanken würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[66139] = { id = 66139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich Feuer", description = "Na gut, junges Wesen. Ich habe all die Wasserelementaressenzen für Euch in diesem Krug verstaut.\n\nWenn Ihr ihn einfach auf den Großen werft, sollte das genügen. Ich meine, wann hat Wasser jemals nicht gegen Feuer gewirkt? Das ist eine idiotensichere Sache.\n\nDie Hitze, ähm, ist nicht gut für meine Gelenke, ich bleibe also einfach hier. Ihr könnt das sicher selbst erledigen.\n\nViel Glück, junges Wesen!", sourceObjective = "Nutzt die konzentrierte Essenz des Wassers, um das lodernde Inferno in den Gärten zu bezwingen.", completion = "Unglaublich! Ich war zwar nicht sicher, ob es funktioniert, aber ich bin froh, dass es geklappt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[66141] = { id = 66141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebrochene Traditionen, gebrochene Körper", description = "Meine Furbolgfreunde sind nicht mehr sie selbst. Sie haben... schlimme Dinge getan. Jetzt sind sie zu etwas Schlimmerem geworden.\n\nFurbolgs haben sich noch nie gegen Furbolgs gewandt!\n\nMein Bruder und ich sind ihnen entkommen. Ich bin hergekommen, um Hilfe zu suchen, während er bei unserem Klanbau geblieben ist.\n\nHelft uns, bevor das das Ende unseres Klans ist!", sourceObjective = "Trefft Garz und Narn auf dem Weg zum Rostkieferbau.", completion = "Mein Bruder hat die Wahrheit gesagt.\n\nEs ist noch schlimmer als bei meiner Abreise.", sourceObjectiveStatus = "unverified-source-field" }
quests[66147] = { id = 66147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristalle im Wasser", description = "Im Moment mag es nicht danach aussehen, aber wir sind Profis. Die Expedition hat uns damit beauftragt, eine Ansammlung seltener Kristalle in der Gegend aufzuspüren. Eine geologische Untersuchung, wenn man so will.\n\nIch bin immer noch erschüttert von dem Gorlocangriff. Wärt Ihr so freundlich, für mich nach diesen Kristallen zu suchen? Bringt Proben mit, wenn Ihr könnt.", sourceObjective = "Sammelt 4 Kristallproben an der Gorlocküste.", progress = "Feldarbeit ist anstrengend.", completion = "Gute Arbeit! Ich bringe das zu LOU-C. Mal sehen, was ihr kleines Gerät damit anstellen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[66148] = { id = 66148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühere Furbolgfamilie", description = "Primalisten sind gekommen. Sie haben uns neue Kraft versprochen: die Macht über die Elemente.\n\nIch hätte nicht gedacht, dass Steinherz ihre Geschenke annehmen würde. Unser Klan brauchte keine Macht. Er hat nicht über die Folgen nachgedacht.\n\nSeine furchtbare Entscheidung kann nicht ungeschehen gemacht werden. Die Magie hat meinen Klan verdorben wie eine Krankheit, die eine Wurzel verfaulen lässt.\n\nEs bricht mir das Herz, aber das Einzige, was uns bleibt, ist, die Verderbten auszumerzen.", sourceObjective = "Tötet 15 Rostkieferfurbolgs und Elementare und trefft Euch anschließend mit Narn tiefer im Rostkieferbau.", completion = "Es tut mir leid, dass Ihr dem Rostkieferklan so begegnet seid. Das ist nicht unsere Art.", sourceObjectiveStatus = "unverified-source-field" }
quests[66149] = { id = 66149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarer Einfluss", description = "Narn sagt, dass nicht alle Rostkiefern Steinherz oder den Primalisten gefolgt sind.\n\nEinige Widerständler werden gegen ihren Willen gefangen gehalten. Von Totems, die Fels und Schlamm versprühen... Von ihnen werden sie unterworfen.\n\nZerschmettert die Totems und befreit sie!", sourceObjective = "Zerstört 3 Primalistentotems der Erdbindung und trefft Euch anschließend mit Narn tiefer im Rostkieferbau.", completion = "Ich werde den Primalisten niemals das Leid vergeben, das sie unserem Klan zugefügt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[66150] = { id = 66150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Radzas Rettung", description = "Radza Donnerklaue ist unsere Geisthüterin. Sie bewahrt unsere Traditionen und unsere Geschichte.\n\nDie Überzeugungen der Primalisten stehen entgegengesetzt zu allem, an das unser Klan glaubt. Ich wusste, sie würde sich Steinherz widersetzen!\n\nSteinherz wird alles dafür tun, sie zu unterwerfen. Ohne Radzas Segen kann niemand Häuptling sein!\n\nNarn sagt, dass Khargall Fünfzahn, die Wache des Häuptlings, versucht, sie zu brechen. Wenn Radza stirbt, stirbt unser Klan mit ihr.\n\nHelft ihr, {name}, und seid darauf gefasst, dass er sie nicht ohne einen Kampf gehen lassen wird.", sourceObjective = "Rettet Radza Donnerklaue.", completion = "So viele aus meinem Klan sind in der Schlacht gegen ihre Brüder und Schwestern gefallen... Und alles nur, um der Macht willen.\n\n<Radza gibt ein kehliges Knurren von sich, das zu einem langen, klagenden Flüstern wird.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66151] = { id = 66151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sein steinernes Herz", description = "Wir jaulen in Trauer um unseren Häuptling, auch wenn er noch lebt.\n\nWas von Steinherz übrig ist, befindet sich in der Höhle weiter vorn. Viele haben versucht, ihn zur Vernunft zu bringen.\n\nEr hat sie getötet, beinahe auch Narn.\n\nEr ist ein Monster! Das ist das wahre Ziel der Primalisten. Sie wollen uns in Stein und Feuer verwandeln, damit wir ihnen dienen.\n\nIn ihm ist kein bisschen Rostkiefer mehr übrig. Er muss vernichtet werden, bevor andere dasselbe Schicksal erleiden.", sourceObjective = "Tötet Steinherz.", progress = "Unser Häuptling wollte Macht, um den Klan zu beschützen... doch durch sie wurde uns alles genommen.", completion = "Mein Häuptling, es tut mir leid.\n\nIch konnte nichts dagegen tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[66152] = { id = 66152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Entrinnen", description = "Wir können nicht hierbleiben.\n\nIch weiß nicht, was wir tun können... oder wohin gehen...\n\nWir werden zum Lager im Nirgendwo zurückkehren. Die Tuskarr sollten wissen, was hier bei den Rostkiefern passiert ist.\n\nWenn wir unsere Geschichte weitererzählen und bewahren, wird sie sich vielleicht nicht wiederholen...", sourceObjective = "Trefft Garz beim Lager im Nirgendwo.", completion = "Unser Klan wurde in Stücke gerissen.\n\nHoffentlich nimmt uns ein anderer auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[66154] = { id = 66154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speichelproben", description = "<Der magere Untote greift sich an die Stirn und seufzt tief.>\n\nDas wird mich gar nicht gut dastehen lassen. An nur einem Tag haben wir es geschafft, die ansässigen Gorlocs aufzuscheuchen, die Hälfte unserer Ausrüstung zu verlieren und jetzt sind wir auch noch um einen Zwerg ärmer.\n\nIn dieser Situation schreibt das Protokoll vor, dass wir so effizient wie möglich arbeiten. Geht und dünnt unsere gezahnten Antagonisten aus und bringt mir ihren Speichel zur Untersuchung, wenn Ihr schon dabei seid.\n\nNur das gute Zeug, wohl gemerkt.", sourceObjective = "Sammelt 12 Speichelproben an der Gorlocküste.", progress = "Habt Ihr die Proben bekommen?", completion = "Na, was sagt man dazu? Hier hat jemand wirklich etwas erreicht. Wie sagt man noch? Zwei für dich, einer für mich?\n\n<Rowe nimmt einen kleinen Schluck aus dem Humpen.>\n\nAh, das tut gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[66155] = { id = 66155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruriqs Stromschnellenritt", description = "Ich habe nicht mit der Zustimmung meines Bruders gerechnet... Aber sie ist willkommen.\n\nDie Zeit ist gekommen! Lasst uns sehen, ob unsere harte Arbeit sich ausgezahlt hat!\n\nTrefft mich auf der Fallschreiter, {name}, dann legen wir flussabwärts ab und fangen unterwegs Fisch für Iskaara!", sourceObjective = "Fahrt mit der Fallschreiter den Fluss hinunter.", completion = "Puh, was für ein Ritt! Ein Wunder, dass das Boot noch heil ist!\n\nVielen Dank, {name}. Das sollten wir noch mal machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[66156] = { id = 66156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesehen bei der Drachenschuppenexpedition", description = "Eure Taten sind nicht unbemerkt geblieben. Ihr stellt immer wieder unter Beweis, dass Ihr <ein berühmter Forscher/eine berühmte Forscherin> seid!\n\nKehrt ins Drachenschuppenbasislager zurück. Ich habe einige Vorräte vorbereitet, die Euch in Euren Anstrengungen unterstützen sollen.", sourceObjective = "Sprecht mit Katalogisiererin Jakes im Drachenschuppenbasislager.", completion = "Eure Taten steigern den Ruhm aller Forscher. Nehmt diese Vorräte, sie sollen Euch eine Hilfe sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[66159] = { id = 66159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schlimme Nachricht", description = "Kalecgos wollte nicht darüber sprechen, was im Azurblauen Gebirge passiert ist, bis Ihr eintrefft.\n\nAber was immer es auch ist... Ich empfinde eine unheilvolle Vorahnung, {name}.", sourceObjective = "Sprecht mit Alexstrasza beim Sitz der Aspekte in Valdrakken.", completion = "Raszageth! Sie versucht, sie zu finden... Das sind sehr verstörende Nachrichten.\n\nWir wissen nicht, wo ihre Primalisten als Nächstes zuschlagen. Unsere Stadt muss vor ihrem Chaos geschützt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[66163] = { id = 66163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Versteck", description = "Willkommen in Valdrakken, {race}.\nDas Klima in der Stadt war in letzter Zeit etwas erhitzt, und damit meine ich nicht das Wetter.\n\nDie Primalisten schleichen durch die Gassen und schüren Uneinigkeit unter den Bürgern unserer Stadt.\n\nUnsere Feinde verkleiden sich nun als gewöhnliche Bürger der Stadt, um sich vor den Eidschuppen zu verstecken. Sie wissen, wie sie meinen Wachen aus dem Weg gehen, aber vor einem Fremdling werden sie sich nicht in Acht nehmen.\n\nNehmt dieses Drachenaugenjuwel, damit werdet Ihr ihre Tarnung durchschauen können.\n\nGeht! Identifiziert diese Eindringlinge und tötet sie!", sourceObjective = "Tötet 6 Eindringlinge der Primalisten in Valdrakken.", completion = "Gut, das wird uns daran erinnern, die Primalisten in Valdrakken niemals willkommen sein werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[66164] = { id = 66164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischfinger", description = "Jetzt, da Mordigan Steine lutscht, können wir uns um das Hauptproblem kümmern...\n\nDiese perfiden Fischleute haben meine Teile geklaut!\n\nWir waren noch keine Stunde in diesem schäbigen kleinen Kaff, und ZACK! Haben Gorlocs uns von überall überschwemmt! Rowe hat geschrien, Aelnara hat geheult und ich meinen Schraubenschlüssel wie eine wahnsinnige Gnomin geschwungen!\n\nKönnt Ihr die Situation retten und mir einige meiner Teile zurückbringen?", sourceObjective = "Findet 5 gestohlene Teile an der Gorlocküste.", progress = "Das ist suboptimal.", completion = "Ihr seid zurück! Ich werde dann mal den Geoscanner 289-07 umkonfigurieren und so einsatzbereit wie zurzeit möglich machen. Die Bedingungen hier an der Küste sind allerdings nicht gerade ideal.", sourceObjectiveStatus = "unverified-source-field" }
quests[66166] = { id = 66166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen und Ohren", description = "Die Primalisten haben ihre Propaganda unter den Einwohnern von Valdrakken verbreitet.\n\nUnsere Feinde sind zu gerissen, um sich in Anwesenheit meiner Eidschuppen zu verplappern, aber vielleicht könnt Ihr Euch nah genug heranschleichen, um ihre Unterhaltungen zu belauschen.\n\nIch habe Orte auf Eurer Karte für weitere Untersuchungen markiert.\n\nIhr solltet besser den Transmogrifizierer aufsuchen, um Euer Aussehen zu verändern und so weniger aufzufallen.\n\nNehmt diesen verzauberten Stein mit. Solange Ihr ihn in Händen haltet, können wir miteinander kommunizieren.", sourceObjective = "Findet Hinweise in Valdrakken und sucht den Transmogrifizierer auf, um zu erfahren, wie Ihr Euer Aussehen verändern könnt.", progress = "Habt Ihr etwas Nützliches gefunden?", completion = "Die Primalisten haben also irgendetwas im Süden vor, und aus der Südfeste sind keine Soldaten gekommen... Das klingt nicht gut, {name}. Das klingt gar nicht gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[66167] = { id = 66167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entblößter Süden", description = "Basierend auf Euren Entdeckungen vermute ich, dass die Primalisten die Garnison von Kommandant Eranog an der Südfeste angreifen. Doch meine Eidschuppen können die Stadt nicht verlassen, denn das würde den Primalisten nur in die Hände spielen.\n\nIch brauche erneut Eure Hilfe, {name}.\n\nReist zur Südfeste und seht, was für Streitkräfte uns dort erwarten. Und wenn möglich, tretet mit den Garnisonswächtern dort in Kontakt.", sourceObjective = "Reist zum Tor der Südfeste, um mit den Garnisonswächtern Kontakt aufzunehmen.", completion = "Habt meinen Dank und meine Entschuldigung. Im Kampfgetümmel ist es schwer, Freund von Feind zu unterscheiden, und hier sind ziemlich viele Feinde.", sourceObjectiveStatus = "unverified-source-field" }
quests[66169] = { id = 66169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache, heiß serviert", description = "Die Primalisten haben uns komplett überrumpelt.\n\n<Velomir spuckt angewidert aus.>\n\nMeine Wächterkameraden wurden von diesen Monstern zerfleischt. Ich hätte mich ihnen im Tod angeschlossen, wärt Ihr nicht aufgetaucht.\n\nIn der Ferne kann ich immer noch den Lärm der Schlacht vernehmen. Vielleicht gibt es noch mehr Überlebende. Vielleicht lebt sogar Kommandant Eranog noch.\n\nHelft mir und lenkt sie ab, damit ich mich näher ranschleichen kann.\n\nEs wäre perfekt, wenn Ihr ein paar dieser sogenannten \"Magmagebundenen\" töten könntet.", sourceObjective = "Tötet 12 magmagebundene Primalisten am Tor der Südfeste.", completion = "Gute Arbeit, {class}. Diese Monster haben jedes bisschen Schmerz, das Ihr ihnen zugefügt habt, doppelt und dreifach verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[66170] = { id = 66170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stille Wache", description = "<Dori'thur schwebt still in der Luft und beäugt Euch erwartungsvoll.\n\nVielleicht möchte die edelmütige Eule, dass Ihr etwas Wichtiges seht.>", sourceObjective = "Seht Euch Dori'thurs Vision an.", completion = "<Dori'thur zwinkert wissend.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66173] = { id = 66173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halle der Proben", description = "Habt Ihr gehört, was diese Konsole gesagt hat?\n\nEs gibt eine Halle voller Proben. Uralte Titanenmaschinen? Proben aus einer anderen Welt? Tyr allein weiß, was sich dort befindet.\n\nÄndern wir das.", sourceObjective = "Erkundet die Halle der Proben.", progress = "Fragt Ihr Euch, was die Titanen noch für \"Proben\" gefangen haben?", completion = "Solltet Ihr Euer Abenteurerleben einmal an den Nagel hängen wollen, könntet Ihr bestimmt als Drachenbändiger arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[66174] = { id = 66174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halle der Aspekte", description = "Die Halle der Halle der Aspekte, hm? Warum sollte Tyr sowas wegsperren? Hat er was zu verbergen?\n\nDas impliziert Erstaunliches! Hoffentlich finden wir da drinnen Antworten.", sourceObjective = "Erkundet die Halle der Aspekte.", progress = "Hüpfen wir durch diesen Transporter, bevor Naleidea noch kalte Füße bekommt!", completion = "Mir ist egal, was Naleidea sagt. Ich wusste von Anfang an, dass Ihr die richtige Wahl seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[66175] = { id = 66175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldexperiment", description = "Dank Euch arbeitet unsere geologische Untersuchung mit beinahe 96%iger Effizienz! \n\n<LOU-C zieht die Augenbrauen zusammen.>\n\nDas sind Anfängerzahlen.\n\nHelft mir, Eure gesammelten Proben mit dem Geoscanner 289-07 zu prüfen. Es sollte uns eine Grundvorstellung davon geben, was genau auf dem Plateau vor sich geht.", sourceObjective = "Helft LOU-C dabei, ihre Tests in Walfängerwinkel durchzuführen.", progress = "Für die Wissenschaft!", completion = "Man soll zwar immer mit allem rechnen, aber alle Achtung... Das gab es wirklich noch nie!", sourceObjectiveStatus = "unverified-source-field" }
quests[66176] = { id = 66176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Experimente", description = "Geht und führt Experimente an den Wasserelementaren durch, die die Gorlocs belästigen!", sourceObjective = "Führt 6 Elementarexperimente an der Gorlocküste durch.", sourceObjectiveStatus = "unverified-source-field" }
quests[66177] = { id = 66177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Zwerg bleibt zurück", description = "Das Salzniveau hier sprengt die Skala! Wir müssen Mordigan finden und ihn hier rausholen. Er muss inzwischen lebensgefährlich dehydriert sein.\n\nEr ist erst seit einigen Stunden fort. Versucht herauszufinden, welchen Weg der grimmige, alte Zwerg genommen hat!", sourceObjective = "Folgt der Spur von Mordigan Eisenkiefer entlang der Gorlocküste.", completion = "Ihr wart beschäftigt. Ich ebenfalls.", sourceObjectiveStatus = "unverified-source-field" }
quests[66178] = { id = 66178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Tag im Hain", description = "Rymek wurde vom blauen Drachenschwarm hergeschickt, um mehr über unsere Gärten zu erfahren und sie zu beschützen.\n\nIch freue mich über die Unterstützung. Wir sind nicht viele und haben schwere Verluste erlitten. Der blaue Drachenschwarm beherrscht mächtige Magie, wir können also viel voneinander lernen.\n\nKommt. Lasst uns demonstrieren, welche wichtige Rolle dem grünen Drachenschwarm hier auf den Dracheninseln zukommt.", sourceObjective = "Trefft Euch mit Merithra und Rymek bei der Grünen Rast in den Smaragdgärten.", completion = "Hier ist es so friedlich.\n\nSomnikus ruht sich hier am liebsten aus, doch... seitdem sein Sohn bei den Angriffen der Zentauren ums Leben kam, ist er ziemlich missmutig.\n\nAber wir sollten uns auf die Gegenwart konzentrieren. Lasst uns Rymek zeigen, was wir hier im Hain machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66179] = { id = 66179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Saat der Zukunft", description = "Der Angriff der Primalisten hat in den Smaragdgärten seine Spuren hinterlassen. Ich wünsche mir, dass sie wieder wachsen und gedeihen.\n\nIn diesem Teil des Gartens gibt es ein Übermaß an Peitschern. Ihre Samen können von den Schwestern des Gartens dazu verwendet werden, in diesen geschundenen Lichtungen wieder Pflanzen zu kultivieren.\n\nErledigt Peitscher, um deren Samen zu erhalten, und gebt diese dann an die Schwestern. Sie tun sich manchmal schwer daran, anderen Kreaturen Schaden zuzufügen, selbst, wenn es im besten Interesse der Gärten als Ganzes ist.", sourceObjective = "Sammelt Samen von verschiedenen Peitschern und bringt sie zu den Schwestern des Gartens.", completion = "Danke. Keine Angst, die Peitscher wachsen sehr schnell nach. Sie werden sich rasch wieder erholt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[66180] = { id = 66180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erweckt die Urtume", description = "Es gibt viele Wege, die Gärten zu schützen. Und wir haben Verbündete, die uns dabei helfen.\n\nAuf diesen Lichtungen ruhen einige Urtume. Sie sind riesige Bäume, die geschworen haben, den Wald und seine Bewohner zu verteidigen.\n\nNutzt dieses Fragment meines Atems, um sie zu wecken.", sourceObjective = "Benutzt Merithras geborgten Atem, um die uralten Wächter in den Smaragdgärten zu wecken.", completion = "Eines der Urtume wurde getötet? Durch Frost?\n\nDas verheißt nichts Gutes. Wir müssen wachsam sein. Die Primalisten könnten gerade einen weiteren Angriff auf den Garten vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[66181] = { id = 66181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein rasender Verteidiger", description = "Mir ist aufgefallen, dass diese Gärten über eine recht vielfältige Verteidigung verfügen. Von Drachen, Drakoniden und Urtumen bis hin zur Tierwelt.\n\nDoch es gibt einen Verteidiger, der in seiner Beschützerrolle etwas zu eifrig geworden ist. Er wollte sich bei meiner Ankunft sogar auf mich stürzen!\n\nUnd da wir wissen, dass in diesem Hain etwas auf der Jagd ist, kann man nicht zu vorsichtig sein.\n\nLeider muss diese Kreatur getötet werden, bevor sie noch mehr Schaden anrichten kann.", sourceObjective = "Tötet die rasende Hainkralle.", completion = "In den Gärten ist es schon viel friedlicher geworden, findet Ihr nicht auch?\n\nIhr seid wirklich gut, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66182] = { id = 66182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerithus' Forschung", description = "Der grüne Drachenschwarm hat viele verschiedene Aufgaben und kümmert sich nicht ausschließlich um den Garten. Wir beschützen auch den Smaragdgrünen Traum, und einige von uns weiten ihr Augenmerk auch auf andere Gebiete aus.\n\nMein Sohn Gerithus hatte zum Beispiel schon immer Interesse an allerlei Formen der Magie.\n\nIhr solltet ihn zusammen mit Rymek aufsuchen, um zu sehen, woran er gerade arbeitet, und ihm zu helfen, wo Ihr könnt.", sourceObjective = "Trefft Euch mit Gerithus tiefer in den Smaragdgärten.", completion = "Willkommen! Schön, dass meine Mutter so an meiner Forschung interessiert ist. Auch wenn es etwas weit hergeholt ist.\n\nAber ich bin mir sicher, dass Rymek als Abgesandter des blauen Drachenschwarms ein wesentlich besseres Verständnis der Magie haben wird als ich. Ich hoffe, dass wir gute Fortschritte erzielen.\n\nLasst uns loslegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[66183] = { id = 66183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smaragdgrüne Tränen", description = "Wir sind zwar erst vor vergleichsweise kurzer Zeit zu den Smaragdgärten zurückgekehrt, doch unsere langanhaltenden Gefühle tragen wir immer noch in uns.\n\nViele unter uns sind nach wie vor von Yseras Tod, vom Tod meiner Großmutter, erschüttert. Dazu zähle auch ich. Ich wünschte, ich hätte mehr Zeit mit ihr verbringen und von ihr lernen können. Welch atemberaubende Dinge sie in ihrem Leben gesehen haben muss!\n\nWenn wir an Orten wie den Smaragdgärten Tränen vergießen, können diese kristallisieren und große Kraft in sich tragen. Ich habe da eine Idee, wie wir diese Manifestationen der Trauer zu etwas Gutem nutzen können.", sourceObjective = "Sammelt 8 smaragdgrüne Tränen.", progress = "Habt Ihr einige der smaragdgrünen Tränen im Garten gesammelt?", completion = "Das sind wundervolle Proben, {name}. Dann wollen wir mal sehen, was wir damit anstellen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[66184] = { id = 66184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebensanker", description = "Basierend auf meiner Forschung, glaube ich, dass es einen Weg gibt, Yseras Verbindung zum Smaragdgrünen Traum wiederherzustellen und sie näher nach Azeroth zu bringen.\n\nAls Ysera starb, hat die Winterkönigin ihre eigene Kraft dazu benutzt, sie im Ardenwald wiederzuerwecken. Für den Moment ist sie dort gebunden, doch wenn wir sie in den Smaragdgrünen Traum bekommen, können wir, glaube ich, diese Anker dazu benutzen, sie dort zu halten.\n\nDoch eins nach dem anderen.\n\nZunächst müssen wir diese Anker mit der Macht der smaragdgrünen Tränen erfüllen.", sourceObjective = "Ermächtigt die inaktiven Anker mit den smaragdgrünen Tränen.", completion = "Das ist es! Ich spüre die Macht in den Ankern.\n\nNun bleibt nur noch das kleine Problem, Ysera aus dem Totenreich wieder ins Reich der Lebenden zurückzuholen. Aber eins nach dem anderen.\n\nIch bringe diese Anker zur sicheren Verwahrung in die Schattenzuflucht.\n\nMeine Mutter ist hier. Sie möchte Euch und Rymek bestimmt noch mehr zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66185] = { id = 66185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch den Wald", description = "Es ist an der Zeit. Ich weiß, dass ich gesagt habe, es würde mir gut gehen, doch seit Solethus' Tod fühle ich mich, als würde mir etwas Essenzielles fehlen.\n\nIch lebe und er tut es nicht. Das fühlt sich... falsch an.\n\nAber vielleicht gibt es einen Weg, wie ich das wieder hinkriegen kann. Ysera ist die Einzige, die uns dabei helfen kann, den Uralten Zweig wieder unter Kontrolle zu bekommen. Und ich glaube, ich kann helfen, sie wieder zurückzubringen.\n\nDoch es wird immer schwieriger, auf die andere Seite zu kommen. Dieser Versuch muss gelingen.\n\nTyrande und Malfurion werden uns dort treffen.", sourceObjective = "Trefft Euch mit Somnikus im Hain des Erwachens im Ardenwald.", completion = "Seid gegrüßt. Somnikus hat mir von der ernsten Bedrohung der Smaragdgärten erzählt und seinem eigenen Anteil daran.\n\nAber ich fürchte, die Lösung wird nicht so leicht werden, wie er hofft.", sourceObjectiveStatus = "unverified-source-field" }
quests[66186] = { id = 66186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis", description = "Ich sehne mich danach, zum Smaragdgrünen Traum zurückzukehren und die Gärten vor den Inkarnationen und ihren Anhängern zu beschützen. Aber ich kann den Ardenwald noch nicht verlassen, nicht mit meiner Verbindung zur Winterkönigin.\n\nIch würde es nie wagen, jemanden darum zu bitten. Es sei denn, er oder sie akzeptiert die Konsequenzen. So, wie ich es einst tat.\n\nDoch es gibt da jemanden, der meinen Platz einnehmen könnte.", sourceObjective = "Wohnt der Entscheidung bei.", completion = "Abgemacht. Ich bleibe im Ardenwald.\n\nIch bleibe, um den Traum zu beschützen und die Hoffnung, die darin sprießt. Nur ich kann das tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[66187] = { id = 66187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verrückte Mordigan und der Kristallkönig", description = "Ich habe die Umgebung durchsucht. Wenn Mordigan irgendwo hier ist, muss er in dieser Höhle sein.\n\n<Dumpfe Flüche und Beleidigungen hallen aus dem Höhleneingang.>\n\nEr ist definitiv in dieser Höhle.\n\nLOU-C hat gesagt, diese Kristalle haben gefährliche dehydrierende Eigenschaften. Versucht, ihn von seinen... geologischen Funden zu trennen. Aber tut ihm nicht allzu sehr weh.\n\nEr ist in seinem Fachbereich ziemlich angesehen.", sourceObjective = "Dekristallisiert Mordigan Eisenkiefer an der Gorlocküste.", completion = "Das ist zwar nicht gerade eine elegante Lösung, aber ich weiß Euer schnelles Denken und Euren... Einfallsreichtum zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66188] = { id = 66188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmruh", description = "Lasst uns zum Hain des Erwachens gehen. Die Winterkönigin ist die Einzige, die dieses Band von Ysera auf mich übertragen kann. Ich bin zuversichtlich, dass sie dem zustimmen wird. Sie hat Ysera in verzweifelten Zeiten geholfen, und nun kann Ysera die Hilfe erwidern.\n\nWenn die Winterkönigin zustimmt, werde ich vermutlich nicht lange wach bleiben können. Die Last der Verbindung wird schwer zu stemmen sein.\n\nIch hoffe, dass ich irgendwann wieder aufwachen kann, um die ausgewachsene Macht des neuen Baumes mit eigenen Augen sehen zu können.", sourceObjective = "Aktiviert die Globen der Wiedergeburt im Hain des Erwachens.", progress = "Ich sehne mich danach, die verdrehte grüne Weite des Traums ein weiteres Mal zu sehen.", completion = "Es ist vollbracht. Malfurion wird hier an meiner statt schlafen. Und Tyrande wird weiterhin über ihr Volk wachen, so wie sie es schon seit Jahrtausenden tut.\n\nWir müssen uns jetzt bereit machen. Wenn ich in den Smaragdgrünen Traum übergehe, gibt es ein kurzes Zeitfenster, in dem Ihr Euch mir anschließen könnt.\n\nSeid Ihr bereit?", sourceObjectiveStatus = "unverified-source-field" }
quests[66189] = { id = 66189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schritt ins Leben", description = "Wir können nicht länger warten. Ich kann spüren, wie die Energien der Wiedergeburt in mir anschwellen. Ich bin bereit, in den Smaragdgrünen Traum zurückzukehren.\n\nAus den Reichen des Todes in die des Lebens.\n\nFolgt mir durch das Tor des Erwachens, und wir werden über den Traumpfad zum Uralten Zweig eilen. Ich vermute, dass es auf dem Weg etwas Widerstand geben wird, also seid auf der Hut.", sourceObjective = "Kämpft Euch mit Ysera durch den Smaragdgrünen Traumpfad und begebt Euch zum Uralten Zweig.", completion = "Es ist schlimmer, als ich befürchtet hatte. Ich kann das Eis zerschmettern, das den Hain umgibt, doch es warten zu viele Feinde auf uns. Und wir müssen einen Weg finden, die Barriere zu deaktivieren, die die anderen draußen hält.\n\nWir müssen uns beeilen und diese Feinde erledigen, damit Merithra und die anderen zu uns gelangen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[66190] = { id = 66190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So knapp", description = "Ich muss diesen Moment nutzen, Euch für all Eure Hilfe zu danken, {name}.\n\nIch hätte wahrlich nie erwartet, je eine Chance zu erhalten, den Traum im Uralten Zweig zu bestaunen. Nicht als bescheidener Botschafter. Das war wirklich lieb.\n\nLord Somnikus hat mir gnädigerweise gestattet, die Lichtung zu betreten und das Portal zu sehen. Es wäre mir eine Ehre, Euch bei meinem Besuch dabeizuhaben.\n\nIch werde mich den Rest meines Lebens an diesen Moment erinnern. Teilt ihn mit mir.", sourceObjective = "Betretet den Traumportalhain mit Rymek.", completion = "Nicht... zu fassen...\n\nDas kann nicht sein.\n\nIch habe versagt. Ich habe Rymek und seinen Drachkin vertraut... und sie haben uns alle hintergangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66191] = { id = 66191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und doch so fern", description = "Ich kann hier nicht mehr so wie früher in den Traum schlüpfen. Da die Verteidigungen des Zweigs aktiviert sind, sind wir im Grunde genommen vom Hain abgeschirmt.\n\nUnd ich fürchte, dass es noch schlimmer wird, {name}.\n\nIch fürchte, dass Rymek uns nicht nur hintergangen hat, um in den Traum zu gelangen. Ich glaube, dass er nach etwas Bestimmtem sucht. Etwas, das kostbar und mächtig ist und das ich zu beschützen geschworen habe.\n\nNicht einmal Gerithus und Somnikus wussten davon. Aber jetzt sind mir die Hände gebunden. Ihr müsst die Wahrheit erfahren.", sourceObjective = "Sprecht mit Merithra.", completion = "Die Lage ist ernst. Rymek hat uns wenige Möglichkeiten gelassen.\n\nEin großes Opfer ist vonnöten und uns bleib keine Wahl.\n\nAuch wenn wir von dieser Seite nicht in den Hain gelangen, gibt es noch einen anderen Weg dorthin... jenseits der Welt der Lebenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[66196] = { id = 66196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hilfequaken", description = "<Das Entchen schlägt in der Blase wild um sich und quakt verängstigt.>\n\n<Vielleicht wissen die Ökologen, wie man ihm helfen kann?>", sourceObjective = "Bringt das Entchen in der Blase zurück ins Ökologenlager.", progress = "<Tharu redet beruhigend auf das Entchen in der Blase ein.>\n\nSchhh, nicht weinen, mein Kleines.\n\nWir großen, starken Ökologen werden auf Euch aufpassen! Und {name} natürlich auch.", completion = "Wir kümmern uns um Watschel. Sagt Bescheid, falls Ihr noch weitere verirrte Entchen dort draußen finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[66201] = { id = 66201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hufe des Krieges", description = "Balakar wird seine Streitkräfte für den Krieg aufstellen. Ich werde es ihm gleichtun, doch wir sind zahlenmäßig unterlegen.\n\nDie Drachen haben um unsere Hilfe gebeten... und jetzt können wir ihre Hilfe brauchen, uns eine faire Chance zu geben. Um ihrem Ruf nach einem Bündnis zu antworten, muss ich das Horn von Drusahl blasen, doch ich brauche Ohn'ahras Segen. Werdet Ihr mir helfen?\n\nGeht nach Teerakai und übergebt meine Kriegserklärung an meinen Leutnant, Jebotai. Er wird meine Streitkräfte zusammentrommeln und Euch den Weg zu den Mystikern zeigen, die Ohn'ahra finden können.", sourceObjective = "Bringt die Nachricht der Khanam Matra zu Khanswache Jebotai in Teerakai.", progress = "Was wollt Ihr, Fremdling?", completion = "<Jebotai liest die Nachricht. In seinem Gesicht zeichnet sich nach und nach immer größere Besorgnis ab.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66203] = { id = 66203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spült über sie hinweg" }
quests[66206] = { id = 66206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nozdormu, ich komme, um zu verhandeln" }
quests[66210] = { id = 66210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Familie zusammenrufen", description = "Euer Freund Kalecgos möchte über Leylinien sprechen, aber es müssen Vorbereitungen für die Bestattung getroffen werden.\n\nKönntet Ihr die letzten Opfergaben aus der Umgebung von Iskaara einsammeln und sie im Bestattungsboot neben den guten alten Ponoliak legen, während ich mich mit ihm treffe?\n\nIch hoffe, Ihr nehmt Euch die Zeit, um auch die Stadt zu genießen! Mein Volk wird Euch herzlich willkommen heißen, insbesondere nach Eurer Hilfe in Brackenfell.", sourceObjective = "Sammelt 4 Bestattungsgaben in der Gegend von Iskaara und legt sie dann in das Bestattungsboot.", progress = "Habt Ihr Euch einen Teller Suppe geholt?", completion = "Euer Freund ist sehr wissbegierig! Nimmt er sich jemals Zeit, um sich zu entspannen?", sourceObjectiveStatus = "unverified-source-field" }
quests[66211] = { id = 66211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brackenfellhöhle: Zur Quelle", description = "Wir können Euch für Eure Hilfe, die Brackenfellgnolle zurückzuschlagen, nicht genug danken.\n\nAber sie sammeln sich weiter und beziehen ihre Verfallmagie aus irgendeiner Quelle tief im Inneren der Brackenfellhöhle. Schlimmer noch, wir haben seit Wochen nichts mehr von den Tuskarr aus der Gegend gehört.\n\nIch fürchte, dort könnte etwas Furchtbares vorgefallen sein. Wir müssen unsere Heimat schützen. Bitte, sammelt Eure Streitmacht, findet unsere Leute und seht, was Ihr gegen diesen Verfall unternehmen könnt!", sourceObjective = "Betretet die Brackenfellhöhle und stellt Faultriarchin Zornauge.\n\nIhr könnt die Brackenfellhöhle allein betreten, wenn Ihr Euch über die Anhängerdungeons anmeldet.", progress = "Wir müssen unsere Leute retten und die Ausbreitung des Verfalls aufhalten!", completion = "Ohne Euch wäre Iskaara verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[66212] = { id = 66212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angeln: Querflossen-Flügelrossfisch", description = "Weiß denn NIEMAND mehr, wie man RICHTIG angelt?\n\n<Lukoturukk zuckt wütend mit seiner Nase.>\n\nIhr da mit dem komischen Gesicht, bringt mir ein paar Fische. Und zwar FEINE Fische. Keine Grungeln!", sourceObjective = "Zieht 5 Querflossen-Flügelrossfische aus dem Meer um die Dracheninseln.", progress = "Na, was habt Ihr gefangen? \n\nBitte keine mageren, kleinen Ancheevies.", completion = "Hmmpf.\n\nHmmmmmpf.\n\n...Ihr seid nicht völlig nutzlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[66213] = { id = 66213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Weben einer Geschichte", description = "Meine liebe Frau, Poa, ist eine großartige Geschichtenerzählerin.\n\nAber dreißig Jahre sind vergangen, und sie erzählt manche immer und immer wieder! Bitte, {class}, sprecht mit Poa und erzählt ihr eine neue Geschichte.\n\nWas sagt Ihr? Ihr wollt ihr von Euren Abenteuern erzählen? Macht Euch nicht lächerlich, davon will ich nichts hören. Die besten Geschichten handeln immer von Fisch. Erzählt ihr eine Geschichte über Fisch, und wenn Ihr Euch eine ausdenken müsst!", sourceObjective = "Erzählt der Ältesten Poa eine Geschichte über Fisch.", completion = "Meine Güte, eine neue Geschichte.\n\nLasst hören!", sourceObjectiveStatus = "unverified-source-field" }
quests[66217] = { id = 66217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Krojek der Küstenstreifer", description = "Wir haben den großen Hai beobachtet, der seit vielen Jahren als Krojek bekannt ist, und warten auf die beste Gelegenheit, ihn zu erlegen.\n\nSeine Jagdgründe haben sich immer näher an die Küste verschoben. Das bedeutet, dass es an der Zeit ist. Versammelt Euren Jagdtrupp und streckt ihn nieder!", sourceObjective = "Tötet Krojek den Küstenstreifer.", completion = "So ist der Kreislauf des Seelebens hier draußen. Einige lassen wir in Ruhe, damit ihre Art weiterlebt. Einige dezimieren wir, einige essen wir. Alles im Gleichgewicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[66218] = { id = 66218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Störende Strolche", description = "Hallo noch mal.\n\nKönntet Ihr Norukk und mir einen Gefallen tun? Unsere Kinder Neelo und Nau sind zum Spielen rausgegangen. Sie wissen, dass sie längst zurück sein sollten.\n\nIch bin beschäftigt, also bitte geht sie suchen. Ich bezweifle, dass sie in Gefahr sind, meine Kinder wissen sich zu helfen.", sourceObjective = "Findet Neelo und Nau.", completion = "Angeblich sind ja alle Gnolle gemein und gefährlich. Aber das ist nur ein Baby!\n\nMama sagt, dass ich immer auf Nau aufpassen muss, und die ist auch ein Baby.", sourceObjectiveStatus = "unverified-source-field" }
quests[66221] = { id = 66221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es geht voran", description = "Mit der Wiederherstellung des Bronzeschwursteins kann Alexstrasza mit ihrem Plan fortfahren.\n\nReist nach Valdrakken, {name}. Sie wird von Eurem Erfolg hören wollen.", sourceObjective = "Sprecht mit Alexstrasza beim Sitz der Aspekte in Valdrakken.", progress = "Ich danke Euch, {name}.", completion = "{name}, bitte nehmt meinen aufrichtigen Dank an für alles, was Ihr getan habt. Ich gebe Euch Bescheid, wenn die Zeit gekommen ist, mich bei diesem nächsten Schritt zu begleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[66222] = { id = 66222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruhe vor dem Sturm", description = "Die Nokhud sind mächtig und haben viele Verbündete. Es wird uns alles abverlangen, ihnen standzuhalten.\n\n{name}, Ihr habt das Vertrauen der Khanam Matra. Ihre Befehle waren, unser Volk vorzubereiten und unsere Freunde zu versammeln.\n\nIch brauche Eure Hilfe. Sucht Hojin auf, um den Rest der Khanswache zu mobilisieren. Macht Späherin Khenyug auf mögliche Orte aufmerksam, an denen die Nokhud eindringen könnten. Informiert Agura, dass mit Verwundeten zu rechnen ist, und sagt Gensai, dass er unsere Verpflegung vorbereiten soll.\n\nBezüglich der Mystiker... Ich glaube, dass sie vor Kurzem aufgebrochen sind. Ich werde prüfen, ob sich in Teerakai noch jemand von ihnen befindet.", sourceObjective = "Kommuniziert Jebotais Befehle an die Bewohner von Teerakai.", progress = "Wir treffen nicht alle Tage auf Außenseiter. Und es passiert noch seltener, dass sie uns so helfen, wie Ihr es tut. Vielen Dank.", completion = "Ich wollte keine Panik auslösen, aber unsere Leute müssen vorbereitet sein. Klan Nokhud ist bekannt dafür, keine Gnade zu zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66223] = { id = 66223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Können wir das behalten?", description = "Er versucht nur, uns zu essen, weil er so hungrig ist!\n\nFisch! Niemand kann so leckeren, eiskalten, rohen Fisch abschlagen!\n\nEiswasserfische sind das Beste überhaupt! Ihr könnt sie überall im Ozean angeln! Aber falls Ihr selbst nicht angeln könnt, wird Euch Jinkutuk in Iskaara bestimmt welche verkaufen.\n\nBringt mir so viele, bis er nicht mehr hungrig ist!", sourceObjective = "Bringt Neelo 7 Eiswasserfische. Kauft sie entweder in Iskaara oder angelt sie in einem beliebigen Ozean der Dracheninseln.", progress = "So viel Fische! Ich will sie alle essen!\n\n...Aber nein. Sie sind für Scaps. Das ist wichtig.", completion = "Scaps wird davon ganz begeistert sein und dann werden wir beste Freunde!", sourceObjectiveStatus = "unverified-source-field" }
quests[66224] = { id = 66224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystisches Mysterium", description = "Es tut mir leid, ich habe es nicht geschafft, mit Ohn'ahra Zwiesprache zu halten. Ihr werdet jemand anderen finden müssen, der die Bitte der Khanam Matra erfüllt.\n\nVor einigen Tagen wurden die anderen Mystiker im Zuge einer dringenden Bitte von Tigari Khan zur Gratwasserzuflucht gerufen. Sie sollten noch dort sein.\n\nTrefft mich außerhalb der Stadt. Das Mindeste, das ich tun kann, ist, Euch den Weg dorthin zu zeigen.", sourceObjective = "Trefft Euch mit Boku und reist zur Gratwasserzuflucht.", progress = "{name}, es geht Euch gut! Ohn'ahra sei Dank.\n\nOh! Das sind meine Totems.", completion = "Ich bin bei diesem Hinterhalt gerade noch so mit dem Leben davongekommen. Ich fürchte, die anderen Mystiker hatten nicht ganz so viel Glück...", sourceObjectiveStatus = "unverified-source-field" }
quests[66225] = { id = 66225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totale Totems", description = "Boku hat gefragt, warum ich eine Nachricht entsandt habe, die alle Mystiker zur Gratwasserzuflucht ruft.\n\nIch habe keine solche Nachricht entsendet. Balakar hat meine Mystiker vorsätzlich in eine Falle geführt, um Klan Ohn'ir zu schwächen.\n\nDoch vielleicht gibt es noch einen weiteren Grund. Die Nokhud sammeln mystische Totems, so viele sie finden können. Diese Totems sind von Ohn'ahra gesegnet.\n\nEs nicht klar, was die Nokhud damit vorhaben, doch wir dürfen nicht zulassen, dass sie sich an Ohn'ahras Geschenken bedienen. Bringt so viele Totems zurück, wie Ihr könnt.", sourceObjective = "Sammelt 8 Totembündel von den Nokhud bei der Gratwasserzuflucht.", progress = "Die Totems sind mit Ohn'ahras Windmagie erfüllt.\n\nDoch die Nokhud haben ihre Lehren aufgegeben. Was haben sie vor?", completion = "So viele Totems. So viele gefallene Mystiker.", sourceObjectiveStatus = "unverified-source-field" }
quests[66226] = { id = 66226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begleiter für seelischen Beistand", description = "Bitte tut mir nicht weh...\n\nWas? Ihr seid hier, um zu helfen? Ihr müsst die Tiere retten!\n\nDie Nokhud haben ohne Vorwarnung angegriffen. Wir alle sind um unsere Leben gerannt! Ich konnte dem Tod gerade noch entkommen, indem ich in den See gesprungen bin.\n\nDie Tiere! Wir haben sie zurückgelassen. Bitte, ich flehe Euch an, rettet sie. Wer weiß, welche Grausamkeiten die Nokhud für sie geplant haben.", sourceObjective = "Rettet die unschuldigen Kreaturen vor den Nokhud bei der Gratwasserzuflucht.", progress = "Als Initianden praktizieren wir unsere heilenden Künsten, indem wir verwundete Kreaturen gesund pflegen.\n\nEs waren vier Tiere in unserer Obhut. Es wäre eine große Erleichterung, wenn Ihr so viele wie möglich von ihnen retten könntet.", completion = "Ihr habt sie gerettet! Sie sind zwar etwas mitgenommen, aber sie leben und werden sich wieder erholen.\n\nDanke, Fremder. Bitte, nehmt dies als Zeichen unseres ewigen Danks.", sourceObjectiveStatus = "unverified-source-field" }
quests[66227] = { id = 66227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutes Angeln", description = "Ein neues Paar Hände! Ich könnte etwas Hilfe brauchen, um genug Fisch für ein feines Essen zu fangen.\n\nDiese Kirin Tor scheinen über etwas in dieser Gegend beunruhigt zu sein, was sie magische Anomalien nennen, was immer das sein mag.\n\nEs sind alle willkommen, hierzubleiben, solange sie mit anpacken und mithelfen.\n\nNehmt Euch eine Angel und fangt an, zu fischen. Je mehr Hände, umso leichter die Arbeit!", sourceObjective = "Fangt 3 Blauflossenelritzen an Khuris Angelplatz.", progress = "Lasst es mich wissen, wenn Ihr ein paar Tipps braucht.", completion = "Ah, das ist goldrichtig! Danke, Abenteurer!", sourceObjectiveStatus = "unverified-source-field" }
quests[66228] = { id = 66228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lager Antonidas", description = "Die Kirin Tor haben unser Hauptlager südlich von hier aufgeschlagen: Lager Antonidas.\n\nIch glaube, Noriko und Khadgar sind gerade dort und rekrutieren Abenteurer, um Kalecgos bei der Rückeroberung des Azurschwursteins zu helfen.\n\nWenn Ihr unsere Sache unterstützen wollt, geht dorthin.", sourceObjective = "Trefft Euch mit Noriko der Allerinnernden im Lager Antonidas.", completion = "Ah, {name}. Es ist gut, Euch zu sehen...\n\nWartet... Spürt Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[66230] = { id = 66230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bilderbuchauftrag", description = "Die Tarasek haben alles mitgenommen, was sie in ihre Klauen bekommen konnten, inklusive meines Registers.\n\nDiese übergroßen Eidechsen horten Schmuckstücke und Trophäen zuhauf. Ich bin sicher, dass sie mein Register auch irgendwo verstaut haben. Könntet Ihr ein Auge danach offen halten, während Ihr auf dem Weg über den Pass seid?\n\nOh, und, {name}, wenn es Euch gelingt, es zu finden, seht nicht hinein. Der Inhalt ist gewissermaßen... privat.", sourceObjective = "Findet Alvis \"Register\" und bringt es zu Wegbehüterin Alvi.", progress = "Habt Ihr noch etwas gefunden, {name}?", completion = "Ah... Ihr habt es tatsächlich gefunden.\n\nDas ist in Wahrheit eher ein Skizzenbuch als ein Register. So weit ich mich zurückerinnern kann, war ich immer mehr am Zeichnen als am Erkunden interessiert...\n\n<Alvi stößt einen langen, tiefen Seufzer aus.>\n\nVielleicht wäre Nori nichts zugestoßen, wenn ich meine Aufgabe ordentlich erfüllt hätte.\n\nIch muss das in Ordnung bringen... aber ich weiß nicht, ob ich das alleine schaffe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66232] = { id = 66232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salziger Affront", description = "Wir würden Euch und Eure Freunde gerne als unsere Gäste wissen, nicht, dass jemand gefragt hätte. Aber wärt Ihr so <ein guter Nachbar/eine gute Nachbarin> und würdet mir einige Kristallflocken mitbringen, wenn Ihr an den Quellen vorbeikommt? Wir nutzen sie, um alle möglichen Dinge zu konservieren. Und wenn es um die Lagerung von Essen geht, ist das hier unerlässlich.\n\nDie größeren Gorlocs sind über und über mit dem Zeug bedeckt. Vielleicht könnt Ihr ja von denen ein paar Flocken ergattern.", sourceObjective = "Sammelt 120 Kristallflocken an der Gorlocküste.", progress = "Jetzt, wo Ihr es sagt, ich bin in der Tat sehr hungrig.", completion = "Das wird uns in dieser Gegend eine große Hilfe sein. Möglicherweise dürfen Eure Freunde doch noch etwas hierbleiben...", sourceObjectiveStatus = "unverified-source-field" }
quests[66236] = { id = 66236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gefangener Wind", description = "Die Nokhud sammeln Totems. Die Primalisten fangen Ohuna. Und Ohn'ahra schweigt.\n\nWas auch immer die Nokhud vorhaben, wir müssen sie daran hindern. Ihr müsst zusammen mit Boku zur Windspielanhöhe reisen. Vermutlich warten unsere Feinde dort bereits.\n\nSucht dort nach Ohn'ahra. Wenn ihre Kinder in Gefahr sind, wird sie sich zweifelsohne zu ihnen begeben... und wir müssen ihr helfen. Die Windmutter ist mächtig, doch ich fürchte, zu was diese Primalisten imstande sind.", sourceObjective = "Trefft Boku bei der Windspielanhöhe.", completion = "Balakar und diese Primalisten sind auf unseren heiligsten Überzeugungen herumgetrampelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66237] = { id = 66237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirituelle Verbündete", description = "Unsere Ankunft wird nicht unbemerkt bleiben.\n\nGestattet mir, mit ihnen zu sprechen, bevor wir eintreten. Ich habe so etwas wie eine gemeinsame Geschichte mit dem Rat.\n\nWir haben später noch genug Zeit, alle vorzustellen.", sourceObjective = "Sprecht mit den Behörden.", completion = "Ein wärmeres Willkommen, als ich befürchtet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[66239] = { id = 66239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbreitender Verfall", description = "<Brena wendet Kargtatzes Totem immer wieder in ihren großen Pranken hin und her.>\n\nKargtatze ist nur eine Schachfigur. Er ist nicht die Quelle dieser Fäulnis. Wir müssen sie finden, bevor sie sich noch weiter ausbreitet.\n\nDie nächste Tuskarrsiedlung von hier ist ein Handelsaußenposten, gleich am anderen Ende der Brücke nach Iskaara.\n\nWir sollten nach ihnen sehen... und zwar schnell.", sourceObjective = "Trefft Euch mit Brena am Handelsaußenposten.", completion = "Wie ich befürchtet habe, wurden sie ebenfalls angegriffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66241] = { id = 66241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rennen von Thaldraszus", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren." }
quests[66242] = { id = 66242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wetterkontrolle", description = "Dieser unnatürliche Sturm ist mit Magie aufgeladen. Die Nokhud scheinen zu lernen, die heilige Essenz der Windspielanhöhe zu manipulieren, um Sturmelementare zu erschaffen. Manche haben mehr Erfolg als andere...\n\n<Boku deutet auf einen unglücklichen Initianden der Nokhud in der Nähe, der immer noch von Blitzen verbrannt raucht.>\n\n{name}, wir dürfen nicht zulassen, dass sie weitermachen.", sourceObjective = "Tötet 8 sturmgebundene Essenzen und 6 Sturmruferinitianden.", completion = "Ich will kein Blut vergießen, aber die Nokhud müssen aufgehalten werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[66243] = { id = 66243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk der Hoffnung", description = "Seid gegrüßt, <Schlundgänger/Schlundgängerin>.\n\nIch bringe Euch eine Einladung der Winterkönigin. Sie bittet Euch, in den Ardenwald zu kommen, um einer Zeremonie mit anderen aus Eurer Welt beizuwohnen.\n\nShandris Mondfeder wird bei ihnen sein. Ihr findet sie im Hain des Erwachens.", sourceObjective = "Trefft Euch mit Shandris Mondfeder im Hain des Erwachens.", completion = "Das Geschenk der Winterkönigin... Was wir gerade erlebt haben...\n\n<In Shandris' Augen treten Tränen der Hoffnung.>\n\nWir müssen Ysera bitten, diesen kostbaren Samen zu hüten.", sourceObjectiveStatus = "unverified-source-field" }
quests[66244] = { id = 66244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Valdrakken", description = "Dank Euch konnten wir einer absoluten Katastrophe knapp entgehen.\n\nDennoch sollten wir uns mit den anderen Aspekten treffen und von dem berichten, was sich hier ereignet hat.\n\nBitte trefft mich beim Sitz der Aspekte in Valdrakken. Ich bin sicher, dass die anderen Informationen zu den Plänen von Raszageth und ihren Primalisten haben.\n\nNördlich von hier, ein wenig nach Osten, gibt es einen Übergang nach Thaldraszus. Die Flugstrecke ist malerisch, aber lasst Euch nicht zu lange Zeit.", sourceObjective = "Reist nach Valdrakken und trefft Euch mit Alexstrasza der Lebensbinderin.", completion = "Willkommen in Valdrakken, {name}. Kalecgos meinte, es gäbe Neuigkeiten vom Azurblauen Gebirge.", sourceObjectiveStatus = "unverified-source-field" }
quests[66245] = { id = 66245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedenkt den Gefallenen", description = "So viele meiner Kameraden sind gefallen.\n\nBitte... sammelt ihre Erkennungssignets, auf dass ihre Namen nie vergessen werden.", sourceObjective = "Sammelt 8 Signets der Südfestengarnison.", progress = "Wie läuft Eure Aufgabe, Held? Habt Ihr irgendwelche Signets gefunden?", completion = "Wir werden ihr Andenken ehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[66246] = { id = 66246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlachtennebel", description = "Der Angriff der Primalisten kam plötzlich und ohne Vorwarnung. Meine Einheit hat versucht, unseren Anführer zu finden, Kommandant Eranog. Aber bevor wir auf die andere Seite der Garnison gelangen konnten, wurden wir abgeschnitten.\n\nWährend der Schlacht hat der Anführer meiner Einheit, Unteroffizier Tagrik, drei Primalisten alleine aufgehalten, während Kaora, Mikor und ich an seiner Seite kämpften.\n\nIhre Schreie sind das Letzte, an das ich mich erinnern kann, bevor ich fiel.\n\nIch bitte Euch, {race}, wenn Ihr irgendwelche Anzeichen von meiner Einheit findet, dann lasst mich wissen, was mit ihnen passiert ist.", sourceObjective = "Sucht nach den Mitgliedern von Wächter Velomirs Einheit am Tor der Südfeste.", completion = "Das... schmerzt mich sehr... aber ich verstehe. Vielen Dank, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66247] = { id = 66247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaum benutzte Waffen", description = "Dieser Speer scheint in gutem Zustand zu sein, wenn man bedenkt, in welchem Zustand sich sein ehemaliger Besitzer befindet.\n\nWächter Velomir hat erwähnt, dass Ihr nach nützlichen Materialien Ausschau halten sollt. Vielleicht können noch mehr dieser Speere von den Magmagebundenen erbeutet werden.", sourceObjective = "Sammelt 6 magmagebundene Speere.", progress = "Habt Ihr etwas Nützliches gefunden?", completion = "Ein guter Fund, {name}! Die dürften sich als nützlich erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66248] = { id = 66248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfekte Verbindung", description = "Diese Rolle mit schwerem Seil ist in gutem Zustand.\n\nWächter Velomir hat gesagt, dass Ihr ein Auge nach nützlichen Materialien offen halten sollt. Vielleicht kann er etwas damit anfangen, wenn Ihr noch mehr Rollen findet.", sourceObjective = "Sammelt 5 Rollen mit schwerem Seil.", progress = "Was gibt's, mein Freund? Habt Ihr etwas gefunden?", completion = "Was ist das? Ein Seil? Ich habe keine Zeit, um ein Netz zu knüpfen!\n\nAber wartet... ich hätte da eine Idee. Wir haben ein paar alte Waffen, für die es sich gut eignen würde...\n\nIhr habt ein gutes Auge, {name}! Die sind perfekt!", sourceObjectiveStatus = "unverified-source-field" }
quests[66249] = { id = 66249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreit den Himmel", description = "Ihr habt beim Sammeln der Speere und der Seile gute Arbeit geleistet. Damit können wir sicherstellen, dass diese eingebildeten Primalisten nicht länger die Herrscher der Lüfte sind!\n\nWenn Ihr die Treppe hochgeht, findet Ihr eine Plattform mit mehreren Belagerungsskorpionen. Mit dem Seil könnt Ihr die Wurfarme bespannen und die Speere dienen als Munition. Damit solltet Ihr in der Lage sein, die magmagebundenen Drachen aus der Luft zu holen!\n\nWenn Ihr sie beseitigen könnt, sollte der Weg zur Spitze frei sein, um unsere Suche nach Kommandant Eranog fortzusetzen.", sourceObjective = "Bedient einen Belagerungsskorpion und verwendet ihn, um die Lüfte von den magmagebundenen Wahrgeborenen zu befreien.", completion = "Gut gemacht, {name}! Das sollte uns eine kleine Atempause verschaffen.\n\nAber behaltet lieber die Waffe in der Hand, wir sind noch nicht fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[66250] = { id = 66250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist der Häuptling?", description = "Das ist der einzige Teil der Festung, den wir noch nicht durchsucht haben, {name}. Wenn sich Kommandant Eranog irgendwo befindet, dann muss es hier sein.\n\n<Velomir blickt zum nahe gelegenen Eingang.>\n\nSchauen wir mal, was wir herausfinden können.", sourceObjective = "Begleitet Wächter Velomir und untersucht den Wachturm am Tor der Südfeste.", completion = "Verdammt noch mal! Der Kommandant steckt hinter alledem? Unglaublich, dass er uns so hintergehen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[66251] = { id = 66251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerwehr", description = "Kommandant Eranog hat uns hintergangen und dieser Bestie das Kommando überlassen.\n\nIhr habt bereits so viel für mich getan, doch ich kann es in meinem gegenwärtigen Zustand nicht mit diesem Monster aufnehmen.\n\nIch bitte Euch, tut mir diesen letzten Gefallen und helft sicherzustellen, dass das Tor der Südfeste nicht gegen diese Primalisten fällt.\n\nWir müssen ihren Anführer töten!\n\nHelft mir, {name}!", sourceObjective = "Tötet Magmakralle.", completion = "Jetzt, da ihr Anführer tot ist, sollte es ein Kinderspiel für die Verstärkungen aus Valdrakken sein, die restlichen Primalisten zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66252] = { id = 66252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht erstatten", description = "Die Primalisten hier sind zurückgedrängt, {name}. Unsere Verstärkungen aus Valdrakken sollten bald eintreffen und die restlichen Primalisten beseitigen.\n\nIhr solltet zur Stadt zurückkehren und Hauptmann Drine Bescheid geben. Ich bin mir sicher, dass sie wissen wollen wird, was hier mit Kommandant Eranog vorgefallen ist.\n\nDanke noch mal für alles, {name}.", sourceObjective = "Kehrt nach Valdrakken zurück und berichtet Hauptmann Drine.", completion = "Eranog hat sich den Primalisten angeschlossen? Flamme und Schuppe, das ist schrecklich!\n\nAber Ihr habt verhindert, dass die Primalisten das Tor der Südfeste einnehmen.\n\nDanke für Euren Dienst an Valdrakken, {name}. Das wird nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66253] = { id = 66253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Lieferungen", description = "Es kommen immer mehr Lieferungen von Shiri und Zen'kala, wir kommen kaum noch hinterher! Aber einer von meinen Arbeitern denkt, ich würd' es nich' merk'n, wenn er ein bisschen davon abgreift.\n\nDie Goblins hier hab'n an 'nem kleinen Gerät gearbeitet, das diesem Dieb den Tag versau'n wird: ein explodierender Kuchen.\n\nHaltet Ausschau nach Kanyaku und werft mit einem direkt nach ihm. Der stiftet sicher gerade irgendwo Unfug.", sourceObjective = "Werft explosiven Kuchen nach dem Dieb und beschafft 1 Lieferungen zurück.", completion = "Gute Arbeit, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[66254] = { id = 66254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein pessimistischer Mystiker", description = "Krieg? Drachen? Ich soll Ohn'ahra für Euch kontaktieren?\n\nKann ich nicht! Ich kann Ohn'ahra nicht hören, kein bisschen. Ich bin lediglich ein Initiand. Und es scheint, als hätte mir Ohn'ahra ihren Segen entzogen. Vielleicht bin ich einfach nicht gut genug...\n\n<Boku beginnt, in einer Tasche herumzuwühlen.>\n\nAls meine Mentorin mich diesem Klan zuwies, schenkte sie mir diese Totems. Sie sagte, sie würden mir Kraft geben, wenn ich jemals an mir selbst zweifeln sollte.\n\nHelft Ihr mir, sie zu platzieren? Ich werde noch einmal versuchen, Ohn'ahra anzurufen.", sourceObjective = "Stellt die Totems der Ermächtigung um Boku herum auf.", completion = "Noch immer nichts. Nicht einmal ein Seufzer von Ohn'ahra.", sourceObjectiveStatus = "unverified-source-field" }
quests[66256] = { id = 66256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adlermacher", description = "Wir haben herausgefunden, warum die Nokhud Mystikertotems wollen: Damit lassen sich die Kinder von Ohn'ahra einfangen. Obwohl die Nokhud die Totems gestohlen haben, stecken eigentlich die Primalisten hinter dieser Lästerung.\n\nDie Kinder von Ohn'ahra sind heilige Ohuna, gesegnet von der Windmutter höchstselbst. Bitte, {name}, befreit jegliche Ohuna, denen Ihr begegnet! Und wenn Ihr irgendwelchen Primalisten über den Weg lauft...\n\n<Bokus Blick schweift ab, aber er bleibt von finsterer Entschlossenheit gezeichnet.>", sourceObjective = "Befreit 6 Kinder von Ohn'ahra und eliminiert 6 Primalisten bei der Windspielanhöhe.", completion = "Nach allem, was Ohn'ahra für uns getan hat, müssen wir alles in unserer Macht Stehende tun, um ihren Kindern zu helfen. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66257] = { id = 66257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vogelzauber", description = "Es heißt, dass Ohn'ahra den Speer unseres Vorfahren Maruuk mit ihrer Macht erfüllt hat. Balakar Khan muss den Primalisten von dieser Legende erzählt haben.\n\nSie haben Magie von den Kindern von Ohn'ahra gestohlen. Sie haben sie mit Sturmhexerei beschmutzt und Ballistenbolzen damit erfüllt. Wofür brauchen die Nokhud solche Waffen?\n\nWir sollten nicht darauf warten, es herauszufinden. Nehmt meine Totems und platziert eins auf jedem Wagen, dem Ihr begegnet. Meine Windmagie wird die Bolzen in Stücke zerschlagen.", sourceObjective = "Verwendet Bokus Windtotems, um die Wagen der Nokhud zu zerstören.", progress = "Ihr solltet die Beine in die Hand nehmen, sobald Ihr ein Totem platziert habt.", completion = "Ich bin mir sicher, dass es noch mehr davon gibt, doch wir haben so viele zerstört, wie wir konnten. Hoffentlich hält sie das etwas auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[66258] = { id = 66258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh nein, Ohn'ahra!", description = "Diese Primalistin schafft es gerade so, Ohn'ahra festzuhalten. Sie scheint uns nicht zu bemerken.\n\nTigari Khan würde sagen, dass selbst die leichteste Brise, einen wankenden Stein umwerfen kann. Wenn ich ihren Zauber unterbrechen kann, selbst wenn es nur kurz ist, kann sich Ohn'ahra vielleicht losreißen.\n\nHaltet Ihr die Wachen beschäftigt. Ich habe eine Idee.", sourceObjective = "Besiegt Feinde, während Boku versucht, Ohn'ahra zu befreien.", completion = "Das war ein ganz schöner Sturz. Wir können uns glücklich schätzen, noch am Leben zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[66259] = { id = 66259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sturm an schlechten Neuigkeiten", description = "{name}, wir müssen der Khanam Matra erzählen, was alles passiert ist, inklusive der Gefangenschaft von Ohn'ahra.\n\nIhr müsst so schnell wie möglich nach Maruukai. Ihr werdet jedoch ohne mich gehen müssen. Ich wurde beim Sturz verletzt und würde Euch nur aufhalten.\n\nSorgt Euch nicht um mich. Ich komme später nach. Geht!", sourceObjective = "Übergebt Euren Bericht der Khanam Matra in Maruukai.", progress = "Nun? Sprecht.", completion = "Das sind schlimme Neuigkeiten, {name}, doch wir dürfen unseren Fokus nicht verlieren. Wir sind verletzt, aber noch nicht geschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66261] = { id = 66261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Rückschlag", description = "Ah, Ihr seid genau das schwer gerüstete Individuum, das ich gehofft habe zu treffen.\n\nIch bin wegen sehr wichtiger Geschäfte der Kirin Tor hergekommen, seht Ihr, aber als ich mein Lager aufschlug, verjagte mich eine Horde dreckiger, verfilzter Gnolle.\n\nTatsächlich hat sich in der Nähe eine besorgniserregende Anzahl Gnolle versammelt, genug, um mich glauben zu lassen, dass sie eine Bedrohung für das ganze Gebirge darzustellen.\n\nAber keine Sorge, ich habe einen Plan! Trefft mich auf der anderen Seite des Sees, und ich erkläre Euch alles.", sourceObjective = "Trefft Detry.", completion = "Los, an die Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[66262] = { id = 66262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abwasserklärung", description = "Fangen wir vorne an: Ich brauche meine Operationsbasis zurück! Aber die Amok laufenden Elementaren hier machen es nicht gerade leicht, auch nur Zeh zu fassen.\n\nUnd natürlich ist das die Schuld dieser elenden Gnolle.\n\nDie Gnolle haben so viel Müll, Innereien und weiß das Licht was noch in den See geworfen, dass die ansässigen Elementare angefangen haben, durchzudrehen.\n\nSeid so gut und sammelt ein paar der ekelhafteren Schweinereien auf, bevor die Lage sich weiter zuspitzt. Und viel wichtiger: bevor sie meine Robe besudeln!", sourceObjective = "Säubert 6 verrottende Haufen am See.", completion = "Ich schmecke bereits den Unterschied!", sourceObjectiveStatus = "unverified-source-field" }
quests[66263] = { id = 66263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine präzise Annäherung", description = "Gnolle sind furchtbare Kreaturen. Sie stinken. Sie kratzen sich. Sie lachen einen immer aus. Und es sind schon viele hier, und mehr kommen ständig an. Wir, und dabei meine ich Ihr, könnten sie tagelang niedermähen wie Weizen auf einem Feld und nicht wirklich etwas erreichen. Sie dürfen nicht hierbleiben.\n\nStattdessen müssen wir der Schlange den Kopf abschlagen! Erleichtert sie um ihre Führung, und sie werden vor Ratlosigkeit und Verzweiflung erstarren.\n\nWas soll das heißen, warum tun wir das? Ist es nicht offensichtlich? Es sind Gnolle! Das sollte Grund genug sein.", sourceObjective = "Tötet Gerbfaust.", completion = "Sie sind bestimmt ganz verzweifelt!", sourceObjectiveStatus = "unverified-source-field" }
quests[66264] = { id = 66264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwaffnet und sanftmütig", description = "Um ehrlich zu sein, wedeln sie dort oben mit einer beunruhigenden Menge an Waffen herum. Es sollte die Dinge beruhigen, wenn wir sie um einige davon erleichtern. Oder zumindest beruhigt es meine Nerven.\n\nWas wollen sie ohne Waffen schon groß anstellen? Euch mit bloßen Händen angreifen? Ha!", sourceObjective = "Sammelt 15 Knochennagerwaffen.", progress = "Sicherlich liegen sie nur herum?", completion = "Ach, die? Schmeißt sie einfach irgendwo hin. Die Elementare haben bestimmt nichts dagegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66265] = { id = 66265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer ist der Nächste?", description = "Aha! Nun, wie es scheint, hat ein anderer Gnoll das Kommando übernommen. Wie ich erwartet habe. Ja.\n\nEs ergibt natürlich Sinn, einen vertrauten Vize-Kriegsfürsten zu haben, um die Weiterführung der Regierung zu sichern, nicht wahr? Wir müssen sie einfach nur etwas härter treffen, wenn wir ihre Bürokratie zu Fall bringen wollen, hm?\n\nWas? Ob ich diesen Moment nutze, um darüber nachzudenken, ob ich diese Gnolle vorschnell verurteile? Lächerlich! Das sind Gnolle!\n\nSchnell jetzt! Tötet Knackzahn, bevor das Eisen kalt wird oder sie eine Wahl organisieren!", sourceObjective = "Tötet Knackzahn.", completion = "Ha! Vielleicht überlegen sie es sich beim nächsten Mal zweimal, bevor sie einen neuen Anführer wählen!", sourceObjectiveStatus = "unverified-source-field" }
quests[66266] = { id = 66266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreckige Bastarde", description = "Diese flohgebissenen Hyänenköter der Gnolle müssen verschwinden! Nicht nur, dass sie keine Manieren haben... Ihr glaubt nicht, an welchen Orten sie sich erleichtern... aber möglicherweise können sie mich trotz meiner beispiellosen Illusionen wittern.\n\nTut der wohlgesitteten Welt einen Gefallen und beseitigt sie.", sourceObjective = "Erschlagt 3 Hyänenmatriarchinnen und 12 Hyänenköter.", completion = "Das war in der Tat Totstellen für Fortgeschrittene!", sourceObjectiveStatus = "unverified-source-field" }
quests[66267] = { id = 66267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "M.E.T.A.", description = "Diese Unholde! Plünderung und Mord sind eine Sache, aber Tierquälerei? Das kann ich nicht zulassen.\n\nDie Gnolle haben Fallen aufgestellt, um Tiere zu fangen, mit denen sie ihre sabbernden Hyänenköter ernähren. Findet einen Weg, ihre flauschigen Gefangenen zu befreien, und zeigt diesen Grobianen, wie ein Magier ethisch korrekt mit Tieren umgeht!\n\nNatürlich macht das ethisch Sinn, wenn man meine kürzlichen Handlungen bedenkt. Was genau wollt Ihr da andeuten?", sourceObjective = "Befreit 6 missbrauchte Tiere.", completion = "Das wird ihnen eine Lehre sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[66268] = { id = 66268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller guten Dinge sind drei", description = "Was? Ein anderer hat das Kommando übernommen? Was ist aus dem lähmenden Machtvakuum geworden? Oder wenigstens aus der angemessenen Trauerzeit, um den Schein zu wahren?\n\nHaben sie den gar keinen Anstand? Keinen Sinn von Schicklichkeit? Keinen Respekt für einen fein säuberlich geschmiedeten Plan? Ich habe Tabellen angefertigt!\n\nKümmert Euch um diesen Blutklaue. Ich brauche einen Moment.\n\nUnd ich kann Eure lästigen Kommentare nicht brauchen, vielen Dank!", sourceObjective = "Tötet Blutklaue.", completion = "Endlich! Das war der Letzte, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[66269] = { id = 66269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur, um sicher zu gehen", description = "Tötet... einfach alle, die aussehen, als wären sie magisch begabt. Oder als hätten sie organisatorische Fähigkeiten. Oder die besonders ehrgeizig aussehen.\n\nTut, was auch immer Ihr in diesem Fall für richtig haltet.\n\nWas Ihr \"für richtig haltet\" ist, nicht mehr mit mir zu sprechen? Also wirklich, {class}! Die... haben eindeutig etwas Bösartiges vor!", sourceObjective = "Tötet 12 Elementaristen von Sturmfang.", completion = "Das musste funktionieren, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[66270] = { id = 66270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hau-den-Gnoll", description = "Oh, Licht... mehr sind unterwegs! Wie konnte das geschehen?\n\nAll meine sorgfältige Planung! All die Tage, die ich in diesem widerlichen See verbracht habe! Die Meucheleien!\n\nAll das hätte sie ins Chaos stürzen und ihre Siedlung zusammenbrechen lassen sollen, aber wir haben sie kaum verlangsamt!\n\nVielleicht... vielleicht habt Ihr recht, {name}. Ich lag die ganze Zeit falsch...\n\nNein! Unmöglich! Wir stecken sowieso zu tief drin.\n\nGeht... kümmert Euch um diese Neuankömmlinge. Ich brauche Zeit, um mich zu sammeln.", sourceObjective = "Besiegt die Möchtegernkriegsherren.", completion = "Sie kämpfen einfach weiter, bis sie einen neuen Anführer finden? Dann ist alles klar. Wenn ich hier je eine Operationsbasis haben will, müssen wir sie alle töten.\n\nDer Plan ist, dass wir...\n\nMoment, Ihr geht? Ihr wollt nicht darin verwickelt sein? Was soll ich jetzt tun? Ich kann diesen See nicht verlassen, jetzt, wo ich mir die Gnolle zum Feind gemacht habe!\n\nSchön! Stellt Euch auf die Seite dieser flohverseuchten Mistkerle.\n\nNehmt, was ich Euch versprochen habe und geht. In diesem Wald gibt es noch andere \"Champions\"! Ich finde schon jemanden, der mir hilft!", sourceObjectiveStatus = "unverified-source-field" }
quests[66278] = { id = 66278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Plunder eines Drakoniden", description = "<Eine funkelnde Taschenuhr liegt zwischen den Müllhaufen. Vielleicht weiß Gryrmpech, was es damit auf sich hat.>", sourceObjective = "Bringt die Taschenuhr zu Gryrmpech in den Gärten.\n\nBereitgestellter Gegenstand:", completion = "Die war in der Hütte? Es ist nicht meine, aber ich glaube, ich erinnere mich, wem sie gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[66279] = { id = 66279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reisewecker", description = "Ah ja, diese Taschenuhr gehört einem der Verwalter, der mir bei der Pflege der Gärten hilft.\n\nEr gehört zu Nozdormu. Orizmu, wenn ich mich recht entsinne. Bei all den Kindern kommt man schnell mal durcheinander. An den meisten Tagen steht er neben dem Stundenglas in der Nähe von Alexstraszas Baum, ohne sich zu bewegen. Oder zu blinzeln.\n\nNozdormus Leute waren schon immer merkwürdig, wenn Ihr mich fragt. Aber er wird Euch sicher dankbar sein, wenn Ihr sie ihm zurückbringt.", sourceObjective = "Bringt die Taschenuhr zu Orizmu in den Gärten.", completion = "Danke, {name}. Nozdormu wird froh sein, sie wiederzuhaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[66299] = { id = 66299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geplante Ei-plosion", description = "Unser Prototyp hat funktioniert! Exzellent!\n\nJetzt wird es Zeit für das Hauptgericht. Dieses Mal seid IHR <der Koch/die Köchin>.\n\nNach ein paar notwendigen Korrekturen werdet Ihr erneut in Eure Verkleidung schlüpfen. Nehmt im Anschluss unser Meisterwerk der EI-plosion, schmeißt es in diesen stinkenden Eintopf, begebt Euch zur Höhle der Matriarchin, serviert ihn ihr und gleitet dann zurück nach unten, während hinter Euch alles in die Luft fliegt.\n\nWenn alles nach Plan geht, wird das ihr letztes Abendmahl sein. Wegen der Explosion. Weil sie nicht mehr besonders hungrig sein wird, wenn sie tot ist.", sourceObjective = "Tötet die Matriarchin des Kreischerschwarms.", completion = "Es ist nicht wirklich nach Plan verlaufen, aber das ist bei jedem guten Goblinplan so! Gute Arbeit!\n\nDer Kreischerschwarm treibt sich zwar immer noch hier herum, aber ohne die Führung ihrer Matriarchin wird er leichter auszumerzen sein. Und die Blaufedern haben eine echte Chance, zu überleben.\n\nHarpyien und Drachen trennen keine so großen Unterschiede. Von ihrem versuchten Fressgelage an der Klippe mal abgesehen, haben sie fast so etwas wie eine Zivilisation. Vielleicht gibt es ja einen friedfertigen Schlag da draußen?\n\nOh, behaltet die Verkleidung. Sie steht Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[66308] = { id = 66308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feuer schüren", description = "Die Erschaffung neuer Waffen und Rüstungen in der Schmiede des Erdwächters wird uns den letztendlichen Sieg über die Djaradin sichern.\n\nDie Flammen der Schmiede müssen allerdings kontinuierlich geschürt werden. Aschenscherbenkohle spendet die stärkste Hitze, und die ist nötig, um Waffen zu schmieden.\n\nIhr findet Aschenscherbenkohle in Ablagerungen und Elementaren in der Aschenscherbenspalte.", sourceObjective = "Sammelt 30 Stücke Aschenscherbenkohle.", progress = "Habt Ihr die frische Aschenscherbenkohle gesammelt?", completion = "Diese Kohle ist genau, was wir brauchen, {name}. Damit sollten wir die Schmiede noch eine Weile betreiben können.", sourceObjectiveStatus = "unverified-source-field" }
quests[66320] = { id = 66320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Strom der Zeit", description = "Die Fäden der Zeit fließen wie ein Fluss mit vielen Armen und Biegungen. Manchmal kann sich der Fluss ändern. Doch eine Anomalie, die ungelöst bleibt, kann unser Schicksal zu einer falschen Zeitlinie verdammen.\n\nWir bewegen uns gerade schnell auf eine solche Anomalie zu. Ich habe Chronormu zu den Wandernden Sanden geschickt, um die Sache zu untersuchen, den Fluss zu korrigieren und uns auf die richtige Zeitlinie zurückzuführen.\n\nIch kann vorhersehen, dass Eure Hilfe von unschätzbarem Wert sein wird.\n\nBitte helft uns und trefft Euch mit Chronormu.", sourceObjective = "Reist in die Wandernden Sande und sprecht mit Chromie.", progress = "Hat Nozdormu Hilfe gesandt?", completion = "Hallo... nochmal? Glaube ich?", sourceObjectiveStatus = "unverified-source-field" }
quests[66321] = { id = 66321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhinderte Mühen", description = "Die Streitkräfte der Djaradin planen einen Angriff auf unsere Stellung. Ich kann es tief in meinen Klauen spüren.\n\nWir sollten zuerst zuschlagen, und zwar bevor sie die Chance haben, sich zu sammeln!\n\nBegebt Euch zum Sengenden Stieg und richtet in den Reihen der dortigen Djaradin Verwüstung an.", sourceObjective = "Eliminiert die Streitkräfte der Djaradin.", progress = "Habt Ihr die Streitkräfte der Djaradin geschwächt?", completion = "Sie werden nicht so schnell vergessen, was für eine Zerstörung Ihr angerichtet habt. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[66323] = { id = 66323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie Kuchen essen", description = "Nachdem wir jetzt die Waren wiederhab'n, können wir hier fertig werd'n. Aber meine Arbeiter hängen alle faul in der Stadt 'rum.\n\nFindet die und kriegt sie dazu, wieder herzukommen. Eine Ladung übrig'n Kuchen ins Gesicht sollte ihnen Beine mach'n.", sourceObjective = "Weckt 3 Arbeiter in Orgrimmar.", completion = "Danke. Alle sind wieder da und fleißig. <Sein Blick fällt auf einen übrigen Kuchen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66324] = { id = 66324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niemals vergessen", description = "Das Gegengift ist fertig. Benutzt es, um im Unterstützungshort nach Überlebenden zu suchen. Beeilt Euch... Der Effekt wird nicht lange anhalten, also müsst Ihr es eventuell wiederholt anwenden.\n\nFalls einige meiner Leute noch atmen, dann rettet sie.\n\nUnd falls dem nicht mehr so ist, dann sammelt ihre Hornsignets, damit ihren Namen Ehre erwiesen werden kann.\n\nWährend Ihr dort drin seid, könnt Ihr vielleicht Beweise finden, wie es zu dieser Ansteckung kommen konnte.", sourceObjective = "Bergt Gegenstände und Überlebende aus dem Unterstützungshort.", progress = "Niemand soll sterben oder leiden, sofern es in meiner Macht steht, das zu verhindern.", completion = "Danke, dass Ihr so viele wie möglich gerettet habt.\n\nRethenash. Katrinasa. Tenezeth.\n\nIch schwöre, dass die Namen der Gefallenen in Erinnerung bleiben werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[66326] = { id = 66326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkszeuge", description = "Eine derart mächtige Schmiede benötigt besondere Werkzeuge, die ihrer überwältigenden Hitze standhalten können.\n\nAber die Djaradin haben diesen Ort geplündert und viele der Werkzeuge gestohlen, die wir für diese Arbeit benötigen.\n\nErgattert die Werkzeuge von ihnen zurück, wenn Ihr könnt, damit wir unsere Verbündeten wieder bewaffnen können.", sourceObjective = "Sammelt 1 |4Präzisionsschuppenhammer:Präzisionsschuppenhämmer;, 1 |4Obsidianamboss:Obsidianambosse;, 5 |4Schwarzstahlzange:Schwarzstahlzangen; und 10 Drachenklauenstempel.", progress = "Habt Ihr die nötigen Werkzeuge gefunden?", completion = "Das ist ein guter Anfang. Für Erste können wir mit den Werkzeugen arbeiten, die Ihr zurückerlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66327] = { id = 66327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windjäger", description = "Wir sollten einen Moment innehalten und unsere Strategie überdenken.\n\nWir brauchen Ohn'ahras Segen, um das Horn von Drusahl zu blasen und die grünen Drachen zu beschwören. Ohne ihre Hilfe können wir diesen Krieg nicht gewinnen. Die Nokhud sind den anderen Klans bereits zahlenmäßig überlegen und nun haben sie Verstärkung von den Primalisten. Außerdem hat Koroleth jetzt auch noch unsere Windmutter gefangen genommen! Wir müssen daher Ohn'ahra finden, bevor die Nokhud ihren finalen Angriff starten und Maruukai einkreisen.\n\nIch werde unverzüglich all unsere Späher entsenden. Ich hoffe nur, dass wir es schaffen, sie rechtzeitig zu finden.", sourceObjective = "Hört Euch den Bericht von Späherin Tomul an.", completion = "Wir sind zu spät. Die Nokhud haben das Horn von Drusahl überrannt und meine Leute abgeschlachtet. \n\nDieser Akt der Aggression wird nicht unerwidert bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[66328] = { id = 66328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grüner Drache am Boden", description = "Die Drachen sind über den Ebenen im Westen zu Boden gegangen. Wir müssen schnell zu ihnen gelangen, bevor die Nokhud uns zuvorkommen.\n\nWir wollen nicht, dass sie nur wegen Balakars Taten gleich alle Maruuk als Feinde betrachten.", sourceObjective = "Trefft die Khanam Matra beim Wasserloch.", progress = "Die Drachen brauchen unsere Hilfe, Fremdling. Wir sollten uns beeilen!", completion = "Unsere Vorfahren haben gesagt, dass die grünen Drachen gemäßigt und weise waren. Wir haben Glück, dass sie ihren Zorn lang genug zurückgehalten haben, um unsere Seite der Geschichte zu hören.\n\nJetzt, da wir wissen, dass die Primalisten und Nokhud unsere gemeinsamen Feinde sind, ist es an der Zeit, sie zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66329] = { id = 66329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn blasen", description = "Warum würden sie Ohn'ahra herbringen? Es sei denn...\n\n{name}! Ich glaube nicht, dass Balakar vorhat, das Horn zu zerstören. Ich glaube, das ist eine Falle! Wir müssen einen Weg an diesem Wind vorbei finden, schnell!", sourceObjective = "Seid <Zeuge/Zeugin> von Balakars und Koroleths Plänen.", completion = "Ich werde nicht ruhen, bevor Balakar für seine heutigen Schandtaten gebüßt hat. Das Massaker an meinem Volk, die Blasphemie gegen Ohn'ahra, der Verrat an unseren uralten Verbündeten...\n\nDie Rache wird noch warten müssen. Es gibt gerade Wichtigeres zu tun. Wir müssen den grünen Drachen helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[66331] = { id = 66331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Primalistenfront", description = "Die Khanam Matra berichtet, dass sie und ihre Streitkräfte bei den Smaragdgärten angekommen sind. Sie haben Koroleth und ihre Primalisten gefunden. Allem Anschein nach sammelt sich eine gewaltige feindliche Invasion am Strand im Norden.\n\nWeise wie sie ist, hat sie mehrere Späher abgestellt, die verschiedene strategische Orte auf dem Schlachtfeld im Blick behalten. Geht und sammelt ihre Berichte. Trefft mich und meine Streitkräfte anschließend an der Front. Ruhm erwartet uns im Kampf. Und sollten wir erfolgreich sein, Vergeltung auch.", sourceObjective = "Sprecht mit Späherin Tomul, Ari und Belika, Ohn Seshteng und Merithra in der Sturmschneise.", progress = "Mit jedem Moment, den wir vertrödeln, rücken unsere Feinde weiter vor. Wir müssen uns beeilen, {name}.", completion = "Unsere Feinde sind uns einen Schritt voraus. Doch das ist kein Grund zur Verzweiflung. Unsere Entschlossenheit ist so stark wie unser Bündnis. Macht Euch bereit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66333] = { id = 66333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit für Solethus", description = "Solange auch nur ein grüner Drache noch atmet, werden diese Primalisten den Uralten Zweig nicht ohne Gegenwehr entweihen.\n\nWir wollen bei dieser Schlacht unseren Beitrag leisten, doch solange diese Drachentöterballisten auf dem Schlachtfeld stehen, kommen wir nicht vorwärts. Sie werden von den stärksten Kriegern der Nokhud bewacht, Ihr werdet Euch also auch noch um diese Krieger kümmern müssen.\n\nZerstört die Ballisten und die Kriegstreiberinnen der Nokhud. Eliminiert diese Bedrohung, und die grünen Drachen werden in dieser Schlacht das Blatt wenden.", sourceObjective = "Tötet 3 Kriegstreiberinnen der Nokhud und zerstört 3 Drachentöterballisten.", progress = "Beeilt Euch, Sterblicher. Solange diese Ballisten einsatzbereit sind, werde ich keine Drachen in den Kampf schicken.", completion = "Diese schrecklichen Waffen wären wir los. Auf dass nie mehr ein Drache so leiden möge wie Solethus.", sourceObjectiveStatus = "unverified-source-field" }
quests[66335] = { id = 66335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekonstruktion weiterer Pylonen", description = "Da diese teuflischen Waffen nun zerstört sind, kann der grüne Drachenschwarm mit voller Stärke in die Schlacht eingreifen.\n\nWir sind mit der Lage am Boden besser vertraut. Wir müssen die Ziele für den Angriff von Merithra und ihren Drachen ausleuchten, damit sie aus der Luft angreifen können.\n\nMerithra hat mir diese verzauberte Saat gegeben. Platziert sie in der Nähe von Primalistenpylonen. Wir werden ihr Licht dazu verwenden, um Angriffe fliegender Drachen anzufordern.", sourceObjective = "Markiert die Primalistenpylonen mit der verzauberten Saat.", progress = "Ich wäre Euch dankbar, wenn Ihr mit dieser verzauberten Saat etwas weiter von mir weg stehen könntet. Danke.", completion = "Ich werde auf ewig dankbar sein, dass die Drachen uns in dieser Schlacht zur Seite standen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66336] = { id = 66336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Insel des Smaragds", description = "Euer Beitrag zu all dem ist mir nicht entgangen, <Sterblicher/Sterbliche>. Es ist zu einem großen Teil Eurer Tapferkeit zu verdanken, dass wir die Primalisten besiegen konnten.\n\nIch habe die Zentauren eingeladen, sich mir unter dem Uralten Zweig anzuschließen. Ihr, zusammen mit der Khanam Matra und ihrem Volk, seid in unserem Zuhause willkommen.\n\nFolgt diesem Pfad durch den Bogen über das Wasser und zu den dahinterliegenden Bäumen. Dort werde ich auf Euch warten.", sourceObjective = "Trefft Merithra im Uralten Zweig.", completion = "Willkommen beim Uralten Zweig. Ihr steht vor dem Smaragdschwurstein des grünen Drachenschwarms.", sourceObjectiveStatus = "unverified-source-field" }
quests[66337] = { id = 66337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmbrecher", description = "{name}, zu mir! Der Sieg ist zum Greifen nahe!\n\nDie Reihen der Primalisten sind durchbrochen und ihr Krieg steht vor dem Ende. Alles, was wir bislang erreicht haben, ist nur von Bedeutung, wenn wir diese entscheidende Schlacht gegen die Primalistenanführerin Koroleth gewinnen.\n\nLasst es uns gemeinsam zu Ende bringen, Ihr und ich! Zusammen! In den Kampf, <Bruder/Schwester>!", sourceObjective = "Bezwingt Koroleth.", completion = "Wir haben es endlich geschafft. Unsere Insel ist wieder sicher. Danke für alles, was Ihr für mein Volk getan habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66339] = { id = 66339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Nokhud: Der Wind gehört dem Himmel", description = "Ist Eure Zeit bei uns zu Ende, {name}, oder werdet Ihr uns einmal mehr helfen?\n\nMeine Späher haben berichtet, dass Balakar sich in seine Festung zurückgezogen hat, wo er Ohn'ahra festhält. Das ist inakzeptabel!\n\nUnd in der Zwischenzeit stürmen die Plünderer der Nokhud über die Ebenen und richten Chaos an. Während wir gegen sie kämpfen, könnt Ihr die Festung der Nokhud infiltrieren und Ohn'ahra retten. Würdet Ihr das für uns tun?", sourceObjective = "Besiegt Balakar Khan und rettet Ohn'ahra beim Angriff der Nokhud.\n\nIhr könnt den Angriff der Nokhud allein betreten, wenn Ihr Euch über die Anhängerdungeons anmeldet.", completion = "Mit diesem Sieg habt Ihr den Maruuk mehr geholfen, als Ihr Euch vorstellen könnt. Ich möchte Euch unseren aufrichtigsten Dank aussprechen, {name}. Geht mit den Segen von Ohn'ahra.", sourceObjectiveStatus = "unverified-source-field" }
quests[66340] = { id = 66340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausflug ins Azurblaue", description = "Wir haben unseren Teil getan. Ich muss jedoch hierbleiben, um über den Schwurstein zu wachen und den grünen Drachenschwarm zu führen. Doch wisset, dass Ihr Euch unsere Dankbarkeit und unser Vertrauen verdient habt.\n\nIch habe erfahren, dass die Kirin Tor um Hilfe bitten, den Azurschwurstein zu beanspruchen. Damit bringt Ihr uns der Heilung Azeroths einen Schritt näher.\n\nFindet Pakina und Masud den Weisen von den Kirin Tor. Sie haben weitere Informationen. Gute Reise und angenehme Träume, {name}.", sourceObjective = "Triff Pakina und Masud den Weisen an der Flussgabelkreuzung.", completion = "Seid gegrüßt, Abenteurer! Ich bin froh, dass Euch unser Hilferuf erreicht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[66344] = { id = 66344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit dem Wind im Rücken", description = "Die Primalisten haben also Klan Nokhud für ihre Sache gewonnen.\n\nBisher konnten wir die Primalisten zurückhalten, doch die Nokhud haben eine neue Waffe ins Spiel gebracht: eine Drachentöterballiste. Ich fürchte, dass Solethus nicht der letzte Drache sein wird, der ihrer verdorbenen Sturmmagie zum Opfer fällt.\n\nKommt. Ich bringe Euch zum Drachenrefugium der Schattenzuflucht. Und Ihr könnt mir erzählen, was Ihr von den Nokhud wisst, während die Khanam Matra ihre Streitkräfte sammelt. Wir müssen uns auf den nächsten Schritt vorbereiten.", sourceObjective = "Fliegt mit Gerithus und Merithra.", completion = "Wir sind da, Sterblicher. Willkommen in den Smaragdgärten.", sourceObjectiveStatus = "unverified-source-field" }
quests[66349] = { id = 66349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übungsfelsen", description = "Entfernt diese Steine!", sourceObjective = "Entfernt 3 Steine.", sourceObjectiveStatus = "unverified-source-field" }
quests[66351] = { id = 66351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rauch über dem Berg", description = "<Pfadfinder Jeb betrachtet die Bergkette hinter dem Lager und schnaubt.>\n\nDas gefällt mir nicht. Pfadfinderin Yips hätte schon vor Tagen hier sein sollen. Sie sollte mir helfen, diesem Haufen von Jungforschern beizubringen, wie man sicher diese Säulen hinaufklettert.\n\nJetzt sehe ich Rauch in der Ferne.\n\nDas gefällt mir ganz und gar nicht.", sourceObjective = "Findet Pfadfinderin Yips' Fluggerät.", completion = "Ihr kommt gerade rechtzeitig! Pfadfinderin Yips verliert bald den Halt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66352] = { id = 66352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was der Feind weiß", description = "Es ist wichtig herauszufinden, was das Ziel der Mission der Splitterflammen in diesen Ruinen ist... und was das alles mit der arkanen Woge zu tun hat.\n\nWir werden das auf die gute alte Art machen: Aufklärung und Spionage.\n\nDie Ruinen sind von Anhängern der Splitterflammen überlaufen. Ich bin mir sicher, dass einige von ihnen Befehle bei sich tragen, die uns Einblicke in ihre mysteriösen Vorhaben erlauben.\n\nNutzt alle Mittel, die Euch zur Verfügung stehen, um an diese Dokumente zu gelangen.", sourceObjective = "Findet Dokumente der Splitterflammen und bringt sie zu Lathos.", progress = "Habt Ihr schon etwas herausgefunden, {name}?", completion = "Ich danke Euch, {name}. Eure Fertigkeit und Effizienz imponieren mir.\n\nVielleicht bin ich nicht der Einzige, der einen \"guten Einfluss\" auf Rannan haben wird.\n\nUnd nun... lasst uns herausfinden, was die Splitterflammen hier verloren haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[66353] = { id = 66353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I.R.R.E. Anomalien", description = "Hier gibt es JEDE MENGE arkaner Energie...\n\nDoch die I.R.R.E. kann dabei helfen! Das ist ein wahrhaft innovatives Gerät... das steckt auch so im Namen: \"Innovative, Revolutionäre Rannan-Erfindung\"! Sie kann arkane Energie aufspüren UND bannen.\n\nHier... haltet mal! Spürt Ihr schon die MACHT in Euren Händen? Nein?\n\nNun, wenn Ihr sie schon mal in der Hand habt, könnt Ihr damit ja auch diese Anomalien bannen!", sourceObjective = "Benutzt die I.R.R.E., um drei arkane Anomalien zu bannen.", progress = "Na los! Die arkane Energie wird sich nicht von alleine bannen.", completion = "Hmm... Ihr habt die Anomalien gebannt, aber die I.R.R.E. erkennt immer noch eine arkane Woge... die mit jeder Minute größer wird.\n\nDas... kann nichts Gutes verheißen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66354] = { id = 66354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Funke", description = "Die Schmiede ist bereit. Jetzt muss sie nur angefeuert werden.\n\nPlatziert die beschädigten Schwursteinfragmente in der Schmiede, und Furorion wird den Funken spenden, der den Prozess entzündet.", sourceObjective = "Rekonstruiert die beschädigten Teile des Schwursteins.", progress = "Wurden die Fragmente rekonstruiert?", completion = "Die beschädigten Teile des Schwursteins sind repariert! Das ist erst der Anfang dessen, was hier noch möglich ist.\n\nMit der neu entfachten Schmiede kann ich anfangen, neue Waffen und Rüstungen herzustellen, um unsere Anstrengungen zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66356] = { id = 66356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenbaum" }
quests[66363] = { id = 66363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basiliskenbuckelschild", description = "Verkettete Schuppen sind der Schlüssel, um einen Pfeil abzuwehren. Unsere Buckelschilde sind die Besten der ganzen Ebenen. Aber mir fehlen Basiliskenbälge für die nächste Bestellung.\n\nIch kann Euch ansehen, dass Ihr Euch für unser Handwerk interessiert. Sammelt Basiliskenbälge auf den Dracheninseln, dann weise ich Euch in unsere Techniken ein.", sourceObjective = "Sammelt 20 starre Basiliskenbälge von den Basilisken der Dracheninseln für Dhurrel von den Zentauren der Maruuk.", progress = "Habt Ihr die Bälge?", completion = "Die sind von hervorragender Qualität! Ich danke Euch.\n\nFür Eure Hilfe könnt Ihr gern etwas vom überschüssigen Leder aus unserem Lager haben. Außerdem kann ich Euch etwas Berufserfahrung schenken, wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66364] = { id = 66364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachen steigen lassen", description = "Lasst mich Euch etwas über eine einzigartige Gelegenheit erzählen.\n\nDie Protodrachen haben einen erstaunlichen Bewegungsreichtum in ihren Schwingen. Und die Verrippung! Sie ist äußerst dehnbar. Wir bauen unsere Drachen meistens aus gespannten Häuten, aber jetzt verbreiten die Protodrachen Chaos. Wenn Ihr mir einige ihrer Schwingen bringt, könnte ich Flugdrachen bauen, die der Stolz des Stammes wären.", sourceObjective = "Sammelt 10 frische Protodrachenschwingen von den Protodrachen der Dracheninseln für Temnaayu von den Tuskarr von Iskaara.", progress = "Habt Ihr die Schwingen?", completion = "Die sind perfekt, damit werde ich im Nu einen funktionierenden Drachen zusammenbasteln!\n\nOh, und lasst mich Euch ein wenig Eures Handwerks zeigen. Das ist das Mindeste, was ich tun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[66368] = { id = 66368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insel im Sturm", description = "Ich hatte nicht viel Zeit zu rasten. Der elementare Angriff ist unerbittlich!\n\nIch würde einen Moment der Ruhe willkommen heißen. Das würde mir erlauben, mehr Zauberschutze für unsere Verteidigung herzustellen.\n\nSeht, was Ihr tun könnt, um die Zahlen der Angreifer zu mindern.", sourceObjective = "Eliminiert 10 lodernde Manifestationen und Schmelzer Igneus.", progress = "Sie müssen getötet werden.", completion = "Es war ein willkommener Moment der Ruhe. Im Gegenzug habe ich ein Geschenk für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[66369] = { id = 66369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der irdene Schutz", description = "Mit den Ringen, die Ihr gesammelt habt, habe ich einen Schutz ermächtigt. Dieser hat die Felsen der Erde selbst um sich herum gesammelt und einen lebendigen Irdenen erschaffen, um dieses Gebiet zu beschützen.\n\nTestet den irdenen Schutz, um zu sehen, ob er funktioniert.", sourceObjective = "Aktiviert den irdenen Schutz.", completion = "Ich danke Euch für Eure Hilfe, {name}. Ich werde noch weitere solcher Schutze in der Gegend errichten, um die Djaradin und die Elementare zu bekämpfen. Nutzt diese Amulette, um sie zu aktivieren, wann immer Ihr Unterstützung benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66383] = { id = 66383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legendäre Unterstützung", description = "{name}, wir haben die Erleuchteten Mittler davon überzeugen können, ein paar zusätzliche Hilfsmittel für den Kampf gegen den Kerkermeister bereitzustellen!", sourceObjective = "Besucht Vilo, den Erleuchteten Rüstmeister, um zu sehen, was verfügbar ist.", completion = "Willkommen! Bitte, seht Euch meine Waren an. Einige davon werden Euch beim Herstellen von legendären Gegenständen helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[66390] = { id = 66390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschwundene Waren", description = "Hmpf, diese nichtsnutzigen Küstenzopfs ziehen wieder in ein Abenteuer, und ich sitze hier fest und soll ihre Waren sortieren!\n\nAch, vielleicht bin ich ja ein wenig verbittert, aber ich wünschte schon, Tawny könnte sich etwas kürzer fassen. Ich brauche ja keinen Roman, nur ein paar Anweisungen. Obendrein ist noch ein Teil der Waren verschwunden, zusammen mit einem meiner Arbeiter!\n\nWürde es Euch etwas ausmachen, die für mich wieder zu besorgen? Ihr könntet ihn bestimmt beschwatzen, wenn Ihr ihm ein Getränk versprecht. Ansonsten bewerft Ihr ihn einfach hiermit.", sourceObjective = "Holt die gestohlenen Waren vom Dieb im Hafen von Sturmwind zurück.", completion = "Ach! Da ist Meerwasser auf die Ware geraten! Nun gut, solange alles noch intakt ist, wird es den Küstenzopfs wohl nicht viel ausmachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66391] = { id = 66391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Ruinen!", description = "Hättet Ihr Interesse daran, etwas über meine Erfindung, die I.R.R.E. zu erfahren? Nein?\n\nNun, ich erzähle es Euch trotzdem... weil sie was gefunden hat.\n\nHeute hat sie eine GEWALTIGE WOGE arkaner Energie entdeckt, die von den Ruinen von Karnthar ausgeht. Lathos glaubt, dass die Splitterflammen etwas damit zu tun haben. Das ist die PERFEKTE Gelegenheit, die I.R.R.E. vorzuführen!\n\nWollt Ihr mitkommen? Das wird der Hammer.", sourceObjective = "Trefft Rannan und Lathos in den Ruinen von Karnthar.", completion = "Ihr habt es verpasst! Wir sind DIREKT in eine Patrouille der Splitterflammen gelaufen.\n\nLathos hat sich durch sie GESCHNETZELT, doch es waren zu viele!\n\nAlso bin ich umhergesprungen und habe eine arkane Explosion nach der anderen abgefeuert... RUMMS UND KABUMM!\n\nOh, aber äh, ja... die Energiewoge...", sourceObjectiveStatus = "unverified-source-field" }
quests[66392] = { id = 66392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ansporn für die Verbündeten der Natur", description = "Wir dürfen jetzt nicht der Verzweiflung erliegen. Wir müssen weiter vorstoßen und einen anderen Weg durch die Barriere finden.\n\nZunächst brauchen wir Verbündete. Rymek hat unzählige Elementare beschworen, die durch das Portal strömen. Wir brauchen also eine Armee, die so wie wir in den Traum gelangen oder zumindest leicht hineingebracht werden kann.\n\nTrommelt die Druiden und Zentauren in der Schattenzuflucht zusammen. Sie haben geschworen, diese Haine zu bewahren, und jetzt ist es an der Zeit, sie bei ihrem Wort zu nehmen.", sourceObjective = "Trommelt die Druiden zusammen und sammelt die ermächtigten Anker in der Schattenzuflucht.", progress = "Seid Ihr bereit für die Reise zum Ardenwald?", completion = "Ich werde mit Euch in den Ardenwald reisen. Ich sage Ysera, dass wir sie zurück brauchen... und wir einen Weg kennen, das zu bewerkstelligen.\n\nIch sollte es sein, der dieses Opfer erbringt. Ich habe ein langes Leben gelebt. Ich wollte meinen Sohn nie überdauern. Auf diese Weise kann ich für Rymeks Verrat Buße tun und im selben Zug unseren Aspekt zurückbringen.\n\nSeid Ihr dabei?", sourceObjectiveStatus = "unverified-source-field" }
quests[66393] = { id = 66393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Somnikus", description = "Somnikus ist melancholisch und aufgewühlt seit dem Tod seines Sohnes.\n\nNatürlich haben wir alle Verluste erlitten, doch ich wage nicht, daran zu denken, wie ich mich fühlen würde, wenn Gerithus etwas Ähnliches zustieße.\n\nBegebt Euch mit Rymek zur Insel und seht, ob es etwas gibt, das wir tun können. Somnikus vermutet, dass die Primalisten kurz vor einem weiteren Angriff stehen. Ich befürchte, er könnte etwas Unüberlegtes tun.\n\nKeine Sorge, dank Eurer Hilfe mit dem Smaragdschwurstein, könnt Ihr die Barriere mit Leichtigkeit durchqueren.", sourceObjective = "Trefft Somnikus mit Rymek in der Nähe des Schwursteins im Uralten Zweig.", completion = "Willkommen im Uralten Zweig, mein Kind.\n\nHat Merithra Euch geschickt, um nach mir zu sehen? Ich bin viel zu alt, als dass sie sich noch Sorgen um mich machen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[66394] = { id = 66394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schleier schwächen", description = "Es muss einen Weg geben, die Barriere vom Inneren des Hains aus zu deaktivieren. Ich spüre mehrere Punkte um uns herum, die sie stärken.\n\nWenn Ihr genug davon ausschaltet, sollten wir in der Lage sein, die Barriere komplett zu deaktivieren, damit die anderen sich uns anschließen können.", sourceObjective = "Deaktiviert Barrierenverankerungen im Uralten Zweig.", progress = "Habt Ihr die Barrierenverankerungen gefunden?", completion = "Das sollte es gewesen sein. Die Barriere wird jetzt deaktiviert.\n\nSchon bald können sich die anderen uns im Smaragdgrünen Traum anschließen, auf dass wir wieder zusammen kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66395] = { id = 66395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die flüsternden Felsen", description = "Merithra braucht sich nicht um mich zu sorgen. Es geht mir gut. Der Tod meines Sohnes... Es geht mir gut.\n\nWenn Ihr mir wirklich etwas Ruhe schenken wollt, dann gibt es da etwas, das Ihr für mich tun könnt. Ich habe den Verdacht, dass die Primalisten noch einmal versuchen werden, in diese Lande einzudringen. Doch anders als letztes Mal werden sie den Uralten Zweig dieses Mal vermutlich nicht direkt angreifen. Sie wissen, dass wir sie zerschlagen würden.\n\nSeht Ihr die Felsen da drüben? Diese etwas stinkigen Felsen in dieser komischen Farbe? Ich kann hören, wie sich etwas unter ihnen bewegt. Vielleicht lauern hier ja Primalisten. Könntet Ihr mal nachschauen und zerquetschen, was auch immer Ihr dort findet?", sourceObjective = "Untersucht verdächtigen Permafrost und tötet Gletschertunnelgräber.", completion = "Ich wusste doch, dass da was sein musste! Und auch noch so nah am Portal! Jetzt kann ich über... andere Dinge nachdenken.\n\nWährend Ihr auf der Jagd wart, hatten Rymek und ich eine wunderbare Unterhaltung. Er ist sehr verständnisvoll und einfühlsam. In gewisser Weise erinnert er mich an Solethus...\n\nEr hat darum gebeten, das Portal in den Smaragdgrünen Traum mit eigenen Augen sehen zu dürfen, und ich wüsste nicht, was dagegen spricht. Besonders, nachdem Ihr jetzt diese lästigen Spinnen von unserer Türschwelle vertrieben habt. Er wird sicher beeindruckt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[66396] = { id = 66396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewachte Anerkennung", description = "Ich weiß, wie erschöpfend es sein kann, solch einen wichtigen Ort zu verteidigen. Und wir Drakoniden und Drachenbruten erhalten nur wenig Dank für unsere Hingabe.\n\nDaher möchte ich den Wächtern hier im Uralten Zweig meinen ganz persönlichen Dank ausdrücken.\n\nHier, bringt ihnen diese Geschenke von mir als Zeichen der Freundschaft. Ich hoffe, dass meine herzliche Geste meinen Dank zum Ausdruck bringt.", sourceObjective = "Übergebt 6 Wachen Rymeks Geschenk.", progress = "Habt Ihr den Wächtern meine Geschenke gebracht?", completion = "Sehr gut. Ich hoffe, dass ihnen diese Edelsteine gefallen. Ich habe sie für diesen besonderen Anlass selbst gefertigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66397] = { id = 66397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit voller Kraft", description = "Wir brauchen Verstärkung, und zwar schnell. Aber Merithra kann sich uns aufgrund der Barriere hier im Hain noch nicht anschließen. Wir werden beides von hier im Inneren des Traums erledigen müssen.\n\nTötet die Primalisten und nehmt Euch von ihnen, was Ihr braucht, damit wir diese Eisgefängnisse schmelzen und die Hainwächter befreien können.", sourceObjective = "Befreit die Smaragdschuppenwächter und Smaragdwärter.", completion = "Danke, dass Ihr mich befreit habt! Ich kann es kaum glauben, dass Ysera tatsächlich hier ist, zurück im Smaragdgrünen Traum! Genau wie in meiner Theorie.\n\nIch würde ihr ja gerne tausende von Fragen stellen, aber ich muss mich konzentrieren. Da wäre immer noch das Problem mit Rymek.\n\nAls er mich in Eis gefangen hat, konnte ich sehen, wohin er gegangen ist.\n\nEr sucht etwas im Traum, etwas Mächtiges. Ich weiß nicht, was, aber wir müssen ihn erreichen, bevor er findet, was auch immer es ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[66398] = { id = 66398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der smaragdgrüne Drachenschwarm", description = "Wenn wir die Primalisten aus dem Smaragdgrünen Traum verbannen wollen, müssen wir vor allem einen Ort sichern: Lunedane. Laut meinem Sohn ist Rymek dort.\n\nEs ist die letzte Verteidigungslinie des werdenden Baumes. Ein uraltes Artefakt sorgt dort dafür, dass der Baum nicht gefunden wird. Es ist außerdem mächtig genug, um all unsere Feinde ein für alle Mal zu vertreiben.\n\nIch weiß nicht, ob meine Mutter noch die Macht besitzt, um es zu beherrschen und einzusetzen. Aber darum können wir uns noch kümmern, wenn wir Rymek gefunden und aufgehalten haben.\n\nFliegt mit uns, als Einheit.", sourceObjective = "Sprecht mit Gerithus und fliegt mit Merithra und Ysera nach Lunedane.", completion = "Wir haben es geschafft! Aber Rymek hat bereits mit seinem Angriff begonnen. Wir dürfen nicht zulassen, dass er durchkommt!", sourceObjectiveStatus = "unverified-source-field" }
quests[66399] = { id = 66399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über die Brücke", description = "Wir müssen etwas gegen diesen Schnee unternehmen! Wenn wir Euch gegen Rymek und seine Diener eine Hilfe sein sollen, können wir uns nicht die Flügel abfrieren.\n\nIch spüre mächtige Frostkerne in der Nähe, die vermutlich diesen Schneesturm aufrechterhalten. Wenn Ihr sie zerstören könnt, können wir Rymeks Diener sofort ausschalten.\n\nUnd Somnikus ist auch da draußen. Er flog wie ein besessener Drache hinter Rymek her. Wir müssen so schnell wie möglich zu ihm.", sourceObjective = "Zerstört die Frostkerne und gelangt zu Somnikus.", progress = "Alles tut weh.", completion = "<Somnikus atmet schwer und schmerzerfüllt. Er zittert vor Kälte.>\n\nIch habe ihn so lange aufgehalten, wie ich konnte...", sourceObjectiveStatus = "unverified-source-field" }
quests[66400] = { id = 66400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wintersturz", description = "<Somnikus ringt um Luft, während er langsam erfriert.>\n\nIch konnte... verhindern, dass er den Baum erreicht. Ich hoffe, das hat ausgereicht.\n\nRymek muss fallen, sofort. Doch das ist nun Eure Aufgabe.\n\nSagt Ysera und Merithra... sagt ihnen, es tut mir leid, dass ich ein alter, närrischer Drache war.", sourceObjective = "Bezwingt Rymek.", completion = "Rymek ist besiegt, doch im Traum streifen immer noch zu viele Elementare und Primalisten umher.\n\nIch schätze... wir werden jetzt herausfinden, wer die Träumerin wirklich ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[66401] = { id = 66401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Träumerin", description = "Wir haben so hart gekämpft, um an diesen Punkt zu gelangen, und es bleibt nur noch eines zu tun. Die Macht in Lunedane wird nur jenem Wesen antworten, das den Smaragdgrünen Traum von innen heraus beherrschen kann.\n\nIch dachte, dass das nur meine Mutter sein könnte, aber... ich kann sehen, wie sie sich verändert hat.\n\nIch weiß nicht, ob es eine Veränderung zum Guten ist, aber sie ist real und das muss ich akzeptieren.\n\nKommt, gehen wir diesen Moment gemeinsam an.", sourceObjective = "Entfesselt die Macht des Traumlocus.", completion = "Ich bin die Träumerin.", sourceObjectiveStatus = "unverified-source-field" }
quests[66402] = { id = 66402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie die Mutter so die Tochter", description = "Von dem Moment, an dem ich wieder Fuß in den Traum gesetzt habe, wusste ich, dass etwas anders war. Doch nun, da wir Rymek und seine Primalisten bezwungen haben, muss ich mir über die Konsequenzen all der Dinge Gedanken machen, die passiert sind.\n\nMeine Tochter hat den grünen Drachenschwarm nach meinem Tod zusammengehalten. Da ist es nur angebracht, dass sie nun diejenige ist, die aufsteigt.\n\nMerithra muss den smaragdgrünen Drachenschwarm anführen.", sourceObjective = "Seht Euch den Aufstieg von Merithra an.", completion = "Wo meine Mutter einst flog, muss ich nun fliegen, jetzt und in Zukunft. Wo ihr Atem einst Frieden und Leben brachte, muss dies nun der Meine tun.\n\nIch schwöre, als Anführerin des grünen Drachenschwarms mein Bestes zu geben. Ich verspreche, dass ich alles tun werde, was nötig ist, genau so, wie Ysera es so viele Jahrtausende lang getan hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[66409] = { id = 66409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drückende Anliegen", description = "Der Häuptling empfängt keinen Besuch.\n\nEgal, ob Iskaara Euch geschickt hat oder nicht, wir hatten in letzter Zeit mehr als genug Ärger. Und wir brauchen auch keine Außenseiter, die noch mehr davon im Schlepptau haben.\n\nWenn Ihr unsere Zeit wollt, dann macht Euch nützlich und helft unseren Wachen. Die Djaradin greifen uns von der anderen Seite des Flusses an. Hinter dem Angriff steckt Flammenformer Lorak. Im Vergleich zu anderen Djaradin sieht er eher unscheinbar aus, doch er hat deutlich mehr Köpfchen als der Rest von ihnen.\n\nKümmert Euch um ihn und bringt mir Beweise dafür. Danach reden wir weiter.", sourceObjective = "Sammelt eine Trophäe von Flammenformer Lorak bei der Schuppenknackerfeste.", progress = "Wenn diese Waffe nur zur Schau ist, dann sagt es gleich, damit wir nicht unsere Zeit verschwenden.", completion = "Ich gebe zu, ich hätte nicht erwartet, Euch lebendig wiederzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66410] = { id = 66410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechtester Eindruck", description = "<Hakota dreht die Trophäe in der Hand und umschließt sie dann. Seine Miene verzieht sich.>\n\nDas ist also aus uns geworden. Ein Fremdling schafft für uns an einem einzigen Tag mehr als unser Häuptling seit Wochen.\n\nKommt. Ich bringe Euch zu ihm.\n\nVielleicht ist das der Tritt in den Allerwertesten, den er braucht.", sourceObjective = "Sprecht mit Tutaqan.", progress = "Was wollt Ihr von uns?", completion = "<Tutaqan wirft die Trophäe erschöpft und desinteressiert zu Boden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66411] = { id = 66411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgewühltes Wasser", description = "Es ist zwar traurig, unseren Häuptling in diesem Zustand zu sehen, aber wir können nicht warten.\n\nWir leben seit Generationen vom Fluss. Aber je weiter die Djaradin vordringen, desto weiter zieht sich der Fluss zurück. Und alle Lebewesen kämpfen miteinander um Raum und Ressourcen. \n\nOhne Wachen kommen unsere Angler nicht weit genug raus, um zu fischen. Unsere Nahrungsvorräte werden täglich knapper.\n\nIhr seht allerdings nicht so aus, als würdet Ihr Schutz brauchen. Nehmt dieses Netz und fangt im Fluss so viele Fische, wie Ihr könnt. Fleisch von den Krabben in der Umgebung ist ebenfalls gern gesehen.", sourceObjective = "Sammelt 10 |4Warmwasserflussfisch:Warmwasserflussfische; und 6 |4saftiges Schnapperfilet:saftige Schnapperfilets;.", progress = "Der Fluss war einst schön und reich an Gaben. Ich bete, dass diese Gaben irgendwann zurückkehren.", completion = "Zumindest müssen unsere Kinder nicht hungern, während unser Häuptling seine Pflichten vernachlässigt. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66412] = { id = 66412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiter so, Blattington", description = "Eine Bitte hätte dieser alte Drakonid noch an Euch, bevor Ihr geht.\n\nFrüher, als Fürst Blattington und ich uns gerade kennengelernt hatten, gingen wir zusammen auf alle möglichen Abenteuer. Ich glaube, dass er deshalb immer davonzieht. Ihm fehlt das Erkunden.\n\nLeider kann ich ihm das nicht mehr ermöglichen, Ihr aber schon! Ich weiß, Ihr könntet ihn an Orte bringen, die ich mir nicht mal erträumen kann.\n\nWir sollten Blattington allerdings vorher fragen, was er davon hält.", sourceObjective = "Sprecht mit Blattington in den Gärten.", completion = "Ich bin neidisch auf ihn, um ehrlich zu sein. Noch einmal jung sein und die Welt erkunden... Ihr müsst mich besuchen, irgendwann, um mir zu berichten, was er so anstellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66413] = { id = 66413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übergreifende Hitze", description = "<Dieser Fisch ist eindeutig schon seit einiger Zeit tot.\n\nBei genauerer Betrachtung fällt Euch auf, dass er fast gar gekocht wurde... wahrscheinlich, während er noch lebendig im Fluss war.\n\nUnujaak im Dorf könnte daran interessiert sein.>", sourceObjective = "Bringt den halbgaren Fisch zum Ältesten Unujaak.", completion = "Oacha'noa schütze uns! Mir schmerzt das Herz, den Fluss in diesem Zustand zu sehen.\n\nDas muss eine weitere Gräueltat der Djaradin sein. Ihre Feuermagie hat den Fluss auf Temperaturen erhitzt, die diese armen Kreaturen einfach nicht ertragen können.\n\nAber es wäre respektlos, das einfach wegzuschmeißen. Los, werft es in den Topf. Das wird unser Abendbrot.", sourceObjectiveStatus = "unverified-source-field" }
quests[66414] = { id = 66414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle bis auf einen", description = "Ich habe gesehen, was Ihr für das Dorf getan habt. Zu besseren Zeiten hätte ich mich darum gekümmert, aber...\n\n<Tutaqan wirft einen Blick zum Fluss, dann sieht er wieder zu Euch.>\n\nEinige unserer Ottuks sind vor Kurzem verschwunden. Wir glauben, dass sie sich zu nah an das Territorium der Djaradin gewagt haben. Einige wurden gefunden. Keiner war noch am Leben. Wenige noch in einem Stück.\n\nWir konnten meinen Ottuk Ipko nicht finden. Er ist schon seit vielen Jahren mein Jagdpartner. Wenn er...\n\n<Er schüttelt den Kopf.>\n\nBitte... helft mir. Durchsucht den Fluss, ich schaue derweil am Ufer nach.", sourceObjective = "Findet Ipko.", progress = "Ich hätte sie nicht so weit fortgehen lassen sollen...", completion = "Das ist meine Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[66415] = { id = 66415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitten durch", description = "Unujaak hat Euch aufgetragen herzukommen, nicht wahr? Als ich Jäger wurde, war er es, der mit dabei geholfen hat, Ipko zu finden... wobei er wohl eher Ipko dabei geholfen hat, mich zu finden. Sie wählen und wir werden eher auserwählt.\n\nEr leidet. Sie alle leiden meinetwegen. Ich weiß, dass sie mich als Anführer brauchen, doch ohne Ipko bin ich nicht der Anführer, der ich sein muss. Wenn ich ihn schon nicht beschützen kann, wie soll ich dann ganz Uktulut beschützen?\n\n<Er atmet tief ein.>\n\nIch kann mir nicht vergeben. Doch ich darf nicht zulassen, dass diese Last mich davon abhält, mit wenigstens einem Fuß auf dem mir auferlegten Pfad zu treten.", sourceObjective = "Helft Tutaqan, einen neuen Ottukbegleiter zu finden.", progress = "Ich wusste, dass es eines Tages passieren würde, doch lindert das den Schmerz keineswegs.", completion = "Nichts kann Ipko ersetzen. Aber Wasser kann nur die Hände füllen, die gewölbt sind, um es zu empfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66417] = { id = 66417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorratssicherung", description = "Pah! Ich kann nicht fassen, dass Tutaqan immer noch Trübsal bläst, wenn wir ihn brauchen, um seine Jäger und Wachen zu befehligen!\n\nWir haben an unserem Anleger mit den Iskaara Handel getrieben, aber jetzt, wo die Djaradin nähergerückt sind und unsere Händler vertrieben haben, ist das komplett in die Hose gegangen. Die Hälfte der Lieferungen des letzten Monats und die meisten unserer Boote sind immer noch auf dem seichten Fluss verschollen.\n\nDie Wachen und Jäger wollen helfen, aber sie haben keine Waffen. Ihr seht aus, als könntet Ihr Euch selbst schützen. Also geht da raus und bringt mir etwas, woraus ich Speere fertigen kann!", sourceObjective = "Sammelt 8 Walknochenfragmente und 30 Stücke durchnässtes Holz.", progress = "Wenn unsere Wachen und Jäger neue Waffen haben, kann ich einen Trupp zusammenstellen, der den Rest holt.", completion = "Das wurde auch Zeit! Sie sind ein bisschen nass, aber ich werde damit viele schöne Waffen herstellen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[66418] = { id = 66418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tuskarrsenal im Test", description = "Die erste Waffe ist fertig! So lange im Fluss zu liegen und dann von dem Feuer der Djaradin erwärmt zu werden, hat die Knochen tatsächlich geschmeidiger gemacht. Den Trick muss ich mir merken!\n\nDa Ihr bisher eine echte Hilfe wart, werde ich Euch gestatten, einige authentische Uktulutwaffen auszutesten. Ihr werdet keine schärferen Klingen oder stabileren Hefte auf dieser Seite der Dracheninseln finden.\n\nProbiert sie auf unserem Übungsplatz für mich aus. Vielleicht erinnert das den Häuptling daran, wie richtiges Kämpfen aussieht! Ha!", sourceObjective = "Nehmt den Knochenspeer von Uktulut und zerstört 4 Trainingsattrappen der Tuskarr.", progress = "Unser Trainingsgebiet ist gleich oben auf dem Hügel. Geht sicher, dass diese Waffen geeignet sind, ein paar Djaradin den Schädel einzuschlagen.", completion = "Haha! Ich habe den Tumult bis hier herüber gehört!\n\nWenn das Geschwätz Tutaqan nicht wieder in Gang bringt, weiß ich nicht, was sonst.\n\nZumindest werden unsere Jäger alle Waffen haben, die sie benötigen, um unser Dorf zu verteidigen... mit oder ohne Tutaqans Hilfe. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66419] = { id = 66419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle für Einen" }
quests[66420] = { id = 66420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prost!", description = "Nachdem wir die Waren jetzt wiederhaben, ist es an der Zeit, alles Übrige in Ordnung zu bringen.\n\nAls hier so viel los war, dachte sich ein Teil meiner Crew wohl, sie könnten einfach verschwinden und ausgiebige Essenspausen einlegen. Seht, ob Ihr sie finden und wieder herbringen könnt.\n\nWenn die Arbeit GETAN ist, können wir alle feiern.", sourceObjective = "Werft mit brackigem Meerwasser nach 3 Arbeitern in Sturmwind.", completion = "Gute Arbeit! Jetzt, wo wir alle wieder arbeiten, kommen wir auch voran.", sourceObjectiveStatus = "unverified-source-field" }
quests[66421] = { id = 66421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sturmschneise" }
quests[66422] = { id = 66422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Expedition geht weiter!", description = "Eine antike Stätte, eine Organisation mit rätselhaften Motivationen... selbst Rannans I.R.R.E. und ihre Analysen...\n\nDas alles weckt den Entdecker in mir.\n\nWir müssen mehr darüber herausfinden, was hier vor sich geht.\n\nIm Süden gibt es eine Treppe, die hoch zu einem Turm führt. Gehen wir schnell weiter.", sourceObjective = "Trefft Rannan und Lathos beim Turm.", completion = "Diese Splitterflammen sind nicht durch meine Hand gestorben... oder durch Rannans \"Spezialität\".\n\nSie waren bereits tot, als wir hier ankamen.\n\nRannan glaubt, dass sie mehrere traumatische Wunden durch arkane Energie erlitten haben.\n\nIch schließe mich seinen Beobachtungen an. Aber es nicht klar, ob die Drachenkonsole oder Eigenbeschuss dafür verantwortlich waren...", sourceObjectiveStatus = "unverified-source-field" }
quests[66423] = { id = 66423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sorgen und Bestätigungen", description = "Die Tode dieser Splitterflammen verdeutlichen, wie gefährlich die Ruinen von Karnthar sind.\n\nAber Rannan glaubt, dass die I.R.R.E. mit einigen Modifikationen dennoch die Energien dort zu bändigen vermag.\n\nWieder einmal behandeln wir nur die Symptome und nicht die Ursache.\n\nDurchsucht die Ruinen nach Hinweisen und versucht herauszufinden, was ihr ursprünglicher Nutzen war. Und beeilt Euch, {name}. Wir haben womöglich nicht genügend Zeit.", sourceObjective = "Findet Hinweise auf den Ursprung der Ruinen.", completion = "Das ist... gar nicht gut.\n\nWenn selbst Sindragosa Karnthar nicht kontrollieren konnte und befohlen hat, diese Position aufzugeben, dann möchte ich mir nicht vorstellen, was für schändliche Dinge die Splitterflammen damit anstellen können.\n\nWir dürfen den Ort nicht in ihre Hände fallen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66425] = { id = 66425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Überladung", description = "Na bitte, fertig!\n\nHier ist die I.R.R.E.R.!\n\nTA TA TAAAA!\n\nIch habe sie auf die Frequenz der Energie um die Drachenkonsolen herum kalibriert und mit einer Glyphe der Bannmagie versehen.\n\nDie I.R.R.E.R wird die Arkanenergie bannen und die Drachenkonsole ausschalten, aber die Glyphe wird mit jeder Nutzung schwächer.\n\nZiemlich praktisch, nicht wahr?\n\nIch habe vier dieser Konsolen in unserer Nähe entdeckt. Schaltet sie ab!", sourceObjective = "Helft Rannan, die arkanen Blasen zu entfernen.", completion = "Ihr habt es geschafft, {name}!\n\nNaja, Ihr und die I.R.R.E.R...\n\nWie auch immer, jetzt helft mir, Lathos zurück ins Lager im Nirgendwo zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66426] = { id = 66426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit läuft davon", sourceObjective = "Erreicht den Ostturm.", completion = "Es ist schlimmer, als wir dachten. Die arkane Energie hat fast ihren Höhepunkt erreicht.\n\nIrgendetwas beschleunigt den Prozess.", sourceObjectiveStatus = "unverified-source-field" }
quests[66427] = { id = 66427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine lauernde Bedrohung", description = "Die arkanen Wunden, die ich erlitten habe, können auf dem Schlachtfeld nicht geheilt werden. Ich fürchte, sie sind zu schwer, als dass ich kämpfen könnte.\n\nIch muss Euch schon wieder um Hilfe bitten, {name}.\n\nIhr müsst Tharohn finden und sie daran hindern, weitere Konsolen zu überladen.\n\nDadurch verschafft Ihr Rannan ein paar wertvolle Augenblicke, um die I.R.R.E. zu kalibrieren... I.R.R.E.R. Wie auch immer er es gerade nennt.\n\nVielleicht können wir die Machenschaften der Splitterflammen dann vereiteln.", sourceObjective = "Tötet Tharohn.", completion = "Es ist also vollbracht.\n\nJetzt hängt alles von Rannan ab. Ich vertraue auf seine Fähigkeiten. Sie haben uns immerhin bis hierher gebracht...", sourceObjectiveStatus = "unverified-source-field" }
quests[66428] = { id = 66428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freundschaft gesichert", description = "Perfekt! Die I.R.R.E.S.T. ist kalibriert und bereit für den Einsatz! Durch Euch!\n\nWarum ich sie nicht benutze? Ganz einfach!\n\nMan muss alle Eventualitäten in Betracht ziehen.\n\nNehmen wir an, sie würde explodieren. Wer würde sie reparieren, wenn ich verletzt, bewusstlos oder tot bin? Könnt Ihr Euch das vorstellen?\n\nUnd jetzt geht und bannt die Barriere, damit wir ins Lager zurückkehren und Lathos versorgen können. Ich werde... mich im Hintergrund halten.", sourceObjective = "Verwendet die I.R.R.E.S.T., um die arkane Barriere zu entfernen.", progress = "Wird dieser Tag denn je besser?", completion = "Er ist... fort? Einfach so?\n\nEr hat sein Leben gegeben, weil die I.R... weil die Maschine nicht funktioniert hat.\n\nLathos hat an mich geglaubt... Ich hätte auf ihn hören sollen... Ich habe ihn im Stich gelassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[66429] = { id = 66429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In ewiger Erinnerung", sourceObjective = "Trefft Rannan beim Lager im Nirgendwo.", completion = "Erst ganz am Ende begann ich Lathos zu schätzen. Ich hielt seine Geduld und Erfahrung für selbstverständlich.\n\nWir verdanken ihm unsere Leben.\n\n<Rannan blickt in Richtung der Ruinen von Karnthar.>\n\nIch werde ihn nie vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66431] = { id = 66431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Trauer", description = "Das hätte nicht passieren müssen. Diese feigen Djaradin... unsere Ottuks abzuschlachten und sie ihren verdorbenen Bestien zu überlassen, damit diese sie ausweiden...\n\nIch nehme Tutaqans Trauer nicht auf die leichte Schulter, aber ich mache mir Sorgen um die Zukunft unserer Leute, wenn er zu lange in seinen dunklen Gedanken und Trauer schwelgt.\n\nWir müssen handeln.\n\nWie es scheint, ist er zum Ausguck über uns aufgebrochen. Ihr habt ihm an diesem Tag einen großen Gefallen getan. Vielleicht könnt Ihr zu ihm durchdringen. Bitte, tut, was Ihr könnt.", sourceObjective = "Versucht, Tutaqan zu helfen.", completion = "<Tutaqan reibt sich mit beiden Händen das Gesicht und seufzt tief. Er sieht erschöpft aus.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66435] = { id = 66435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergungsunternehmung", description = "Als Schamanin habe ich schon mit vielen Elementaren gearbeitet, aber ich habe noch nie solch aggressive Exemplare gesehen!\n\nDie Expedition hat ein Gewölbe der Titanen entdeckt, aber eine Barriere verschließt die innere Kammer. Als wir versucht haben, sie aufzulösen, haben wir wohl einen Sicherheitsmechanismus aktiviert... plötzlich waren wir von wütenden Elementaren umgeben!\n\nAls die Elementare angriffen, waren noch viele unserer Forscher bei den Ausgrabungen. Viele von ihnen sitzen dort fest und KEINER unter ihnen ist ein Kämpfer. \n\nBitte geht dort hinunter und unterstützt ihren Rückzug!", sourceObjective = "Rettet 5 bedrängte Forscher aus den Ruinen des Lebensgewölbes.", completion = "Alle sind sicher innerhalb unserer neuen Grenzen angekommen. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66436] = { id = 66436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgegrabene Unruhestifter", description = "Die Erdelementare versuchen nicht nur, uns zurückzuschlagen, sie zerstören sogar zurückgelassene Artefakte und Ausrüstung! Es ist, als hätte man sie programmiert, alles Titanische zu zerstören...\n\nSolange wir uns gegen sie verteidigen müssen, können wir diese Stätte nicht weiter studieren. Bitte helft uns, sie zu vertreiben!", sourceObjective = "Tötet 12 Erdelementare in den Ruinen des Lebensgewölbes.", progress = "Der Elementar hat uns überrascht! Seid vorsichtig!", completion = "Das sollte ausreichen, um unsere Position zu sichern. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66437] = { id = 66437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schlüsselelement", description = "<Diese Erdkugel pulsiert vor Energie>\n\n<Elementaristin Taiyang weiß vielleicht etwas damit anzufangen.>", sourceObjective = "Bringt die Kugel des Ursteins zu Elementaristin Taiyang in den Ruinen des Lebensgewölbes.\n\nBereitgestellter Gegenstand:", completion = "Ich kann die Elementarenergie in dieser Kugel spüren. Ihr habt möglicherweise eine Lösung für unsere Probleme gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[66438] = { id = 66438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgehobene Ziele", description = "Luft ist ein mächtiges Element. Es schneidet durch Fels und bläht die Segel, um uns an unser Ziel zu bringen.\n\nMeine Hypothese ist, dass die Luft besonders effektiv sein wird, wenn wir diese Barriere durchbrechen wollen. Es ist wirklich ganz einfach.\n\nMeine Späher haben die Kugel der Urstürme aufgespürt. Späherin Ri'tal kann Euch zu ihr führen. Ihr findet sie in der Nähe der Flunkerhöhle. Schnell!", sourceObjective = "Findet Späherin Ri'tal in der Flunkerhöhle.", progress = "Habt Ihr die Späherin gefunden?", completion = "Tae'shara ist sich für viele Aufgaben zu fein, sie delegiert lieber. Ich kann verstehen, warum die Kugel der Urstürme sie interessiert. Ich behalte sie für den Moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[66439] = { id = 66439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnellfeuerpläne", description = "Elementarkugeln, hm? Wenn es Erde gibt, gibt's auch Feuer!\n\nDie Primalisten drüben bei den Flunkernestern formen das Land mit Lava. Wenn irgendjemand Interesse an einer Kugel der Urflammen hat, dann sind sie es.\n\nSchaltet sie aus und seht, ob sie etwas Nützliches haben!", sourceObjective = "Sammelt Urflammenfragmente von Streitkräften der Primalisten in der Flunkerhöhle.", progress = "Acadia hatte eine Spur zur Kugel der Urflammen. Habt Ihr sie gefunden?", completion = "Ah, die Kugel der Urflammen. Sie ist so feurig und strahlend wie Acadia. Ich behalte sie für den Moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[66440] = { id = 66440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abschluss", description = "Ich weiß nicht, was ich sagen soll. Ich wusste nicht, dass der Schmerz des Häuptlings so tief sitzt.\n\nAber es ergibt Sinn. Ottuks sind für unsere Leute keine Haustiere, besonders nicht für Jäger wie unseren Häuptling. Sie sind unsere Freunde, unsere Begleiter... sogar Familienmitglieder.\n\nIpko war Tutaqans erster und einziger Ottuk. Für Jäger von Uktulut ist diese Bindung heilig.\n\nIch werde dafür sorgen, dass sein Übergang in das Reich unserer Vorfahren friedlich ist.", sourceObjective = "Sprecht mit Tutaqan.", progress = "Mehr kann ich nicht tun.", completion = "<Tutaqan beißt die Zähne fest zusammen, Tränen steigen ihm in die Augen. Er sieht Euch nicht an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66441] = { id = 66441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destillierte Anstrengungen", description = "Die Kugel des Ursteins ist ein glücklicher Fund, aber Acadia und Tae'shara haben widersprüchliche Thesen, was die Barriere betrifft.\n\nIch habe meine eigene Vermutung. Vielleicht kommen wir der Antwort mit weiteren Kugeln der Elemente näher.\n\nEiner der Forscher hat einen übergroßen Wasserelementar in einer nahe gelegenen Höhle entdeckt. Besiegt den Elementar, vielleicht findet Ihr bei ihm eine weitere Kugel.", sourceObjective = "Tötet Assquian in der Höhle östlich der Ruinen des Lebensgewölbes.", progress = "Hatte der Elementar eine weitere Kugel?", completion = "Wir müssen wie das Wasser sein, stets bereit, uns anzupassen. Habt Dank, dass Ihr die Kugel der Urwellen zu mir zurückgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
